import type { Context } from '@deepseek-ai/cordis'

export const name = 'timers'

export function apply(ctx: Context) {
  ctx.effect(() => {
    const timer = setInterval(() => {
      console.log('A 心跳')
    }, 100)
    // 资源名
    return () => {
      clearInterval(timer)
      console.log('A 清理')
    }
  }, 'timer-A')

  ctx.effect(() => {
    const timer = setInterval(() => {
      console.log('B 心跳')
    }, 100)
    return () => {
      clearInterval(timer)
      console.log('B 清理')
    }
  }, 'timer-B')

  // 2 秒后手动卸载自己
  setTimeout(async () => {
    console.log('--- 主动卸载插件 ---')
    await ctx.fiber.dispose()
    console.log('--- 卸载完成，进程退出 ---')
  }, 2000)
}

import { Service, type Context } from '@deepseek-ai/cordis'

declare module '@deepseek-ai/cordis' {
  interface Context {
    counter: Counter
  }
}

// Counter 是一个"挂到 ctx 上的具名 API"
export class Counter extends Service {
  private count = 0

  constructor(ctx: Context) {
    super(ctx, 'counter')
  }

  increment() {
    return ++this.count
  }

  get value() {
    return this.count
  }
}

export const name = 'counter'

export function apply(ctx: Context) {
  ctx.plugin(Counter)
}

