import { Service, type Context } from '@deepseek-ai/cordis'

declare module '@deepseek-ai/cordis' {
  interface Context {
    diagnose: Diagnose
  }
  interface Events {
    'diagnose/report'(lines: string[]): void
  }
}

export class Diagnose extends Service {
  constructor(ctx: Context) {
    super(ctx, 'diagnose')
  }

  /** 汇总当前所有插件的状态 */
  report() {
    const lines: string[] = []
    for (const runtime of this.ctx.registry.values()) {
      for (const fiber of runtime.fibers) {
        const state = ['PENDING', 'LOADING', 'ACTIVE', 'FAILED', 'UNLOADING', 'DISPOSED'][fiber.state] ?? fiber.state
        lines.push(`${runtime.name ?? '(匿名)'}: ${state}`)
      }
    }
    this.ctx.emit('diagnose/report', lines)
    return lines
  }
}

export const name = 'diagnose-service'

export function apply(ctx: Context) {
  ctx.plugin(Diagnose)
}

import type { Context } from '@deepseek-ai/cordis'
import type {} from './diagnose.ts'

export const name = 'main'

export const inject = ['diagnose']

// FiberState：0 PENDING / 1 LOADING / 2 ACTIVE / 3 FAILED / 4 UNLOADING / 5 DISPOSED

// 一个构造时就抛错的插件，用来看 FAILED 状态
export class BrokenPlugin {
  constructor(public ctx: Context) {
    throw new Error('boom：我在构造时炸了')
  }
}

export function apply(ctx: Context) {
  ctx.on('diagnose/report', (lines) => {
    console.log('=== 插件状态 ===')
    for (const line of lines) console.log(line)
  })

  // 1. 正常看一眼
  ctx.diagnose.report()

  // 2. 再加载一个会炸的插件，看它怎么变成 FAILED
  setTimeout(async () => {
    console.log('\n=== 加载一个会抛错的插件 ===')
    const fiber = ctx.plugin(BrokenPlugin)
    await fiber.await().catch((error) => {
      console.log('捕获到错误：', (error as Error).message)
    })
    console.log('\n=== 故障后重新看一眼 ===')
    ctx.diagnose.report()
  }, 100)
}

import { Service, type Context } from '@deepseek-ai/cordis'

declare module '@deepseek-ai/cordis' {
  interface Context {
    llm: Llm
  }
  interface Events {
    /** 消费方向 llm 服务发出一次请求，由提供方处理。 */
    'llm/generate'(input: string): void
  }
}

/**
 * 模型输出被切成一块一块的"流式碎片"（chunk），每条都是下面联合类型的一员。
 * 用 TS 的判别联合：每种 chunk 用 `type` 区分，`type` 叫"判别标签"。
 */
export type StreamChunk =
  /** 一个内容块开始：`blockType` 是 'text'（文字）或 'tool-call'（工具调用）。 */
  | { type: 'block-start'; index: number; blockType: 'text' | 'tool-call' }
  /** 文字流进来一小段。 */
  | { type: 'text-delta'; index: number; text: string }
  /** 模型"思考过程"流进来一小段。 */
  | { type: 'reasoning-delta'; index: number; text: string }
  /** 一次工具调用的参数（JSON 字符串）流进来一小段。 */
  | { type: 'tool-call-delta'; index: number; id: string; name?: string; argumentsDelta: string }
  /** 一个内容块结束，`block` 是拼装好的完整内容。 */
  | { type: 'block-end'; index: number; block: ContentBlock }
  /** 本次调用的 token 用量。 */
  | { type: 'usage'; usage: { inputTokens: number; outputTokens: number } }
  /** 本次调用结束，`reason.kind` 说明为什么结束。 */
  | { type: 'finish'; reason: { kind: 'stop' | 'tool-calls' | 'max-tokens' | 'error' } }

/** 拼装完成的内容块：要么是一段文字，要么是一次工具调用。 */
export type ContentBlock =
  | { type: 'text'; text: string }
  | { type: 'tool-call'; id: string; name: string; arguments: string }

/** 一次模型请求里，消费方真正关心的部分。 */
export interface GenerateOptions {
  /** 对话历史，最后一条是 user。工具返回的结果也会以一条历史的形式进来。 */
  messages: { role: 'system' | 'user' | 'assistant' | 'tool'; content: string }[]
  /** 希望模型别超过多少输出 token。 */
  maxTokens?: number
  /** 取消信号：上层想中断这次请求时 abort 它。 */
  signal?: AbortSignal
}

/**
 * Service Definition：定义"调用模型"这个能力的词汇。
 * 和上一课的 Notifier 一样：只定义，不实现。
 * `ctx.llm` 拿到的就是这个类型，所以提供方必须继承它。
 */
export abstract class Llm extends Service {
  constructor(ctx: Context) {
    super(ctx, 'llm')
  }

  /**
   * 唯一必须实现的方法：把请求变成一个"异步可迭代"的碎片流。
   * `async function*`（异步生成器）写起来最省事，它天然就是 AsyncIterable。
   * 约定：先 yield `usage`，最后 yield `finish`。
   */
  abstract stream(options: GenerateOptions): AsyncIterable<StreamChunk>
}

import type { Context } from '@deepseek-ai/cordis'
import type { ContentBlock, GenerateOptions, StreamChunk } from './llm.ts'

export const name = 'consumer'

// 没有这一行，ctx.llm 会抛 "cannot get property "llm" without inject"（第 03 课讲过）
export const inject = ['llm']

// Consumer：只依赖抽象 Llm，不知道背后是假模型还是真 API
export function apply(ctx: Context) {
  ctx.on('llm/generate', (input) => {
    void run(input)
  })

  // 三次调用，把三段剧本依次演完
  ctx.emit('llm/generate', '你好')
  setTimeout(() => ctx.emit('llm/generate', '现在几点了？'), 50)
  setTimeout(() => ctx.emit('llm/generate', '第二篇我们会学工具'), 100)

  async function run(input: string) {
    const options: GenerateOptions = {
      messages: [{ role: 'user', content: input }],
    }

    // 消费方只面向抽象：Iterable 的迭代协议让它不必知道 chunk 从哪来
    for await (const chunk of ctx.llm.stream(options)) {
      print(chunk)
    }
  }

  function print(chunk: StreamChunk) {
    switch (chunk.type) {
      case 'block-start':
        console.log(`--- 内容块开始（${chunk.blockType}）---`)
        break
      case 'text-delta':
        process.stdout.write(chunk.text)
        break
      case 'reasoning-delta':
        process.stdout.write(`[思考] ${chunk.text}`)
        break
      case 'tool-call-delta':
        console.log(`[工具调用片段] id=${chunk.id} name=${chunk.name ?? '(同上)'} 参数=${chunk.argumentsDelta}`)
        break
      case 'block-end':
        console.log(`\n--- 内容块结束：${formatBlock(chunk.block)} ---`)
        break
      case 'usage':
        console.log(`[用量] 输入 ${chunk.usage.inputTokens} / 输出 ${chunk.usage.outputTokens} tokens`)
        break
      case 'finish':
        console.log(`[结束] 原因：${chunk.reason.kind}`)
        break
    }
  }
}

function formatBlock(block: ContentBlock) {
  switch (block.type) {
    case 'text':
      return `文字 "${block.text}"`
    case 'tool-call':
      return `工具 ${block.name}(${block.arguments})`
  }
}

import type { Context } from '@deepseek-ai/cordis'
import { Llm, type GenerateOptions, type StreamChunk } from './llm.ts'

/** 把一段文字切成"标准流式回复"，照着 harness 测试里的 textResponse 写的。 */
export function textResponse(text: string): StreamChunk[] {
  return [
    { type: 'block-start', index: 0, blockType: 'text' },
    // 一个字符一条 delta，模拟真实模型逐字吐字
    ...Array.from(text, (char): StreamChunk => ({ type: 'text-delta', index: 0, text: char })),
    { type: 'block-end', index: 0, block: { type: 'text', text } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: text.length } },
    { type: 'finish', reason: { kind: 'stop' } },
  ]
}

/** 把一次工具调用切成"标准流式回复"，参数按 JSON 字符串分两段流出。 */
export function toolCallResponse(id: string, name: string, args: object): StreamChunk[] {
  const argumentsJson = JSON.stringify(args)
  return [
    { type: 'block-start', index: 0, blockType: 'tool-call' },
    { type: 'tool-call-delta', index: 0, id, name, argumentsDelta: argumentsJson.slice(0, 5) },
    { type: 'tool-call-delta', index: 0, id, argumentsDelta: argumentsJson.slice(5) },
    { type: 'block-end', index: 0, block: { type: 'tool-call', id, name, arguments: argumentsJson } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: 5 } },
    { type: 'finish', reason: { kind: 'tool-calls' } },
  ]
}

export const name = 'llm-mock'

/**
 * Service Provider：一个脚本化的假模型。
 * 每被调用一次，就从剧本（script）里取下一段剧本吐出去——像复读机，但复读的是你写好的内容。
 */
export class MockAdapter extends Llm {
  constructor(
    ctx: Context,
    private script: (StreamChunk[] | ((options: GenerateOptions) => StreamChunk[]))[],
  ) {
    super(ctx)
  }

  async *stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const entry = this.script.shift()
    if (!entry) throw new Error('MockAdapter: 剧本用完了')
    const chunks = typeof entry === 'function' ? entry(options) : entry
    for (const chunk of chunks) {
      yield chunk
    }
  }
}

export function apply(ctx: Context) {
  // 三段剧本：先纯文字，再工具调用，再根据输入动态决定
  ctx.plugin(MockAdapter, [
    textResponse('你好，我是假模型。'),
    toolCallResponse('call-1', 'get_weather', { city: '北京' }),
    (options) => {
      const last = options.messages.at(-1)?.content ?? ''
      return textResponse(`你刚才说：${last}`)
    },
  ])
}

﻿/**
 * 简化版 defineTool。
 *
 * harness 真身（packages/core/tools/src/schema.ts）在这里做了三层事：
 * 1. 把手写的 JSON Schema DSL 编译成标准 JSON Schema，并用它校验模型传来的参数；
 * 2. 从 DSL 反推出 TypeScript 类型，让 execute 里的 args 有补全；
 * 3. 用 ctx.effect 管理注册，插件卸载时工具自动消失。
 *
 * 本课先做第 3 件事，把"注册"这条链路跑通。校验和类型推导留到第 11 课。
 */

/** 模型传来的参数：一个 JSON 对象。 */
export type ToolArgs = Record<string, unknown>

/** 参数 schema：一棵 JSON Schema 树。 */
export type ToolParameters = Record<string, unknown>

/** 执行上下文：harness 真身叫 ToolRunContext，这里只保留两个字段。 */
export interface ToolRunContext {
  /** 本次调用的 id，由注册表分配。 */
  readonly callId: string
  /** 取消信号：调用方 abort 时，工具应当尽快收手。 */
  readonly signal?: AbortSignal
}

/** 一个工具的完整定义。 */
export interface ToolDefinition {
  readonly name: string
  /** 写给模型看的说明，模型据此决定要不要调用它。 */
  readonly description: string
  /** 参数结构说明（第 11 课细讲）。 */
  readonly parameters: ToolParameters
  /** 具体干活的部分。 */
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}

/** 一次工具调用的结果。成功失败都走这个壳，不抛异常。 */
export type ToolResult =
  | { ok: true; callId: string; name: string; value: unknown }
  | { ok: false; callId: string; name: string; error: string }

export interface DefineToolOptions {
  name: string
  description: string
  parameters?: Record<string, unknown>
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}

/** 定义工具。真身在 harness 里还会做校验和类型推导，这里只做组装。 */
export function defineTool(options: DefineToolOptions): ToolDefinition {
  return {
    name: options.name,
    description: options.description,
    parameters: options.parameters ?? {},
    execute: options.execute,
  }
}

import type { Context } from '@deepseek-ai/cordis'

// 自定义事件必须在 declare module 里登记（第 04 课），
// 否则 ctx.emit / ctx.on 会因类型对不上而编译不过。
declare module '@deepseek-ai/cordis' {
  interface Events {
    /** 用户说了一句话，agent 处理一轮。 */
    'agent/turn'(input: string): void
  }
}

export const name = 'agent'

// 没有这一行，ctx.tools 会抛 "cannot get property "tools" without inject"（第 03 课）
export const inject = ['tools']

/**
 * Consumer：模拟 agent loop 里"模型决定调工具"的那一步。
 *
 * 它不知道有哪些工具，只从 ctx.tools 里查、然后调。
 */
export function apply(ctx: Context) {
  ctx.on('agent/turn', async (input) => {
    console.log(`\n=== 用户说：${input} ===`)

    // 1. 把工具清单打印出来——模型拿到的就是这些文字
    for (const definition of ctx.tools.list()) {
      console.log(`[可用工具] ${definition.name} — ${definition.description}`)
    }

    // 2. 假模型"决定"调 get_weather（真模型是在输出里给出 tool-call）
    const call = matchTool(input)
    if (!call) {
      console.log('[模型] 这个问题不用工具，直接回答。')
      return
    }
    console.log(`[模型决定] 调用 ${call.name}，参数 ${JSON.stringify(call.args)}`)

    // 3. 真正执行，结果无论成败都收进壳里
    const result = await ctx.tools.call(call.name, call.args)
    if (result.ok) {
      console.log(`[工具返回] ${String(result.value)}`)
    } else {
      console.log(`[工具失败] ${result.error}`)
    }
  })

  // 三次"对话"。全部延迟触发：apply 是同步执行的，
  // 此刻 weather.ts 可能还没加载完，马上 emit 会看不到工具。
  setTimeout(() => ctx.emit('agent/turn', '北京天气怎么样？'), 50)
  setTimeout(() => ctx.emit('agent/turn', '你好呀'), 100)
  setTimeout(() => ctx.emit('agent/turn', '查一下天气'), 150)
}

/** 假模型的"决策"：看输入里有没有城市名或"天气"两个字。 */
function matchTool(input: string) {
  const cities = ['北京', '上海']
  const city = cities.find((name) => input.includes(name))
  if (city) return { name: 'get_weather', args: { city } }
  if (input.includes('天气')) return { name: 'get_weather', args: { city: '北京' } }
  return null
}

﻿import type { Context } from '@deepseek-ai/cordis'
import { Tools, type ToolSchema } from './tools.ts'
import type { ToolArgs, ToolDefinition, ToolResult } from './define-tool.ts'

export const name = 'tools-registry'

/**
 * Service Provider：一个基于 Map 的工具注册表。
 *
 * register() 是第 02 课的"注册即效果"：注册方插件一卸载，
 * 这个工具定义自动从表里消失。
