   * `execute` 是本地代码，发给模型没有意义，还可能泄露实现细节。
   * harness 真身 [packages/core/tools/src/index.ts 第 1260 行](../../../deepseek-harness/packages/core/tools/src/index.ts#L1260)
   * 的 `schemas()` 干的就是这件事，注释里那词叫 allowlist（白名单）。
   */
  abstract schemas(): ToolSchema[]

  /** 执行一个工具；任何失败都收进 ToolResult，不往外抛。 */
  abstract call(name: string, args: unknown): Promise<ToolResult>
}

/** 递给模型看的工具描述：三个字段，缺一不可。 */
export interface ToolSchema {
  readonly name: string
  readonly description: string
  readonly parameters: ToolParameters
}

import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from './define-tool.ts'

export const name = 'weather-tool'

// 忘了这行，ctx.tools 会抛 "cannot get property "tools" without inject"
// （第 03 课的规矩：要拿 ctx 上的服务，必须先声明 inject）
export const inject = ['tools']

/**
 * Service Provider 的角色之一：往 ctx.tools 里放一个工具。
 *
 * 真身（packages/web/tool-web/src/search.ts）长这样：
 *   ctx.tools.register(defineTool({ name: 'web_search', ... }))
 * 我们连形状都照抄，只是把网络请求换成了假数据。
 */
export function apply(ctx: Context) {
  ctx.tools.register(defineTool({
    name: 'get_weather',
    description: '查询一个城市的天气。需要城市名。',
    parameters: {
      city: {
        type: 'string',
        required: true,
        description: '城市名，例如 "北京"',
      },
      unit: {
        type: 'string',
        enum: ['celsius', 'fahrenheit'],
        description: '温度单位，默认摄氏度。',
      },
    },
    async execute(args) {
      const city = String(args.city ?? '')
      // Keyless：假数据，不联网
      const table: Record<string, string> = {
        北京: '晴，12°C',
        上海: '小雨，18°C',
      }
      const forecast = table[city] ?? '晴，20°C（默认值）'
      const unit = args.unit === 'fahrenheit' ? '（已换算为华氏）' : ''
      return `${city}：${forecast}${unit}`
    },
  }))
}

﻿/**
 * 简化版 defineTool。
 *
 * harness 真身（packages/core/tools/src/schema.ts 第 554 行）在这里做三件事：
 * 1. 把手写的 JSON Schema DSL 编译成标准 JSON Schema，并用它校验模型传来的参数；
 * 2. 从 DSL 反推出 TypeScript 类型，让 execute 里的 args 有补全；
 * 3. 把校验包在 execute 外层，任何违规都以 ToolArgsError 的形式抛出。
 *
 * 第 10 课只做了"组装"。本课补上第 1 和第 3 件事——**校验**。
 */

import { compileNode, ToolArgsError, validateValue, type JsonSchemaNode, type SchemaSpec } from './json-schema.ts'

/** 模型传来的参数：一个 JSON 对象。 */
export type ToolArgs = Record<string, unknown>

/** 参数 schema：一棵 JSON Schema 树。 */
export type ToolParameters = Record<string, unknown>

/** 执行上下文：harness 真身叫 ToolRunContext，这里只保留两个字段。 */
export interface ToolRunContext {
  /** 本次调用的 id，由注册表分配。 */
  readonly callId: string
  /** 取消信号：调用方 abort 时，工具应当尽快收手。 */
  readonly signal?: AbortSignal
}

/** 一次工具调用的结果。成功失败都走这个壳，不抛异常。 */
export type ToolResult =
  | { ok: true; callId: string; name: string; value: unknown }
  | { ok: false; callId: string; name: string; error: string }

/** 一个工具的完整定义。 */
export interface ToolDefinition {
  readonly name: string
  /** 写给模型看的说明，模型据此决定要不要调用它。 */
  readonly description: string
  /** 编译后的参数 schema，既校验也进模型请求。 */
  readonly parameters: ToolParameters
  /** 具体干活的部分。参数已通过校验。 */
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}
export interface DefineToolOptions {
  name: string
  description: string
  /** 手写的参数 schema（第 11 课细讲）。 */
  parameters?: Record<string, SchemaSpec>
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}

/**
 * 定义工具。
 * @param options - 工具的名称、说明、参数 schema 和执行体。
 * @returns 一个 registry-ready 的定义，execute 已自带参数校验。
 */
export function defineTool(options: DefineToolOptions): ToolDefinition {
  const compiled = compileParameters(options.parameters)

  return {
    name: options.name,
    description: options.description,
    parameters: compiled,
    async execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> {
      // 校验发生在用户的 execute 之前：不合规的参数根本到不了业务代码
      const violations = validateValue(compiled, args)
      if (violations.length > 0) {
        throw new ToolArgsError(options.name, violations)
      }
      return options.execute(args, exec)
    },
  }
}

/** 把"每个参数一条声明"的手写 DSL 编译成一个对象根的 JSON Schema。 */
function compileParameters(spec: Record<string, SchemaSpec> | undefined): JsonSchemaNode {
  if (spec === undefined) return { type: 'object', additionalProperties: true }
  const node = compileNode({ type: 'object', properties: spec })
  // 顶层参数对象是"开放"的：模型可以额外带字段，不像 output schema 那样严苛
  node.additionalProperties = true
  return node
}

/**
 * 简化版 JSON Schema 校验器。
 *
 * harness 真身在 packages/core/tools/src/json-schema.ts，它只接受一个
 * 受限的 JSON Schema 子集：一个标量 type、对象 properties/required、
 * 布尔 additionalProperties、数组 items、标量 enum/const。任何子集之外的
 * 关键字直接拒绝，而不是"接受但不校验"——因为那会给作者一种虚假的安全感。
 *
 * 本课实现同款子集的教学版。
 */

/** 校验错误：模型传来的参数不符合声明。 */
export class ToolArgsError extends Error {
  constructor(
    readonly toolName: string,
    readonly violations: string[],
  ) {
    super(`invalid arguments: ${violations.join('; ')}`)
    this.name = 'ToolArgsError'
  }
}

/** 手写 DSL 里的一个节点。 */
export type SchemaSpec =
  | { type: 'string'; required?: true; description?: string; enum?: readonly string[] }
  | { type: 'number'; required?: true; description?: string }
  | { type: 'boolean'; required?: true; description?: string }
  | { type: 'array'; required?: true; description?: string; items?: SchemaSpec }
  | { type: 'object'; required?: true; description?: string; additionalProperties?: boolean; properties?: Record<string, SchemaSpec> }

/** 编译后的 JSON Schema 节点（只保留校验需要的字段）。 */
export interface JsonSchemaNode {
  type: string
  description?: string
  enum?: readonly (string | number | boolean | null)[]
  required?: string[]
  additionalProperties?: boolean
  items?: JsonSchemaNode
  properties?: Record<string, JsonSchemaNode>
  /** 允许作为普通 JSON 对象在工具之间传递。 */
  [key: string]: unknown
}

/**
 * 把手写 DSL 的一个节点编译成 JSON Schema。
 * @param spec - 手写 DSL 节点。
 * @returns 编译后的 JSON Schema 节点。
 */
export function compileNode(spec: SchemaSpec): JsonSchemaNode {
  const node: JsonSchemaNode = { type: spec.type }
  if (spec.description !== undefined) node.description = spec.description
  if ('enum' in spec && spec.enum !== undefined) node.enum = spec.enum
  if (spec.type === 'array' && spec.items !== undefined) {
    node.items = compileNode(spec.items)
  }
  if (spec.type === 'object') {
    node.additionalProperties = spec.additionalProperties ?? false
    if (spec.properties !== undefined) {
      node.properties = {}
      node.required = []
      for (const [key, child] of Object.entries(spec.properties)) {
        node.properties[key] = compileNode(child)
        if (child.required === true) node.required.push(key)
      }
      if (node.required.length === 0) delete node.required
    }
  }
  return node
}

/**
 * 校验一个值是否符合编译后的 schema。
 * @param schema - 编译后的 schema。
 * @param value - 待校验的值，任意来源。
 * @param path - 当前路径，用于错误信息定位。
 * @returns 违规列表；空数组表示通过。
 */
export function validateValue(schema: JsonSchemaNode, value: unknown, path = '$'): string[] {
  const violations: string[] = []
  const at = (suffix: string) => suffix === '' ? path : `${path}.${suffix}`

  switch (schema.type) {
    case 'string':
      if (typeof value !== 'string') {
        violations.push(`${at('')} 必须是字符串，收到 ${describe(value)}`)
        break
      }
      if (schema.enum !== undefined && !schema.enum.includes(value)) {
        violations.push(`${at('')} 必须是 ${schema.enum.map((entry) => JSON.stringify(entry)).join(' / ')} 之一`)
      }
      break

    case 'number':
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        violations.push(`${at('')} 必须是数字，收到 ${describe(value)}`)
      }
      break

    case 'boolean':
      if (typeof value !== 'boolean') {
        violations.push(`${at('')} 必须是布尔值，收到 ${describe(value)}`)
      }
      break

    case 'array': {
      if (!Array.isArray(value)) {
        violations.push(`${at('')} 必须是数组，收到 ${describe(value)}`)
        break
      }
      if (schema.items === undefined) break
      value.forEach((entry, index) => {
        violations.push(...validateValue(schema.items!, entry, `${path}[${index}]`))
      })
      break
    }

    case 'object': {
      if (typeof value !== 'object' || value === null || Array.isArray(value)) {
        violations.push(`${at('')} 必须是对象，收到 ${describe(value)}`)
        break
      }
      const record = value as Record<string, unknown>
      for (const key of schema.required ?? []) {
        if (record[key] === undefined) {
          violations.push(`${at(key)} 是必填项，但没有提供`)
        }
      }
      for (const [key, child] of Object.entries(schema.properties ?? {})) {
        if (record[key] === undefined) continue
        violations.push(...validateValue(child, record[key], at(key)))
      }
      if (schema.additionalProperties === false) {
        for (const key of Object.keys(record)) {
          if (schema.properties === undefined || !(key in schema.properties)) {
            violations.push(`${at(key)} 不是声明过的字段（additionalProperties: false）`)
          }
        }
      }
      break
    }

    default:
      throw new Error(`不支持的 schema 类型：${schema.type}`)
  }

  return violations
}

/** 把一个未知值描述成一句人能看懂的话，用于错误信息。 */
function describe(value: unknown): string {
  if (value === null) return 'null'
  if (Array.isArray(value)) return '数组'
  if (typeof value === 'object') return '对象'
  return JSON.stringify(value) ?? String(value)
}

