/** 参数 schema：一棵 JSON Schema 树。 */
export type ToolParameters = Record<string, unknown>

/** 执行上下文：harness 真身叫 ToolRunContext，这里只保留两个字段。 */
export interface ToolRunContext {
  /** 本次调用的 id，由注册表分配。 */
  readonly callId: string
  /** 取消信号：调用方 abort 时，工具应当尽快收手。 */
  readonly signal?: AbortSignal
}

/** 一次工具调用的结果。成功失败都走这个壳，不抛异常。 */
export type ToolResult =
  | { ok: true; callId: string; name: string; value: unknown }
  | { ok: false; callId: string; name: string; error: string }

/** 一个工具的完整定义。 */
export interface ToolDefinition {
  readonly name: string
  /** 写给模型看的说明，模型据此决定要不要调用它。 */
  readonly description: string
  /** 编译后的参数 schema，既校验也进模型请求。 */
  readonly parameters: ToolParameters
  /** 具体干活的部分。参数已通过校验。 */
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}
export interface DefineToolOptions {
  name: string
  description: string
  /** 手写的参数 schema（第 11 课细讲）。 */
  parameters?: Record<string, SchemaSpec>
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}

/**
 * 定义工具。
 * @param options - 工具的名称、说明、参数 schema 和执行体。
 * @returns 一个 registry-ready 的定义，execute 已自带参数校验。
 */
export function defineTool(options: DefineToolOptions): ToolDefinition {
  const compiled = compileParameters(options.parameters)

  return {
    name: options.name,
    description: options.description,
    parameters: compiled,
    async execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> {
      // 校验发生在用户的 execute 之前：不合规的参数根本到不了业务代码
      const violations = validateValue(compiled, args)
      if (violations.length > 0) {
        throw new ToolArgsError(options.name, violations)
      }
      return options.execute(args, exec)
    },
  }
}

/** 把"每个参数一条声明"的手写 DSL 编译成一个对象根的 JSON Schema。 */
function compileParameters(spec: Record<string, SchemaSpec> | undefined): JsonSchemaNode {
  if (spec === undefined) return { type: 'object', additionalProperties: true }
  const node = compileNode({ type: 'object', properties: spec })
  // 顶层参数对象是"开放"的：模型可以额外带字段，不像 output schema 那样严苛
  node.additionalProperties = true
  return node
}

/**
 * 简化版 JSON Schema 校验器。
 *
 * harness 真身在 packages/core/tools/src/json-schema.ts，它只接受一个
 * 受限的 JSON Schema 子集：一个标量 type、对象 properties/required、
 * 布尔 additionalProperties、数组 items、标量 enum/const。任何子集之外的
 * 关键字直接拒绝，而不是"接受但不校验"——因为那会给作者一种虚假的安全感。
 *
 * 本课实现同款子集的教学版。
 */

/** 校验错误：模型传来的参数不符合声明。 */
export class ToolArgsError extends Error {
  constructor(
    readonly toolName: string,
    readonly violations: string[],
  ) {
    super(`invalid arguments: ${violations.join('; ')}`)
    this.name = 'ToolArgsError'
  }
}

/** 手写 DSL 里的一个节点。 */
export type SchemaSpec =
  | { type: 'string'; required?: true; description?: string; enum?: readonly string[] }
  | { type: 'number'; required?: true; description?: string }
  | { type: 'boolean'; required?: true; description?: string }
  | { type: 'array'; required?: true; description?: string; items?: SchemaSpec }
  | { type: 'object'; required?: true; description?: string; additionalProperties?: boolean; properties?: Record<string, SchemaSpec> }

/** 编译后的 JSON Schema 节点（只保留校验需要的字段）。 */
export interface JsonSchemaNode {
  type: string
  description?: string
  enum?: readonly (string | number | boolean | null)[]
  required?: string[]
  additionalProperties?: boolean
  items?: JsonSchemaNode
  properties?: Record<string, JsonSchemaNode>
  /** 允许作为普通 JSON 对象在工具之间传递。 */
  [key: string]: unknown
}

/**
 * 把手写 DSL 的一个节点编译成 JSON Schema。
 * @param spec - 手写 DSL 节点。
 * @returns 编译后的 JSON Schema 节点。
 */
export function compileNode(spec: SchemaSpec): JsonSchemaNode {
  const node: JsonSchemaNode = { type: spec.type }
  if (spec.description !== undefined) node.description = spec.description
  if ('enum' in spec && spec.enum !== undefined) node.enum = spec.enum
  if (spec.type === 'array' && spec.items !== undefined) {
    node.items = compileNode(spec.items)
  }
  if (spec.type === 'object') {
    node.additionalProperties = spec.additionalProperties ?? false
    if (spec.properties !== undefined) {
      node.properties = {}
      node.required = []
      for (const [key, child] of Object.entries(spec.properties)) {
        node.properties[key] = compileNode(child)
        if (child.required === true) node.required.push(key)
      }
      if (node.required.length === 0) delete node.required
    }
  }
  return node
}

/**
 * 校验一个值是否符合编译后的 schema。
 * @param schema - 编译后的 schema。
 * @param value - 待校验的值，任意来源。
 * @param path - 当前路径，用于错误信息定位。
 * @returns 违规列表；空数组表示通过。
 */
export function validateValue(schema: JsonSchemaNode, value: unknown, path = '$'): string[] {
  const violations: string[] = []
  const at = (suffix: string) => suffix === '' ? path : `${path}.${suffix}`

  switch (schema.type) {
    case 'string':
      if (typeof value !== 'string') {
        violations.push(`${at('')} 必须是字符串，收到 ${describe(value)}`)
        break
      }
      if (schema.enum !== undefined && !schema.enum.includes(value)) {
        violations.push(`${at('')} 必须是 ${schema.enum.map((entry) => JSON.stringify(entry)).join(' / ')} 之一`)
      }
      break

    case 'number':
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        violations.push(`${at('')} 必须是数字，收到 ${describe(value)}`)
      }
      break

    case 'boolean':
      if (typeof value !== 'boolean') {
        violations.push(`${at('')} 必须是布尔值，收到 ${describe(value)}`)
      }
      break

    case 'array': {
      if (!Array.isArray(value)) {
        violations.push(`${at('')} 必须是数组，收到 ${describe(value)}`)
        break
      }
      if (schema.items === undefined) break
      value.forEach((entry, index) => {
        violations.push(...validateValue(schema.items!, entry, `${path}[${index}]`))
      })
      break
    }

    case 'object': {
      if (typeof value !== 'object' || value === null || Array.isArray(value)) {
        violations.push(`${at('')} 必须是对象，收到 ${describe(value)}`)
        break
      }
      const record = value as Record<string, unknown>
      for (const key of schema.required ?? []) {
        if (record[key] === undefined) {
          violations.push(`${at(key)} 是必填项，但没有提供`)
        }
      }
      for (const [key, child] of Object.entries(schema.properties ?? {})) {
        if (record[key] === undefined) continue
        violations.push(...validateValue(child, record[key], at(key)))
      }
      if (schema.additionalProperties === false) {
        for (const key of Object.keys(record)) {
          if (schema.properties === undefined || !(key in schema.properties)) {
            violations.push(`${at(key)} 不是声明过的字段（additionalProperties: false）`)
          }
        }
      }
      break
    }

    default:
      throw new Error(`不支持的 schema 类型：${schema.type}`)
  }

  return violations
}

/** 把一个未知值描述成一句人能看懂的话，用于错误信息。 */
function describe(value: unknown): string {
  if (value === null) return 'null'
  if (Array.isArray(value)) return '数组'
  if (typeof value === 'object') return '对象'
  return JSON.stringify(value) ?? String(value)
}

import { Service, type Context } from '@deepseek-ai/cordis'

declare module '@deepseek-ai/cordis' {
  interface Context { llm: Llm }
  interface Events {
    /** 消费方向 llm 服务发出一次请求，由提供方处理。 */
    'llm/generate'(input: string): void
  }
}

export type StreamChunk =
  | { type: 'block-start'; index: number; blockType: 'text' | 'tool-call' }
  | { type: 'text-delta'; index: number; text: string }
  | { type: 'reasoning-delta'; index: number; text: string }
  | { type: 'tool-call-delta'; index: number; id: string; name?: string; argumentsDelta: string }
  | { type: 'block-end'; index: number; block: ContentBlock }
  | { type: 'usage'; usage: { inputTokens: number; outputTokens: number } }
  | { type: 'finish'; reason: { kind: 'stop' | 'tool-calls' | 'max-tokens' | 'error' } }

export type ContentBlock =
  | { type: 'text'; text: string }
  | { type: 'tool-call'; id: string; name: string; arguments: string }

export interface GenerateOptions {
  messages: { role: 'system' | 'user' | 'assistant' | 'tool'; content: string }[]
  maxTokens?: number
  signal?: AbortSignal
}

export abstract class Llm extends Service {
  constructor(ctx: Context) { super(ctx, 'llm') }
  abstract stream(options: GenerateOptions): AsyncIterable<StreamChunk>
}

import type { Context } from '@deepseek-ai/cordis'
import type { GenerateOptions, StreamChunk } from './llm.ts'
import type { SessionEventLine } from './session.ts'
import { SECTION_ORDER } from './system-prompt.ts'

declare module '@deepseek-ai/cordis' {
  interface Events {
    /** 用户说了一句话，agent 处理一轮。 */
    'agent/turn'(input: string): void
  }
}

export const name = 'agent'
export const inject = ['llm', 'tools', 'sessionLog', 'systemPrompt']

/** 一轮对话里模型给出的指令：要么说话，要么调工具。 */
type ModelTurn =
  | { kind: 'text'; text: string }
  | { kind: 'tool-call'; id: string; name: string; args: Record<string, unknown> }

/** 上一轮递出去的提示词，用来判断"变没变"。 */
let lastSystem = ''
/** 上一版提示词落在日志的哪一行，换新版时把它顶掉。 */
let lastSystemSeq: number | undefined
/** 身份段的销毁器：换提示词时先撤掉旧的那一段。 */
let disposeIdentity: (() => void) | undefined

/**
 * Consumer：agent loop 的第六版。
 *
 * 前面五版一直在解决"模型知道什么"：工具（12）、失败（13）、
 * 历史（14~15）、长度（16）、跨进程（17）。
 * 本课补上另一半：**谁在告诉模型它该是谁。**
 */
export function apply(ctx: Context) {
  ctx.on('agent/turn', (input) => { void run(input) })

  // 身份：这段话不随对话变化，每一轮请求都带上
  disposeIdentity = ctx.systemPrompt.section({
    name: 'agent:identity',
    order: SECTION_ORDER.identity,
    text: '你是一个天气助手，只回答天气相关的问题。',
  })
  // 人设：部署方给定的行为准则。真身里这来自 cordis.yml 的 personaPrefix
  ctx.systemPrompt.section({
    name: 'agent:persona',
    order: SECTION_ORDER.persona,
    text: '回答时语气礼貌，不确定就明说。',
  })
  // 工具清单：**函数形式**，每轮请求现算。
  // 它注册时天气工具还没注册进来（cordis.yml 里 weather.ts 排在前面的错觉：
  // 真正决定顺序的是依赖拓扑，写插件的人控制不了）。
  // 所以这里给的不是一串文本，是一个"被问到才去 ctx.tools 拿"的函数。
  ctx.systemPrompt.section({
    name: 'agent:tools',
    order: SECTION_ORDER.tools,
    text: () => ctx.systemPrompt.renderTools(ctx.tools.schemas()),
  })
  // 每次提示词变了都报一声——注册表通知，不是启动时假设
  ctx.on('system-prompt/change', () => {
    console.log(`[提示词变更] 现在共 ${ctx.systemPrompt.assemble().length} 字`)
  })
  ctx.on('tools/change', () => {
    console.log(`[工具清单变更] 现在共 ${ctx.tools.schemas().length} 个工具`)
  })

  setTimeout(() => ctx.emit('agent/turn', '北京天气怎么样？'), 50)
  setTimeout(() => ctx.emit('agent/turn', '帮我写一首诗'), 150)
  // 第三轮之前临时给助手扩权：提示词是注册表，能中途改写
  setTimeout(() => { widenScope() }, 300)
  setTimeout(() => ctx.emit('agent/turn', '帮我写一首诗'), 400)
  setTimeout(() => replay(), 500)

  /**
   * 把身份段换掉：从"只回答天气"改成"天气助手，也能闲聊"。
   *
   * 用的是 `ctx.effect()` 的返回——上一段注册的销毁器。
   * 提示词从此刻起变成新算出来的那份，不需要重启进程。
   */
  function widenScope() {
    console.log('\n=== 改写身份段：允许闲聊 ===')
    disposeIdentity?.()
    disposeIdentity = ctx.systemPrompt.section({
      name: 'agent:identity',
      order: SECTION_ORDER.identity,
      text: '你是一个天气助手，主要回答天气，但也能闲聊几句。',
    })
  }

  async function run(input: string) {
    console.log(`\n=== 用户说：${input} ===`)
    ctx.sessionLog.append({ type: 'user/message', data: { content: input } })

    // 关键一行：提示词不是谁写死的一个常量，是从注册表现算的
    const system = ctx.systemPrompt.assemble()
    // 提示词变了：新起一条 system 行，并且**顶掉上一版**。
    // 它不随对话变化，每轮都写一份会把日志灌满；而变化本身是重要事件，必须留痕。
    // 顶掉用 op: 'replace'（第 16 课那套）——日志里旧版还在，模型只看得见最新版。
    if (system !== lastSystem) {
      ctx.sessionLog.append(
        { type: 'system/message', data: { content: system } },
        lastSystemSeq === undefined ? 'append' : { op: 'replace', startSeq: lastSystemSeq, endSeq: lastSystemSeq },
      )
      lastSystem = system
      lastSystemSeq = ctx.sessionLog.list().at(-1)?.seq
    }

    // 再关键一行：messages 不是手搓的，是从日志折出来的——连同 system 一起
    const options: GenerateOptions = { messages: ctx.sessionLog.deriveMessages() }
    const turn = await collect(ctx.llm.stream(options))

    switch (turn.kind) {
      case 'text':
        console.log(`[模型回答] ${turn.text}`)
        ctx.sessionLog.append({ type: 'assistant/message', data: { text: turn.text } })
        break

      case 'tool-call': {
        console.log(`[模型决定] 调用 ${turn.name}，参数 ${JSON.stringify(turn.args)}`)
        // 注意：arguments 存的是模型吐出的**原始字符串**，不是我们 parse 后的对象
        ctx.sessionLog.append({
          type: 'tool/call',
          data: { callId: turn.id, name: turn.name, arguments: JSON.stringify(turn.args) },
        })
        await executeTool(turn)
        break
      }
    }
  }

  async function executeTool(call: Extract<ModelTurn, { kind: 'tool-call' }>) {
    const result = await ctx.tools.call(call.name, call.args)
    if (result.ok) {
      console.log(`[工具返回] ${String(result.value)}`)
      ctx.sessionLog.append({
        type: 'tool/result',
        data: { callId: call.id, name: call.name, value: result.value, isError: false },
      })

      // 工具结果有了，再问模型一次，让它说人话——这次它看得见刚才的调用和返回
      const follow = await collect(ctx.llm.stream({ messages: ctx.sessionLog.deriveMessages() }))
      if (follow.kind === 'text') {
        console.log(`[模型回答] ${follow.text}`)
        ctx.sessionLog.append({ type: 'assistant/message', data: { text: follow.text } })
      }
    } else {
      console.log(`[工具失败] ${result.error}`)
      ctx.sessionLog.append({
        type: 'tool/result',
        data: { callId: call.id, name: call.name, value: result.error, isError: true },
      })
    }
  }

  /** 重放：日志是唯一事实来源，屏幕上的字早没了，日志还在。 */
  function replay() {
    const lines = ctx.sessionLog.list()
    console.log(`\n=== 日志全量（${lines.length} 条）===`)
    for (const line of lines) {
      console.log(`#${line.seq} [${line.type}] ${describe(line)}`)
    }

    const messages = ctx.sessionLog.deriveMessages()
    console.log(`\n=== 第二轮请求时模型看到的历史（${messages.length} 条）===`)
    for (const message of messages) {
      console.log(`[${message.role}] ${message.content}`)
    }
  }

  function describe(line: SessionEventLine): string {
    switch (line.type) {
      case 'user/message':
        return line.data.content
      case 'assistant/message':
        return line.data.text
      case 'tool/call':
        return `${line.data.name}(${line.data.arguments})`
      case 'tool/result':
        return line.data.isError ? `失败：${String(line.data.value)}` : String(line.data.value)
      case 'system/message':
        return line.data.content
    }
  }
}

/**
 * 把流式 chunk 收成一个完整的 ModelTurn。
 *
 * 这是第 09 课 `for await` 循环的升级版：不再是打印，
 * 而是**按 index 把碎片拼回整块**。真模型的工具参数被切成很多片，
 * 必须拼起来才能 JSON.parse。
 */
async function collect(stream: AsyncIterable<StreamChunk>): Promise<ModelTurn> {
  // index → 已拼接的文本/参数
  const texts = new Map<number, string>()
  const calls = new Map<number, { id: string; name: string; arguments: string }>()

  for await (const chunk of stream) {
    switch (chunk.type) {
      case 'text-delta':
        texts.set(chunk.index, (texts.get(chunk.index) ?? '') + chunk.text)
        break
      case 'tool-call-delta': {
        const existing = calls.get(chunk.index) ?? { id: chunk.id, name: '', arguments: '' }
        // name 可能只在第一条 delta 上出现
        if (chunk.name !== undefined) existing.name = chunk.name
        existing.arguments += chunk.argumentsDelta
        calls.set(chunk.index, existing)
        break
      }
      case 'block-end':
        if (chunk.block.type === 'tool-call') {
          return { kind: 'tool-call', id: chunk.block.id, name: chunk.block.name, args: parseArgs(chunk.block.arguments) }
        }
        break
      case 'finish':
        break
      default:
        break
    }
  }

  const text = [...texts.entries()].sort(([a], [b]) => a - b).map(([, value]) => value).join('')
  return { kind: 'text', text }
}

/** 解析工具参数；解析失败时返回空对象——校验层会给出准确报错。 */
function parseArgs(json: string): Record<string, unknown> {
  try {
    const parsed: unknown = JSON.parse(json)
    return typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)
      ? parsed as Record<string, unknown>
      : {}
  } catch {
    return {}
  }
}

import type { Context } from '@deepseek-ai/cordis'
import { Llm, type GenerateOptions, type StreamChunk } from './llm.ts'

export function textResponse(text: string): StreamChunk[] {
  return [
    { type: 'block-start', index: 0, blockType: 'text' },
    ...Array.from(text, (char): StreamChunk => ({ type: 'text-delta', index: 0, text: char })),
    { type: 'block-end', index: 0, block: { type: 'text', text } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: text.length } },
    { type: 'finish', reason: { kind: 'stop' } },
  ]
}

export function toolCallResponse(id: string, name: string, args: object): StreamChunk[] {
  const argumentsJson = JSON.stringify(args)
  return [
    { type: 'block-start', index: 0, blockType: 'tool-call' },
    { type: 'tool-call-delta', index: 0, id, name, argumentsDelta: argumentsJson.slice(0, 5) },
    { type: 'tool-call-delta', index: 0, id, argumentsDelta: argumentsJson.slice(5) },
    { type: 'block-end', index: 0, block: { type: 'tool-call', id, name, arguments: argumentsJson } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: 5 } },
    { type: 'finish', reason: { kind: 'tool-calls' } },
  ]
}

export const name = 'llm-mock'

export class MockAdapter extends Llm {
  private cursor = 0

  constructor(
    ctx: Context,
    private script: (StreamChunk[] | ((options: GenerateOptions) => StreamChunk[]))[],
  ) {
    super(ctx)
  }

  async *stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const entry = this.script[this.cursor]
    if (!entry) throw new Error('MockAdapter: 剧本用完了')

    // 两种条目的寿命不同，这是本课的关键设计：
    // 函数条目是"常驻大脑"——每一轮都重新问它一次，像真模型那样只看当前请求做决策；
    // 静态条目是一次性剧本——读过就翻页，第二次 stream 就取不到了。
    if (typeof entry !== 'function') this.cursor += 1

    const chunks = typeof entry === 'function' ? entry(options) : entry
    for (const chunk of chunks) { yield chunk }
  }
}

/**
 * 假模型的"大脑"：看整个请求决定这一轮说什么。
 *
 * 真模型是靠训练数据学会"什么时候该调工具"的；我们没法训练，
 * 就用 if 把同样的决策写死。重点不在这段逻辑，而在于
 * **它输出的形状和真模型一模一样**——消费方完全感知不到差别。
 *
 * 注意签名收的是 GenerateOptions（整个请求），不是一句字符串。
 * 本课起它开始读 `role: 'system'` 那条消息——**系统提示词生效的唯一证据，
 * 就是模型的决策真的被它改变了**。读不到（比如第 17 课）时走默认行为。
 */
export function decide(options: GenerateOptions): StreamChunk[] {
  // 取**最后一条** system：历史里可能还留着被换掉的旧提示词，
  // 而真正生效的永远是最新写入的那一份。
  const system = options.messages.filter((message) => message.role === 'system').at(-1)?.content ?? ''
  const persona = system.includes('语气') ? '礼貌' : '随意'
  const hasTools = system.includes('get_weather')
  const history = options.messages
  const input = history.at(-1)?.content ?? ''

  // 工具结果又喂回来了：这次该说人话了
  if (input.includes('°C')) {
    const tail = persona === '礼貌' ? '。另外提醒您，出门请酌情携带雨具。' : '。出门看情况带把伞。'
    return textResponse(`${input}${tail}`)
  }
  if (input.includes('刚才')) {
    // 只有模型能看见摘要时才答得上来；原始记录被 replace 顶掉之后就看不到了
    const summary = options.messages.find((message) => message.content.startsWith('（摘要）'))
    if (summary) return textResponse('你问了我北京天气，我查完还提醒了你带伞。')
    return textResponse('我没有历史记忆，每次请求只带当前这一句。')
  }
  if (input.includes('北京')) {
    return toolCallResponse('call-1', 'get_weather', { city: '北京' })
  }
  // 系统提示词说了"只回答天气"，别的请求一律谢绝；
  // 身份段被改写成"也能闲聊"之后，同一句话就答得上了
  if (system.includes('只回答天气')) {
    if (persona === '礼貌') {
      return textResponse('抱歉，我是一个天气助手，只能回答天气相关的问题。')
    }
    return textResponse('我只管天气，别的问不了。')
  }
  if (input.includes('诗')) {
    // 清单里有 get_weather 才证明工具描述真的进了请求——
    // 没有它，模型连"有工具可用"都不知道
    if (!hasTools) return textResponse('我没有工具可用。')
    return textResponse('晴空一字一行诗，云落枝头化作雨。')
  }
  if (input.includes('天气')) {
    return toolCallResponse('call-2', 'get_weather', { city: '北京' })
  }
  return textResponse(`我不知道怎么回答"${input}"，但我可以查天气。`)
}

export function apply(ctx: Context) {
  ctx.plugin(MockAdapter, [decide])
}

﻿import type { Context } from '@deepseek-ai/cordis'
import { Tools, type ToolSchema } from './tools.ts'
import type { ToolArgs, ToolDefinition, ToolResult } from './define-tool.ts'

export const name = 'tools-registry'

/**
 * Service Provider：一个基于 Map 的工具注册表。
 *
 * register() 是第 02 课的"注册即效果"：注册方插件一卸载，
 * 这个工具定义自动从表里消失。
 */
class MapTools extends Tools {
  private readonly definitions = new Map<string, ToolDefinition>()
  private counter = 0

  register(definition: ToolDefinition): () => void {
    // ctx.effect 是"本插件卸载时自动执行"的注册点
    return this.ctx.effect(() => {
      this.definitions.set(definition.name, definition)
      return () => {
        this.definitions.delete(definition.name)
      }
    }, `tools.register(${definition.name})`)
  }

  get(name: string): ToolDefinition | undefined {
    return this.definitions.get(name)
  }

  list(): ToolDefinition[] {
    return [...this.definitions.values()]
  }

  schemas(): ToolSchema[] {
    // 只挑三个字段——execute 留在本地，不随请求出门
    return [...this.definitions.values()].map(({ name, description, parameters }) => ({
      name,
      description,
      parameters,
    }))
  }

  async call(name: string, args: unknown): Promise<ToolResult> {
    const definition = this.definitions.get(name)
    const callId = `call-${++this.counter}`
    if (!definition) {
      return { ok: false, callId, name, error: `工具不存在：${name}` }
    }
    try {
      const value = await definition.execute((args ?? {}) as ToolArgs, { callId })
      return { ok: true, callId, name, value }
    } catch (error) {
      return { ok: false, callId, name, error: error instanceof Error ? error.message : String(error) }
    }
  }
}

export function apply(ctx: Context) {
  ctx.plugin(MapTools)
}

import { Service, type Context } from '@deepseek-ai/cordis'
import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

/**
 * 一条会话记录。`data` 的形状由 `type` 决定。
 *
 * harness 真身里这是 `SessionEventMap`（packages/core/session/src/types.ts 第 281 行），
 * 同样是"一个 type 对应一种 data"的表。
 *
 * 本课比前几课多一种记录：`system/message`——每一轮递给模型的提示词。
 * 类型名也随内容换成本课专属的，免得和别课的同名记录表搅在一起。
 */
export interface SessionEventMap {
  /** 用户说了一句话。 */
  'user/message': { content: string }
  /** 模型回答了一轮。 */
  'assistant/message': { text: string }
  /** 模型请求调用一个工具，arguments 是它吐出的原始 JSON 字符串。 */
  'tool/call': { callId: string; name: string; arguments: string }
  /** 工具执行完了，value 是返回值，isError 标记成功失败。 */
  'tool/result': { callId: string; name: string; value: unknown; isError: boolean }
  /** 这一轮递给模型的系统提示词。 */
  'system/message': { content: string }
}

/** 任意一种会话记录。 */
export type SessionEvent =
  | { [K in keyof SessionEventMap]: { type: K; data: SessionEventMap[K] } }[keyof SessionEventMap]

/**
 * 会产生模型可见消息的记录类型。
 *
 * 日志里还有别的行（turn 边界、失败尝试），它们不进模型请求，
 * 只是排查问题时看的痕迹。harness 真身叫 `SurfaceEventType`
 * （packages/core/session/src/types.ts 第 439 行）。
 */
export type SurfaceEventType = 'user/message' | 'assistant/message' | 'tool/result' | 'system/message'

/** 一条记录在"模型能看到的历史"里的落点。 */
export type SurfaceOp =
  /** 追加到末尾：正常路径。 */
  | 'append'
  /** 替换一段已有节点：压缩上下文时用，被替换的行在日志里还在，只是不再进模型请求。 */
  | { op: 'replace'; startSeq: number; endSeq: number }

/**
 * 落盘的一行。
 *
 * 这是判别联合：`switch (line.type)` 会收窄 `line.data` 的类型，
 * 不用写任何断言。写法照抄 harness 真身的 `SessionEvent`
 * （packages/core/session/src/types.ts 第 493 行）——
 * `{ [K in ...]: {...} }[T]` 这层映射就是为了让联合生效。
 */
export type SessionEventLine = {
  [K in keyof SessionEventMap]: {
    /** 会话内单调递增的序号，从 1 开始。 */
    readonly seq: number
    /** 写入时刻，Unix 毫秒。 */
    readonly time: number
    readonly type: K
    readonly data: SessionEventMap[K]
    /** 它怎么进入模型可见历史。只有会产生消息的行带这个字段。 */
    readonly surfaceOp?: K extends SurfaceEventType ? SurfaceOp : never
  }
}[keyof SessionEventMap]

/**
 * 把会话日志挂到 `ctx.sessionLog`。
 *
 * 属性名不带 `session`：整个教程的每一课都各自声明了一份 `Session` 类，
 * 它们被同一份 tsconfig 收进一个全局命名空间，同名属性会互相冲突。
 */
declare module '@deepseek-ai/cordis' {
  interface Context { sessionLog: Session }
}

/** 一条喂给模型的请求消息。 */
export interface ChatMessage {
  readonly role: 'system' | 'user' | 'assistant' | 'tool'
  readonly content: string
}

/**
 * Service Definition：把"发生过的事"写进一条只增不减的日志。
 *
 * 这是 harness 的**唯一事实来源**。第 12 课的 agent loop 只在内存里跑，
 * 进程一退全忘了；有了它，任何时候都能把对话重放出来。
 */
export abstract class Session extends Service {
  constructor(ctx: Context) { super(ctx, 'sessionLog') }

  /**
   * 追加一条记录。
   * @param record - 记录内容。
   * @param op - 它怎么进入模型可见历史，默认 `'append'`。
   * @returns 分配到的序号。
   */
  abstract append(record: SessionEvent, op?: SurfaceOp): number

  /** 目前为止的全部记录，按 seq 升序。 */
  abstract list(): readonly SessionEventLine[]

  /**
   * 把日志折叠成模型能看的历史。
   *
   * 只走会产生消息的行；`replace` 标记的行会顶掉它覆盖的那一段。
   * 这就是 harness 的 `deriveMessages()`——每次请求前都重新折一遍，
   * 所以日志和模型看到的东西永远一致。
   */
  abstract deriveMessages(): ChatMessage[]

  /** 磁盘上已经有多少条记录——恢复来的，还是新起的。 */
  abstract readonly restoredCount: number

  /**
   * 从磁盘读回一个 session 的全部记录。
   *
   * 第一行是头行（`type: 'session'`），记录格式版本；剩下的是记录行。
   * 版本对不上直接抛错——**拒绝加载比猜着加载安全**。
   * @param file - session.jsonl 的路径。
   * @returns 按 seq 升序的记录。
   */
  static load(file: string): readonly SessionEventLine[] {
    const text = readFileSync(file, 'utf8')
    const lines = text.split('\n')
      .filter((line) => line.length > 0)
      .map((line) => JSON.parse(line) as SessionFileEvent)
    const [header, ...rest] = lines
    if (header.type !== 'session') {
      throw new Error(`session 文件第一行必须是头行，实际是 ${String(header.type)}`)
    }
    if (header.version !== SESSION_FORMAT_VERSION) {
      throw new Error(
        `session 格式版本不匹配：文件是 v${header.version}，本程序只会 v${SESSION_FORMAT_VERSION}`,
      )
    }
    // 剩下的都是记录行；头行在上面已经核对掉了
    return rest.filter(isSessionLine)
  }
}

/** 头行不是记录。 */
function isSessionLine(line: SessionFileEvent): line is SessionEventLine {
  return line.type !== 'session'
}

/**
 * 落盘文件的一行：要么是头行，要么是一条记录。
 *
 * 头行不是记录——它没有 `seq`，只说明"这个文件是什么格式的"。
 * harness 真身在 packages/session/session-persistence-jsonl/src/format.ts
 * 里也叫 `HeaderLine`，`type` 字段值是 `'session'`。
 */
export type SessionFileEvent =
  | { type: 'session'; version: number }
  | SessionEventLine

/** 当前会话日志的格式版本。harness 真身是 `SESSION_FORMAT_VERSION = 4`。 */
export const SESSION_FORMAT_VERSION = 1

/**
 * Service Provider：JSONL 落地。
 *
 * 每行一条 JSON，追加写文件。harness 真身（packages/session/session-persistence-jsonl）
 * 用 zstd 压缩、分代文件名和原子替换，我们保留最核心的那个决定：
 * **append-only，写出去的行永不改写**。
 */
export class JsonlSession extends Session {
  private seq = 0
  private readonly records: SessionEventLine[] = []
  private readonly file: string
  /** 磁盘上已有多少条记录——恢复来的，还是新起的。 */
  readonly restoredCount: number

  constructor(ctx: Context, config: { file: string }) {
    super(ctx)
    this.file = join(config.file, 'session.jsonl')
    mkdirSync(dirname(this.file), { recursive: true })

    // 恢复：接着磁盘上已有的行往下写，seq 继续往上加
    if (existsSync(this.file)) {
      const existing = Session.load(this.file)
      this.records.push(...existing)
      this.seq = existing.at(-1)?.seq ?? 0
      this.restoredCount = existing.length
    } else {
      this.restoredCount = 0
      // 新文件第一行写头行：以后谁来读这个文件，先核对版本
      appendFileSync(this.file, `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`)
    }
  }

  append(record: SessionEvent, op: SurfaceOp = 'append'): number {
    this.seq += 1
    const line = this.toLine(this.seq, record, op)
    this.records.push(line)
    // 追加写：只往文件末尾加字节，不动已有内容
    appendFileSync(this.file, `${JSON.stringify(line)}\n`)
    return line.seq
  }

  /** 拼一行。`tool/call` 不进模型可见历史——它已经被同一轮的 assistant/message 代表了。 */
  private toLine(seq: number, record: SessionEvent, op: SurfaceOp): SessionEventLine {
    const time = Date.now()
    switch (record.type) {
      case 'user/message':
        return { seq, time, type: 'user/message', data: record.data, surfaceOp: op }
      case 'assistant/message':
        return { seq, time, type: 'assistant/message', data: record.data, surfaceOp: op }
      case 'tool/result':
        return { seq, time, type: 'tool/result', data: record.data, surfaceOp: op }
      case 'system/message':
        return { seq, time, type: 'system/message', data: record.data, surfaceOp: op }
      case 'tool/call':
        return { seq, time, type: 'tool/call', data: record.data }
    }
  }

  list(): readonly SessionEventLine[] { return this.records }

  /**
   * 折叠日志。
   *
   * `surface` 是一个"模型能看到哪些 seq"的有序列表。
   * 追加就 push；替换就把 [startSeq, endSeq] 那段挖掉、换成新行。
   * 被挖掉的行在日志里一行不少，只是不再进模型请求。
   */
  deriveMessages(): ChatMessage[] {
    const surface: SessionEventLine[] = []
    for (const line of this.records) {
      const op = line.surfaceOp
      if (op === undefined) continue          // 非消息行：跳过
      if (op === 'append') { surface.push(line); continue }
      // replace：挖掉旧段，在原来的位置插入新行
      const start = surface.findIndex((node) => node.seq === op.startSeq)
      const end = surface.findIndex((node) => node.seq === op.endSeq)
      if (start === -1 || end === -1) continue
      surface.splice(start, end - start + 1, line)
    }
    return sortSystemFirst(surface.map(toChatMessage))
  }

  /**
   * 把整个文件重写一遍。
   *
   * 注意头行得带上——它是文件的一部分，不是记录。
   * 这是本文件里唯一一处"整份重写"的路径，正常写入走的是 append。
   */
  flush(): void {
    const header = `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`
    const body = this.records.map((line) => `${JSON.stringify(line)}\n`).join('')
    writeFileSync(this.file, header + body)
  }
}

/**
 * 让 system 消息排在最前面。
 *
 * 模型要求"先系统指令，再对话"，而日志里的 system 行是**按写入时刻**落的——
 * 每一轮请求都会在 user 行后面跟一条。折叠时必须把它们提前，
 * 否则对话历史会被一条系统指令从中间劈开。
 * @param messages - 按日志顺序排好的消息。
 * @returns system 在前、其余保持相对顺序的消息列表。
 */
function sortSystemFirst(messages: ChatMessage[]): ChatMessage[] {
  const system = messages.filter((message) => message.role === 'system')
  const rest = messages.filter((message) => message.role !== 'system')
  return [...system, ...rest]
}

/** 把一条消息行翻译成模型请求里的消息。 */
function toChatMessage(line: SessionEventLine): ChatMessage {
  switch (line.type) {
    case 'user/message':
      return { role: 'user', content: line.data.content }
    case 'assistant/message':
      return { role: 'assistant', content: line.data.text }
    case 'tool/result':
      return { role: 'tool', content: String(line.data.value) }
    case 'system/message':
      return { role: 'system', content: line.data.content }
    case 'tool/call':
      // 走不到这里：tool/call 没有 surfaceOp，deriveMessages 已经把它过滤掉了
      return { role: 'assistant', content: `${line.data.name}(${line.data.arguments})` }
  }
}

export function apply(ctx: Context) {
  ctx.plugin(JsonlSession, { file: '.sessions/demo' })
}

import { Service, type Context } from '@deepseek-ai/cordis'
import type { ToolSchema } from './tools.ts'

declare module '@deepseek-ai/cordis' {
  interface Context { systemPrompt: SystemPrompt }
  interface Events {
    /**
     * 有段落注册进来或摘出去。
     *
     * harness 真身（packages/core/system-prompt/src/index.ts 第 19 行）也叫
     * `system-prompt/change`。为什么需要它？因为**写插件的人控制不了谁先加载**，
     * 想知道"提示词是不是变了"，只能等注册表通知。
     * @mode emit
     */
    'system-prompt/change'(): void
  }
}

/**
 * 段落顺序表：数字小的排在前面。
 *
 * harness 真身（packages/core/system-prompt/src/index.ts 第 125 行）有一张
 * 大得多的 `SECTION_ORDERS`，把全仓库所有段落都钉死在固定槽位上。
 * 我们只留三个，但机制是同一套：**顺序不靠注册先后，靠一张公开的表**。
 */
export const SECTION_ORDER = {
  /** 身份：你是谁。永远在最前面。 */
  identity: -1000,
  /** 人设：部署方给定的行为准则。 */
  persona: 0,
  /** 工具清单：由注册表现算。 */
  tools: 1000,
} as const

/** 一段提示词。 */
export interface Section {
  /** 段落的唯一名字，重复注册同名会 fail loud。 */
  readonly name: string
  /** 顺序，取自 `SECTION_ORDER` 之类的公开表。 */
  readonly order: number
  /**
   * 文本，或每次组装时现算文本的函数。
   *
   * 函数形式是给"内容取决于别的插件后来发生了什么"的段落用的——
   * 工具清单就是这种：注册它的 agent 早就 apply 完了，
   * 而工具是别的插件之后才注册进来的。
   */
  readonly text: string | (() => string)
  /** 为 true 时这一段就是全部提示词，别的段落和工具清单都不要了。 */
  readonly complete?: boolean
}

/**
 * Service Definition：系统提示词的组装台。
 *
 * 它不是一个字符串字段，而是一个**有序段落注册表**。
 * 任何人都能往里加一段，加的时候不用管别人加过什么。
 */
export abstract class SystemPrompt extends Service {
  constructor(ctx: Context) { super(ctx, 'systemPrompt') }

  /**
   * 注册一段提示词。
   * @param section - 段落内容。
   * @returns 摘除函数，随注册方插件的卸载自动执行。
   */
  abstract section(section: Section): () => void

  /**
   * 拼出当前完整提示词。
   *
   * 每次请求都重新算一遍——所以任何时候问它，拿到的都是"此刻的全部贡献"。
   * @returns 组装后的文本；一段都没有时是空串。
   */
  abstract assemble(): string

  /**
   * 把工具清单渲染成一段文本。
   *
   * 模型不会读我们的 TypeScript 接口，它只认文本。
   * @param schemas - 递给模型看的工具描述。
   * @returns 渲染结果；没有工具时是空串。
   */
  abstract renderTools(schemas: readonly ToolSchema[]): string
}

/**
 * Service Provider：基于数组的段落注册表。
 *
 * 排序发生在 `assemble()` 里，不在注册时——所以后注册的段落
 * 照样能排到前面去，只要它的 order 小。
 */
class ArraySystemPrompt extends SystemPrompt {
  private readonly sections: Section[] = []

  constructor(ctx: Context) {
    super(ctx)
  }

  section(section: Section): () => void {
    return this.ctx.effect(() => {
      this.sections.push(section)
      this.ctx.emit('system-prompt/change')
      return () => {
        const index = this.sections.indexOf(section)
        if (index >= 0) this.sections.splice(index, 1)
        this.ctx.emit('system-prompt/change')
      }
    }, `systemPrompt.section(${section.name})`)
  }

  assemble(): string {
    const complete = this.sections.filter((section) => section.complete)
    if (complete.length > 1) {
      throw new Error(
        `system prompt 有 ${complete.length} 段标记了 complete：${complete.map((s) => s.name).join('、')}`,
      )
    }
    // complete 段落一出现，它就是全部——别的段落连工具清单一起让位
    if (complete.length === 1) return resolveText(complete[0])

    const sorted = [...this.sections].sort((a, b) => a.order - b.order)
    const parts = sorted.map(resolveText).filter((text) => text.length > 0)
    return parts.join('\n\n')
  }

  renderTools(schemas: readonly ToolSchema[]): string {
    if (schemas.length === 0) return ''
    const lines = schemas.map((schema) => `- ${schema.name}：${schema.description}`)
    return ['你可以使用以下工具：', ...lines].join('\n')
  }
}

/**
 * 取一段的文本。函数形式现算——调用方拿到的永远是"此刻的内容"。
 * @param section - 要取文本的段落。
 * @returns 该段落此刻的文本。
 */
function resolveText(section: Section): string {
  return typeof section.text === 'function' ? section.text() : section.text
}

export function apply(ctx: Context) {
  ctx.plugin(ArraySystemPrompt)
}

import { Service, type Context } from '@deepseek-ai/cordis'
import type { ToolDefinition, ToolParameters, ToolResult } from './define-tool.ts'

declare module '@deepseek-ai/cordis' {
  interface Context {
    tools: Tools
  }
  interface Events {
    /**
     * 有工具注册进来或摘出去。
     *
     * harness 真身（packages/core/tools/src/index.ts 第 208 行）也叫
     * `tools/change`。为什么需要它？因为插件的加载顺序由依赖拓扑决定，
     * **不写插件的人控制不了谁先谁后**。想知道"现在有哪些工具"，
     * 只能等注册表通知，不能在启动时假设它已经满了。
     * @mode emit
     */
    'tools/change'(): void
  }
}

/**
 * Service Definition：工具注册表。
 *
 * 它只知道"工具长什么样、怎么被调用"，不知道任何一个工具的具体实现。
 */
export abstract class Tools extends Service {
  constructor(ctx: Context) {
    super(ctx, 'tools')
  }

  /** 注册一个工具定义，返回的摘除函数随注册方插件的卸载自动执行。 */
  abstract register(definition: ToolDefinition): () => void

  /** 按名字取定义，没有则 undefined。 */
  abstract get(name: string): ToolDefinition | undefined

  /** 当前全部定义，按注册顺序排列。 */
  abstract list(): ToolDefinition[]

  /**
   * 递给模型看的工具清单。
   *
   * 只保留 name / description / parameters 三个字段——
   * `execute` 是本地代码，发给模型没有意义，还可能泄露实现细节。
   * harness 真身 [packages/core/tools/src/index.ts 第 1260 行](../../../deepseek-harness/packages/core/tools/src/index.ts#L1260)
   * 的 `schemas()` 干的就是这件事，注释里那词叫 allowlist（白名单）。
   */
  abstract schemas(): ToolSchema[]

  /** 执行一个工具；任何失败都收进 ToolResult，不往外抛。 */
  abstract call(name: string, args: unknown): Promise<ToolResult>
}

/** 递给模型看的工具描述：三个字段，缺一不可。 */
export interface ToolSchema {
  readonly name: string
  readonly description: string
  readonly parameters: ToolParameters
}

import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from './define-tool.ts'

export const name = 'weather-tool'

// 忘了这行，ctx.tools 会抛 "cannot get property "tools" without inject"
// （第 03 课的规矩：要拿 ctx 上的服务，必须先声明 inject）
export const inject = ['tools']

/**
 * Service Provider 的角色之一：往 ctx.tools 里放一个工具。
 *
 * 真身（packages/web/tool-web/src/search.ts）长这样：
 *   ctx.tools.register(defineTool({ name: 'web_search', ... }))
 * 我们连形状都照抄，只是把网络请求换成了假数据。
 */
export function apply(ctx: Context) {
  ctx.tools.register(defineTool({
    name: 'get_weather',
    description: '查询一个城市的天气。需要城市名。',
    parameters: {
      city: {
        type: 'string',
        required: true,
        description: '城市名，例如 "北京"',
      },
      unit: {
        type: 'string',
        enum: ['celsius', 'fahrenheit'],
        description: '温度单位，默认摄氏度。',
      },
    },
    async execute(args) {
      const city = String(args.city ?? '')
      // Keyless：假数据，不联网
      const table: Record<string, string> = {
        北京: '晴，12°C',
        上海: '小雨，18°C',
      }
      const forecast = table[city] ?? '晴，20°C（默认值）'
      const unit = args.unit === 'fahrenheit' ? '（已换算为华氏）' : ''
      return `${city}：${forecast}${unit}`
    },
  }))
}

import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from './define-tool.ts'

export const name = 'calc-tool'

export const inject = ['tools']

/**
 * 第二个工具插件。
 *
 * 它和 weather.ts 长得一模一样，唯一的差别是干的事不同。
 * 这就是"注册表"的全部意义：**加工具不用碰 loop 一行代码**，
 * 只要新写一个插件、在 cordis.yml 里加一行。
 */
export function apply(ctx: Context) {
  ctx.tools.register(defineTool({
    name: 'calc',
    description: '算一道四则运算。支持加减乘除。',
    parameters: {
      a: { type: 'number', required: true, description: '左操作数' },
      b: { type: 'number', required: true, description: '右操作数' },
      op: { type: 'string', enum: ['+', '-', '*', '/'], description: '运算符' },
    },
    execute(args) {
      const a = Number(args.a)
      const b = Number(args.b)
      switch (args.op) {
        case '+': return `${a} + ${b} = ${a + b}`
        case '-': return `${a} - ${b} = ${a - b}`
        case '*': return `${a} * ${b} = ${a * b}`
        case '/': return `${a} / ${b} = ${b === 0 ? '除数不能为 0' : a / b}`
        default:
          return `不支持的运算符：${String(args.op)}`
      }
    },
  }))
}

/**
 * 简化版 defineTool。
 *
 * harness 真身（packages/core/tools/src/schema.ts 第 554 行）在这里做三件事：
 * 1. 把手写的 JSON Schema DSL 编译成标准 JSON Schema，并用它校验模型传来的参数；
 * 2. 从 DSL 反推出 TypeScript 类型，让 execute 里的 args 有补全；
 * 3. 把校验包在 execute 外层，任何违规都以 ToolArgsError 的形式抛出。
 *
 * 第 10 课只做了"组装"。本课补上第 1 和第 3 件事——**校验**。
 */

import { compileNode, ToolArgsError, validateValue, type JsonSchemaNode, type SchemaSpec } from './json-schema.ts'

/** 模型传来的参数：一个 JSON 对象。 */
export type ToolArgs = Record<string, unknown>

/** 参数 schema：一棵 JSON Schema 树。 */
export type ToolParameters = Record<string, unknown>

/** 执行上下文：harness 真身叫 ToolRunContext，这里只保留两个字段。 */
export interface ToolRunContext {
  /** 本次调用的 id，由注册表分配。 */
  readonly callId: string
  /** 取消信号：调用方 abort 时，工具应当尽快收手。 */
  readonly signal?: AbortSignal
}

/** 一次工具调用的结果。成功失败都走这个壳，不抛异常。 */
export type ToolResult =
  | { ok: true; callId: string; name: string; value: unknown }
  | { ok: false; callId: string; name: string; error: string }

/** 一个工具的完整定义。 */
export interface ToolDefinition {
  readonly name: string
  /** 写给模型看的说明，模型据此决定要不要调用它。 */
  readonly description: string
  /** 编译后的参数 schema，既校验也进模型请求。 */
  readonly parameters: ToolParameters
  /** 具体干活的部分。参数已通过校验。 */
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}
export interface DefineToolOptions {
  name: string
  description: string
  /** 手写的参数 schema（第 11 课细讲）。 */
  parameters?: Record<string, SchemaSpec>
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}

/**
 * 定义工具。
 * @param options - 工具的名称、说明、参数 schema 和执行体。
 * @returns 一个 registry-ready 的定义，execute 已自带参数校验。
 */
export function defineTool(options: DefineToolOptions): ToolDefinition {
  const compiled = compileParameters(options.parameters)

  return {
    name: options.name,
    description: options.description,
    parameters: compiled,
    async execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> {
      // 校验发生在用户的 execute 之前：不合规的参数根本到不了业务代码
      const violations = validateValue(compiled, args)
      if (violations.length > 0) {
        throw new ToolArgsError(options.name, violations)
      }
      return options.execute(args, exec)
    },
  }
}

/** 把"每个参数一条声明"的手写 DSL 编译成一个对象根的 JSON Schema。 */
function compileParameters(spec: Record<string, SchemaSpec> | undefined): JsonSchemaNode {
  if (spec === undefined) return { type: 'object', additionalProperties: true }
  const node = compileNode({ type: 'object', properties: spec })
  // 顶层参数对象是"开放"的：模型可以额外带字段，不像 output schema 那样严苛
  node.additionalProperties = true
  return node
}

/**
 * 简化版 JSON Schema 校验器。
 *
 * harness 真身在 packages/core/tools/src/json-schema.ts，它只接受一个
 * 受限的 JSON Schema 子集：一个标量 type、对象 properties/required、
 * 布尔 additionalProperties、数组 items、标量 enum/const。任何子集之外的
 * 关键字直接拒绝，而不是"接受但不校验"——因为那会给作者一种虚假的安全感。
 *
 * 本课实现同款子集的教学版。
 */

/** 校验错误：模型传来的参数不符合声明。 */
export class ToolArgsError extends Error {
  constructor(
    readonly toolName: string,
    readonly violations: string[],
  ) {
    super(`invalid arguments: ${violations.join('; ')}`)
    this.name = 'ToolArgsError'
  }
}

/** 手写 DSL 里的一个节点。 */
export type SchemaSpec =
  | { type: 'string'; required?: true; description?: string; enum?: readonly string[] }
  | { type: 'number'; required?: true; description?: string }
  | { type: 'boolean'; required?: true; description?: string }
  | { type: 'array'; required?: true; description?: string; items?: SchemaSpec }
  | { type: 'object'; required?: true; description?: string; additionalProperties?: boolean; properties?: Record<string, SchemaSpec> }

/** 编译后的 JSON Schema 节点（只保留校验需要的字段）。 */
export interface JsonSchemaNode {
  type: string
  description?: string
  enum?: readonly (string | number | boolean | null)[]
  required?: string[]
  additionalProperties?: boolean
  items?: JsonSchemaNode
  properties?: Record<string, JsonSchemaNode>
  /** 允许作为普通 JSON 对象在工具之间传递。 */
  [key: string]: unknown
}

/**
 * 把手写 DSL 的一个节点编译成 JSON Schema。
 * @param spec - 手写 DSL 节点。
 * @returns 编译后的 JSON Schema 节点。
 */
export function compileNode(spec: SchemaSpec): JsonSchemaNode {
  const node: JsonSchemaNode = { type: spec.type }
  if (spec.description !== undefined) node.description = spec.description
  if ('enum' in spec && spec.enum !== undefined) node.enum = spec.enum
  if (spec.type === 'array' && spec.items !== undefined) {
    node.items = compileNode(spec.items)
  }
  if (spec.type === 'object') {
    node.additionalProperties = spec.additionalProperties ?? false
    if (spec.properties !== undefined) {
      node.properties = {}
      node.required = []
      for (const [key, child] of Object.entries(spec.properties)) {
        node.properties[key] = compileNode(child)
        if (child.required === true) node.required.push(key)
      }
      if (node.required.length === 0) delete node.required
    }
  }
  return node
}

/**
 * 校验一个值是否符合编译后的 schema。
 * @param schema - 编译后的 schema。
 * @param value - 待校验的值，任意来源。
 * @param path - 当前路径，用于错误信息定位。
 * @returns 违规列表；空数组表示通过。
 */
export function validateValue(schema: JsonSchemaNode, value: unknown, path = '$'): string[] {
  const violations: string[] = []
  const at = (suffix: string) => suffix === '' ? path : `${path}.${suffix}`

  switch (schema.type) {
    case 'string':
      if (typeof value !== 'string') {
        violations.push(`${at('')} 必须是字符串，收到 ${describe(value)}`)
        break
      }
      if (schema.enum !== undefined && !schema.enum.includes(value)) {
        violations.push(`${at('')} 必须是 ${schema.enum.map((entry) => JSON.stringify(entry)).join(' / ')} 之一`)
      }
      break

    case 'number':
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        violations.push(`${at('')} 必须是数字，收到 ${describe(value)}`)
      }
      break

    case 'boolean':
      if (typeof value !== 'boolean') {
        violations.push(`${at('')} 必须是布尔值，收到 ${describe(value)}`)
      }
      break

    case 'array': {
      if (!Array.isArray(value)) {
        violations.push(`${at('')} 必须是数组，收到 ${describe(value)}`)
        break
      }
      if (schema.items === undefined) break
      value.forEach((entry, index) => {
        violations.push(...validateValue(schema.items!, entry, `${path}[${index}]`))
      })
      break
    }

    case 'object': {
      if (typeof value !== 'object' || value === null || Array.isArray(value)) {
        violations.push(`${at('')} 必须是对象，收到 ${describe(value)}`)
        break
      }
      const record = value as Record<string, unknown>
      for (const key of schema.required ?? []) {
        if (record[key] === undefined) {
          violations.push(`${at(key)} 是必填项，但没有提供`)
        }
      }
      for (const [key, child] of Object.entries(schema.properties ?? {})) {
        if (record[key] === undefined) continue
        violations.push(...validateValue(child, record[key], at(key)))
      }
      if (schema.additionalProperties === false) {
        for (const key of Object.keys(record)) {
          if (schema.properties === undefined || !(key in schema.properties)) {
            violations.push(`${at(key)} 不是声明过的字段（additionalProperties: false）`)
          }
        }
      }
      break
    }

    default:
      throw new Error(`不支持的 schema 类型：${schema.type}`)
  }

  return violations
}

/** 把一个未知值描述成一句人能看懂的话，用于错误信息。 */
function describe(value: unknown): string {
  if (value === null) return 'null'
  if (Array.isArray(value)) return '数组'
  if (typeof value === 'object') return '对象'
  return JSON.stringify(value) ?? String(value)
}

import { Service, type Context } from '@deepseek-ai/cordis'

declare module '@deepseek-ai/cordis' {
  interface Context { llm: Llm }
  interface Events {
    /** 消费方向 llm 服务发出一次请求，由提供方处理。 */
    'llm/generate'(input: string): void
  }
}

export type StreamChunk =
  | { type: 'block-start'; index: number; blockType: 'text' | 'tool-call' }
  | { type: 'text-delta'; index: number; text: string }
  | { type: 'reasoning-delta'; index: number; text: string }
  | { type: 'tool-call-delta'; index: number; id: string; name?: string; argumentsDelta: string }
  | { type: 'block-end'; index: number; block: ContentBlock }
  | { type: 'usage'; usage: { inputTokens: number; outputTokens: number } }
  | { type: 'finish'; reason: { kind: 'stop' | 'tool-calls' | 'max-tokens' | 'error' } }

export type ContentBlock =
  | { type: 'text'; text: string }
  | { type: 'tool-call'; id: string; name: string; arguments: string }

export interface GenerateOptions {
  messages: { role: 'system' | 'user' | 'assistant' | 'tool'; content: string }[]
  maxTokens?: number
  signal?: AbortSignal
}

export abstract class Llm extends Service {
  constructor(ctx: Context) { super(ctx, 'llm') }
  abstract stream(options: GenerateOptions): AsyncIterable<StreamChunk>
}

import type { Context } from '@deepseek-ai/cordis'
import type { GenerateOptions, StreamChunk } from './llm.ts'
import type { SessionLine } from './session.ts'

declare module '@deepseek-ai/cordis' {
  interface Events {
    /** 用户说了一句话，agent 处理一轮。 */
    'agent/turn'(input: string): void
    /** 把前面的轮次折叠成一条摘要。 */
    'agent/compact'(fromSeq: number, toSeq: number, summary: string): void
  }
}

export const name = 'agent'
export const inject = ['llm', 'tools', 'session']

/** 一轮对话里模型给出的指令：要么说话，要么调工具。 */
type ModelTurn =
  | { kind: 'text'; text: string }
  | { kind: 'tool-call'; id: string; name: string; args: Record<string, unknown> }

/**
 * Consumer：agent loop 的第三版。
 *
 * 前两版跑完就忘。本课在 `apply` 的第一时间问一句：
 * **磁盘上是不是已经有一段历史了？** 有，就把它接上，接着往下聊。
 */
export function apply(ctx: Context) {
  ctx.on('agent/turn', (input) => { void run(input) })
  ctx.on('agent/compact', (fromSeq, toSeq, summary) => { compact(fromSeq, toSeq, summary) })

  // 启动第一件事：报告从磁盘恢复了什么
  const restored = ctx.session.restoredCount
  if (restored > 0) {
    console.log(`=== 从磁盘恢复了 ${restored} 条记录，seq 接着 #${ctx.session.list().at(-1)?.seq ?? 0} 往下编 ===`)
    console.log('=== 模型看到的历史 ===')
    for (const message of ctx.session.deriveMessages()) {
      console.log(`[${message.role}] ${message.content}`)
    }
    // 恢复之后直接问一个需要历史才能答的问题
    setTimeout(() => ctx.emit('agent/turn', '刚才我问了什么？'), 50)
  } else {
    console.log('=== 没有找到历史，开一个新会话 ===')
    setTimeout(() => ctx.emit('agent/turn', '北京天气怎么样？'), 50)
    setTimeout(() => ctx.emit('agent/turn', '帮我算 7*6'), 100)
    setTimeout(() => ctx.emit('agent/turn', '你好'), 150)
    // 三轮聊完，把 #1~#10 折成一条摘要。
    // endSeq 必须是**摘要之前最后一条记录**（#10）：摘要自己落在 #11，
    // 它还没进日志，写 11 会让"找终点"的那一步落空，压缩被静默跳过。
    setTimeout(() => ctx.emit('agent/compact', 1, 10, '（摘要）用户问了北京天气和一道乘法，模型分别调了 get_weather 和 calc。'), 200)
  }
  setTimeout(() => replay(), 400)

  /**
   * 工具清单：等注册表通知，不自己猜时机。
   *
   * 为什么不能在 apply 函数体里直接 `ctx.tools.schemas()`？因为 cordis 按
   * **依赖拓扑**排插件的加载顺序：agent 声明了 `inject: ['llm','tools','session']`，
   * 它要的三个服务必须先把 provider 建好，所以 agent 的 apply 排在 provider
   * 之后、**但排在 weather-tool / calc-tool 之前**——后两者只 inject 了
   * `tools`，拓扑上没人催它们，就按 cordis.yml 的顺序落到最后。
   *
   * 也就是说：apply 函数体执行的那一刻，注册表**恰好是空的**。
   * 而这个顺序由依赖关系决定，写 cordis.yml 的人控制不了。
   * 所以"现在有哪些工具"这件事，只能等注册表通知，不能自己数。
   *
   * 那为什么还要 `setTimeout` 包一层？因为插件是一个个加载的，
   * weather-tool 注册时会响一次，calc-tool 注册时又响一次。
   * 每次响都打印，就会打出两份不完整的清单。
   * 所以：**每次变化只重新排一次打印，等本轮事件循环安静下来再打**。
   */
  let scheduled = false
  ctx.on('tools/change', () => {
    if (scheduled) return
    scheduled = true
    setTimeout(printTools, 0)
  })

  function printTools() {
    console.log('=== 模型能选的工具 ===')
    for (const schema of ctx.tools.schemas()) {
      console.log(`- ${schema.name}：${schema.description}`)
    }
  }

  async function run(input: string) {
    console.log(`\n=== 用户说：${input} ===`)
    ctx.session.append({ type: 'user/message', data: { content: input } })

    // 关键一行：messages 不是手搓的，是从日志折出来的
    const options: GenerateOptions = { messages: ctx.session.deriveMessages() }
    const turn = await collect(ctx.llm.stream(options))

    switch (turn.kind) {
      case 'text':
        console.log(`[模型回答] ${turn.text}`)
        ctx.session.append({ type: 'assistant/message', data: { text: turn.text } })
        break

      case 'tool-call': {
        console.log(`[模型决定] 调用 ${turn.name}，参数 ${JSON.stringify(turn.args)}`)
        // 注意：arguments 存的是模型吐出的**原始字符串**，不是我们 parse 后的对象
        ctx.session.append({
          type: 'tool/call',
          data: { callId: turn.id, name: turn.name, arguments: JSON.stringify(turn.args) },
        })
        await executeTool(turn)
        break
      }
    }
  }

  async function executeTool(call: Extract<ModelTurn, { kind: 'tool-call' }>) {
    const result = await ctx.tools.call(call.name, call.args)
    if (result.ok) {
      console.log(`[工具返回] ${String(result.value)}`)
      ctx.session.append({
        type: 'tool/result',
        data: { callId: call.id, name: call.name, value: result.value, isError: false },
      })

      // 工具结果有了，再问模型一次，让它说人话——这次它看得见刚才的调用和返回
      const follow = await collect(ctx.llm.stream({ messages: ctx.session.deriveMessages() }))
      if (follow.kind === 'text') {
        console.log(`[模型回答] ${follow.text}`)
        ctx.session.append({ type: 'assistant/message', data: { text: follow.text } })
      }
    } else {
      console.log(`[工具失败] ${result.error}`)
      ctx.session.append({
        type: 'tool/result',
        data: { callId: call.id, name: call.name, value: result.error, isError: true },
      })
    }
  }

  /**
   * 压缩：往日志里**追加**一条摘要，标记它顶掉 [fromSeq, toSeq]。
   *
   * 注意是追加，不是删除。旧的行一条不少地还在文件里，
   * 只是从此不进模型请求——这就是 harness 的 compaction 路子。
   */
  function compact(fromSeq: number, toSeq: number, summary: string) {
    console.log(`\n=== 压缩：#${fromSeq}~#${toSeq} 折成一条摘要 ===`)
    const seq = ctx.session.append(
      { type: 'assistant/message', data: { text: summary } },
      { op: 'replace', startSeq: fromSeq, endSeq: toSeq },
    )
    console.log(`摘要落成 #${seq}，它顶掉了 #${fromSeq}~#${toSeq}`)
  }

  /** 重放：日志是唯一事实来源，屏幕上的字早没了，日志还在。 */
  function replay() {
    const lines = ctx.session.list()
    console.log(`\n=== 日志全量（${lines.length} 条）===`)
    for (const line of lines) {
      console.log(`#${line.seq} [${line.type}] ${describe(line)}${opNote(line)}`)
    }

    const messages = ctx.session.deriveMessages()
    console.log(`\n=== 模型看到的历史（折叠后 ${messages.length} 条）===`)
    for (const message of messages) {
      console.log(`[${message.role}] ${message.content}`)
    }
  }

  /** 压缩标记只在日志里可见，模型那一侧看不到。 */
  function opNote(line: SessionLine): string {
    const op = line.surfaceOp
    if (op === undefined || op === 'append') return ''
    return `　← replace #${op.startSeq}~#${op.endSeq}`
  }

  function describe(line: SessionLine): string {
    switch (line.type) {
      case 'user/message':
        return line.data.content
      case 'assistant/message':
        return line.data.text
      case 'tool/call':
        return `${line.data.name}(${line.data.arguments})`
      case 'tool/result':
        return line.data.isError ? `失败：${String(line.data.value)}` : String(line.data.value)
    }
  }
}

/**
 * 把流式 chunk 收成一个完整的 ModelTurn。
 *
 * 这是第 09 课 `for await` 循环的升级版：不再是打印，
 * 而是**按 index 把碎片拼回整块**。真模型的工具参数被切成很多片，
 * 必须拼起来才能 JSON.parse。
 */
async function collect(stream: AsyncIterable<StreamChunk>): Promise<ModelTurn> {
  // index → 已拼接的文本/参数
  const texts = new Map<number, string>()
  const calls = new Map<number, { id: string; name: string; arguments: string }>()

  for await (const chunk of stream) {
    switch (chunk.type) {
      case 'text-delta':
        texts.set(chunk.index, (texts.get(chunk.index) ?? '') + chunk.text)
        break
      case 'tool-call-delta': {
        const existing = calls.get(chunk.index) ?? { id: chunk.id, name: '', arguments: '' }
        // name 可能只在第一条 delta 上出现
        if (chunk.name !== undefined) existing.name = chunk.name
        existing.arguments += chunk.argumentsDelta
        calls.set(chunk.index, existing)
        break
      }
      case 'block-end':
        if (chunk.block.type === 'tool-call') {
          return { kind: 'tool-call', id: chunk.block.id, name: chunk.block.name, args: parseArgs(chunk.block.arguments) }
        }
        break
      case 'finish':
        break
      default:
        break
    }
  }

  const text = [...texts.entries()].sort(([a], [b]) => a - b).map(([, value]) => value).join('')
  return { kind: 'text', text }
}

/** 解析工具参数；解析失败时返回空对象——校验层会给出准确报错。 */
function parseArgs(json: string): Record<string, unknown> {
  try {
    const parsed: unknown = JSON.parse(json)
    return typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)
      ? parsed as Record<string, unknown>
      : {}
  } catch {
    return {}
  }
}

import type { Context } from '@deepseek-ai/cordis'
import { Llm, type GenerateOptions, type StreamChunk } from './llm.ts'

export function textResponse(text: string): StreamChunk[] {
  return [
    { type: 'block-start', index: 0, blockType: 'text' },
    ...Array.from(text, (char): StreamChunk => ({ type: 'text-delta', index: 0, text: char })),
    { type: 'block-end', index: 0, block: { type: 'text', text } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: text.length } },
    { type: 'finish', reason: { kind: 'stop' } },
  ]
}

export function toolCallResponse(id: string, name: string, args: object): StreamChunk[] {
  const argumentsJson = JSON.stringify(args)
  return [
    { type: 'block-start', index: 0, blockType: 'tool-call' },
    { type: 'tool-call-delta', index: 0, id, name, argumentsDelta: argumentsJson.slice(0, 5) },
    { type: 'tool-call-delta', index: 0, id, argumentsDelta: argumentsJson.slice(5) },
    { type: 'block-end', index: 0, block: { type: 'tool-call', id, name, arguments: argumentsJson } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: 5 } },
    { type: 'finish', reason: { kind: 'tool-calls' } },
  ]
}

export const name = 'llm-mock'

export class MockAdapter extends Llm {
  private cursor = 0

  constructor(
    ctx: Context,
    private script: (StreamChunk[] | ((options: GenerateOptions) => StreamChunk[]))[],
  ) {
    super(ctx)
  }

  async *stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const entry = this.script[this.cursor]
    if (!entry) throw new Error('MockAdapter: 剧本用完了')

    // 两种条目的寿命不同，这是本课的关键设计：
    // 函数条目是"常驻大脑"——每一轮都重新问它一次，像真模型那样只看当前请求做决策；
    // 静态条目是一次性剧本——读过就翻页，第二次 stream 就取不到了。
    if (typeof entry !== 'function') this.cursor += 1

    const chunks = typeof entry === 'function' ? entry(options) : entry
    for (const chunk of chunks) { yield chunk }
  }
}

/**
 * 假模型的"大脑"：看用户输入决定这一轮说什么。
 *
 * 真模型是靠训练数据学会"什么时候该调工具"的；我们没法训练，
 * 就用 if 把同样的决策写死。重点不在这段逻辑，而在于
 * **它输出的形状和真模型一模一样**——消费方完全感知不到差别。
 *
 * 注意签名收的是 GenerateOptions（整个请求），不是一句字符串：
 * 真模型看的是全部 messages，我们只看最后一条——至于是谁说的，
 * 在"请求即历史"之后已经不重要了，压缩摘要也是一条历史。
 */
export function decide(options: GenerateOptions): StreamChunk[] {
  const input = options.messages.at(-1)?.content ?? ''
  // 工具结果又喂回来了：这次该说人话了
  if (input.includes('°C')) {
    return textResponse(`${input}。出门看情况带把伞。`)
  }
  if (input.includes('刚才')) {
    // 只有模型能看见摘要时才答得上来；原始记录被 replace 顶掉之后就看不到了
    const summary = options.messages.find((message) => message.content.startsWith('（摘要）'))
    if (summary) return textResponse('你问了我北京天气，我查完还提醒了你带伞。')
    return textResponse('我没有历史记忆，每次请求只带当前这一句。')
  }
  if (input.includes('北京')) {
    return toolCallResponse('call-1', 'get_weather', { city: '北京' })
  }
  if (input.includes('天气')) {
    return toolCallResponse('call-2', 'get_weather', { city: '北京' })
  }
  // 新增：模型"选"了另一个工具。它不需要认识 calc 的实现，
  // 只要注册表里有这个名字，loop 就能把它调起来。
  if (input.includes('算') || input.includes('+')) {
    return toolCallResponse('call-3', 'calc', { a: 7, b: 6, op: '*' })
  }
  // 工具结果又喂回来了：算数结果是 "7 * 6 = 42" 这种形状。
  // 注意上面那句不能写成 includes('*')——那会把结果也当成"要算数"。
  if (/^[\d.]+\s*[-+*/]\s*[\d.]+\s*=/.test(input)) {
    return textResponse(`算好了：${input}`)
  }
  return textResponse(`我不知道怎么回答"${input}"，但我可以查天气、也会算数。`)
}

export function apply(ctx: Context) {
  ctx.plugin(MockAdapter, [decide])
}

import type { Context } from '@deepseek-ai/cordis'
import { Tools, type ToolSchema } from './tools.ts'
import type { ToolArgs, ToolDefinition, ToolResult } from './define-tool.ts'

export const name = 'tools-registry'

/**
 * Service Provider：一个基于 Map 的工具注册表。
 *
 * register() 是第 02 课的"注册即效果"：注册方插件一卸载，
 * 这个工具定义自动从表里消失。
 */
class MapTools extends Tools {
  private readonly definitions = new Map<string, ToolDefinition>()
  private counter = 0

  register(definition: ToolDefinition): () => void {
    // ctx.effect 是"本插件卸载时自动执行"的注册点
    return this.ctx.effect(() => {
      this.definitions.set(definition.name, definition)
      // 注册即广播：谁想知道"现在有哪些工具"，挂这个事件就行
      this.ctx.emit('tools/change')
      return () => {
        this.definitions.delete(definition.name)
        this.ctx.emit('tools/change')
      }
    }, `tools.register(${definition.name})`)
  }

  get(name: string): ToolDefinition | undefined {
    return this.definitions.get(name)
  }

  list(): ToolDefinition[] {
    return [...this.definitions.values()]
  }

  schemas(): ToolSchema[] {
    // 只挑三个字段——execute 留在本地，不随请求出门
    return [...this.definitions.values()].map(({ name, description, parameters }) => ({
      name,
      description,
      parameters,
    }))
  }

  async call(name: string, args: unknown): Promise<ToolResult> {
    const definition = this.definitions.get(name)
    const callId = `call-${++this.counter}`
    if (!definition) {
      return { ok: false, callId, name, error: `工具不存在：${name}` }
    }
    try {
      const value = await definition.execute((args ?? {}) as ToolArgs, { callId })
      return { ok: true, callId, name, value }
    } catch (error) {
      return { ok: false, callId, name, error: error instanceof Error ? error.message : String(error) }
    }
  }
}

export function apply(ctx: Context) {
  ctx.plugin(MapTools)
}

import { Service, type Context } from '@deepseek-ai/cordis'
import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

/**
 * 一条会话记录。`data` 的形状由 `type` 决定。
 *
 * harness 真身里这是 `SessionEventMap`（packages/core/session/src/types.ts 第 281 行），
 * 同样是"一个 type 对应一种 data"的表。
 */
export interface SessionRecordMap {
  /** 用户说了一句话。 */
  'user/message': { content: string }
  /** 模型回答了一轮。 */
  'assistant/message': { text: string }
  /** 模型请求调用一个工具，arguments 是它吐出的原始 JSON 字符串。 */
  'tool/call': { callId: string; name: string; arguments: string }
  /** 工具执行完了，value 是返回值，isError 标记成功失败。 */
  'tool/result': { callId: string; name: string; value: unknown; isError: boolean }
}

/** 任意一种会话记录。 */
export type SessionRecord =
  | { [K in keyof SessionRecordMap]: { type: K; data: SessionRecordMap[K] } }[keyof SessionRecordMap]

/**
 * 会产生模型可见消息的记录类型。
 *
 * 日志里还有别的行（turn 边界、失败尝试），它们不进模型请求，
 * 只是排查问题时看的痕迹。harness 真身叫 `SurfaceEventType`
 * （packages/core/session/src/types.ts 第 439 行）。
 */
export type SurfaceRecordType = 'user/message' | 'assistant/message' | 'tool/result'

/** 一条记录在"模型能看到的历史"里的落点。 */
export type SurfaceOp =
  /** 追加到末尾：正常路径。 */
  | 'append'
  /** 替换一段已有节点：压缩上下文时用，被替换的行在日志里还在，只是不再进模型请求。 */
  | { op: 'replace'; startSeq: number; endSeq: number }

/**
 * 落盘的一行。
 *
 * 这是判别联合：`switch (line.type)` 会收窄 `line.data` 的类型，
 * 不用写任何断言。写法照抄 harness 真身的 `SessionEvent`
 * （packages/core/session/src/types.ts 第 493 行）——
 * `{ [K in ...]: {...} }[T]` 这层映射就是为了让联合生效。
 */
export type SessionLine = {
  [K in keyof SessionRecordMap]: {
    /** 会话内单调递增的序号，从 1 开始。 */
    readonly seq: number
    /** 写入时刻，Unix 毫秒。 */
    readonly time: number
    readonly type: K
    readonly data: SessionRecordMap[K]
    /** 它怎么进入模型可见历史。只有会产生消息的行带这个字段。 */
    readonly surfaceOp?: K extends SurfaceRecordType ? SurfaceOp : never
  }
}[keyof SessionRecordMap]

declare module '@deepseek-ai/cordis' {
  interface Context { session: Session }
}

/** 一条喂给模型的请求消息。 */
export interface ChatMessage {
  readonly role: 'user' | 'assistant' | 'tool'
  readonly content: string
}

/**
 * Service Definition：把"发生过的事"写进一条只增不减的日志。
 *
 * 这是 harness 的**唯一事实来源**。第 12 课的 agent loop 只在内存里跑，
 * 进程一退全忘了；有了它，任何时候都能把对话重放出来。
 */
export abstract class Session extends Service {
  constructor(ctx: Context) { super(ctx, 'session') }

  /**
   * 追加一条记录。
   * @param record - 记录内容。
   * @param op - 它怎么进入模型可见历史，默认 `'append'`。
   * @returns 分配到的序号。
   */
  abstract append(record: SessionRecord, op?: SurfaceOp): number

  /** 目前为止的全部记录，按 seq 升序。 */
  abstract list(): readonly SessionLine[]

  /**
   * 把日志折叠成模型能看的历史。
   *
   * 只走会产生消息的行；`replace` 标记的行会顶掉它覆盖的那一段。
   * 这就是 harness 的 `deriveMessages()`——每次请求前都重新折一遍，
   * 所以日志和模型看到的东西永远一致。
   */
  abstract deriveMessages(): ChatMessage[]

  /** 磁盘上已经有多少条记录——恢复来的，还是新起的。 */
  abstract readonly restoredCount: number

  /**
   * 从磁盘读回一个 session 的全部记录。
   *
   * 第一行是头行（`type: 'session'`），记录格式版本；剩下的是记录行。
   * 版本对不上直接抛错——**拒绝加载比猜着加载安全**。
   * @param file - session.jsonl 的路径。
   * @returns 按 seq 升序的记录。
   */
  static load(file: string): readonly SessionLine[] {
    const text = readFileSync(file, 'utf8')
    const lines = text.split('\n')
      .filter((line) => line.length > 0)
      .map((line) => JSON.parse(line) as SessionFileLine)
    const [header, ...rest] = lines
    if (header.type !== 'session') {
      throw new Error(`session 文件第一行必须是头行，实际是 ${String(header.type)}`)
    }
    if (header.version !== SESSION_FORMAT_VERSION) {
      throw new Error(
        `session 格式版本不匹配：文件是 v${header.version}，本程序只会 v${SESSION_FORMAT_VERSION}`,
      )
    }
    // 剩下的都是记录行；头行在上面已经核对掉了
    return rest.filter(isSessionLine)
  }
}

/** 头行不是记录。 */
function isSessionLine(line: SessionFileLine): line is SessionLine {
  return line.type !== 'session'
}

/**
 * 落盘文件的一行：要么是头行，要么是一条记录。
 *
 * 头行不是记录——它没有 `seq`，只说明"这个文件是什么格式的"。
 * harness 真身在 packages/session/session-persistence-jsonl/src/format.ts
 * 里也叫 `HeaderLine`，`type` 字段值是 `'session'`。
 */
export type SessionFileLine =
  | { type: 'session'; version: number }
  | SessionLine

/** 当前会话日志的格式版本。harness 真身是 `SESSION_FORMAT_VERSION = 4`。 */
export const SESSION_FORMAT_VERSION = 1

/**
 * Service Provider：JSONL 落地。
 *
 * 每行一条 JSON，追加写文件。harness 真身（packages/session/session-persistence-jsonl）
 * 用 zstd 压缩、分代文件名和原子替换，我们保留最核心的那个决定：
 * **append-only，写出去的行永不改写**。
 */
export class JsonlSession extends Session {
  private seq = 0
  private readonly records: SessionLine[] = []
  private readonly file: string
  /** 磁盘上已有多少条记录——恢复来的，还是新起的。 */
  readonly restoredCount: number

  constructor(ctx: Context, config: { file: string }) {
    super(ctx)
    this.file = join(config.file, 'session.jsonl')
    mkdirSync(dirname(this.file), { recursive: true })

    // 恢复：接着磁盘上已有的行往下写，seq 继续往上加
    if (existsSync(this.file)) {
      const existing = Session.load(this.file)
      this.records.push(...existing)
      this.seq = existing.at(-1)?.seq ?? 0
      this.restoredCount = existing.length
    } else {
      this.restoredCount = 0
      // 新文件第一行写头行：以后谁来读这个文件，先核对版本
      appendFileSync(this.file, `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`)
    }
  }

  append(record: SessionRecord, op: SurfaceOp = 'append'): number {
    this.seq += 1
    const line = this.toLine(this.seq, record, op)
    this.records.push(line)
    // 追加写：只往文件末尾加字节，不动已有内容
    appendFileSync(this.file, `${JSON.stringify(line)}\n`)
    return line.seq
  }

  /** 拼一行。`tool/call` 不进模型可见历史——它已经被同一轮的 assistant/message 代表了。 */
  private toLine(seq: number, record: SessionRecord, op: SurfaceOp): SessionLine {
    const time = Date.now()
    switch (record.type) {
      case 'user/message':
        return { seq, time, type: 'user/message', data: record.data, surfaceOp: op }
      case 'assistant/message':
        return { seq, time, type: 'assistant/message', data: record.data, surfaceOp: op }
      case 'tool/result':
        return { seq, time, type: 'tool/result', data: record.data, surfaceOp: op }
      case 'tool/call':
        return { seq, time, type: 'tool/call', data: record.data }
    }
  }

  list(): readonly SessionLine[] { return this.records }

  /**
   * 折叠日志。
   *
   * `surface` 是一个"模型能看到哪些 seq"的有序列表。
   * 追加就 push；替换就把 [startSeq, endSeq] 那段挖掉、换成新行。
   * 被挖掉的行在日志里一行不少，只是不再进模型请求。
   */
  deriveMessages(): ChatMessage[] {
    const surface: SessionLine[] = []
    for (const line of this.records) {
      const op = line.surfaceOp
      if (op === undefined) continue          // 非消息行：跳过
      if (op === 'append') { surface.push(line); continue }
      // replace：挖掉旧段，在原来的位置插入新行
      const start = surface.findIndex((node) => node.seq === op.startSeq)
      const end = surface.findIndex((node) => node.seq === op.endSeq)
      if (start === -1 || end === -1) continue
      surface.splice(start, end - start + 1, line)
    }
    return surface.map(toChatMessage)
  }

  /**
   * 把整个文件重写一遍。
   *
   * 注意头行得带上——它是文件的一部分，不是记录。
   * 这是本文件里唯一一处"整份重写"的路径，正常写入走的是 append。
   */
  flush(): void {
    const header = `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`
    const body = this.records.map((line) => `${JSON.stringify(line)}\n`).join('')
    writeFileSync(this.file, header + body)
  }
}

/** 把一条消息行翻译成模型请求里的消息。 */
function toChatMessage(line: SessionLine): ChatMessage {
  switch (line.type) {
    case 'user/message':
      return { role: 'user', content: line.data.content }
    case 'assistant/message':
      return { role: 'assistant', content: line.data.text }
    case 'tool/result':
      return { role: 'tool', content: String(line.data.value) }
    case 'tool/call':
      // 走不到这里：tool/call 没有 surfaceOp，deriveMessages 已经把它过滤掉了
      return { role: 'assistant', content: `${line.data.name}(${line.data.arguments})` }
  }
}

export function apply(ctx: Context) {
  ctx.plugin(JsonlSession, { file: '.sessions/demo' })
}

import { Service, type Context } from '@deepseek-ai/cordis'
import type { ToolDefinition, ToolParameters, ToolResult } from './define-tool.ts'

declare module '@deepseek-ai/cordis' {
  interface Context {
    tools: Tools
  }
  interface Events {
    /**
     * 有工具注册进来或摘出去。
     *
     * harness 真身（packages/core/tools/src/index.ts 第 208 行）也叫
     * `tools/change`。为什么需要它？因为插件的加载顺序由依赖拓扑决定，
     * **不写插件的人控制不了谁先谁后**。想知道"现在有哪些工具"，
     * 只能等注册表通知，不能在启动时假设它已经满了。
     * @mode emit
     */
    'tools/change'(): void
  }
}

/**
 * Service Definition：工具注册表。
 *
 * 它只知道"工具长什么样、怎么被调用"，不知道任何一个工具的具体实现。
 */
export abstract class Tools extends Service {
  constructor(ctx: Context) {
    super(ctx, 'tools')
  }

  /** 注册一个工具定义，返回的摘除函数随注册方插件的卸载自动执行。 */
  abstract register(definition: ToolDefinition): () => void

  /** 按名字取定义，没有则 undefined。 */
  abstract get(name: string): ToolDefinition | undefined

  /** 当前全部定义，按注册顺序排列。 */
  abstract list(): ToolDefinition[]

  /**
   * 递给模型看的工具清单。
   *
   * 只保留 name / description / parameters 三个字段——
   * `execute` 是本地代码，发给模型没有意义，还可能泄露实现细节。
   * harness 真身 [packages/core/tools/src/index.ts 第 1260 行](../../../deepseek-harness/packages/core/tools/src/index.ts#L1260)
   * 的 `schemas()` 干的就是这件事，注释里那词叫 allowlist（白名单）。
   */
  abstract schemas(): ToolSchema[]

  /** 执行一个工具；任何失败都收进 ToolResult，不往外抛。 */
  abstract call(name: string, args: unknown): Promise<ToolResult>
}

/** 递给模型看的工具描述：三个字段，缺一不可。 */
export interface ToolSchema {
  readonly name: string
  readonly description: string
  readonly parameters: ToolParameters
}

import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from './define-tool.ts'

export const name = 'weather-tool'

// 忘了这行，ctx.tools 会抛 "cannot get property "tools" without inject"
// （第 03 课的规矩：要拿 ctx 上的服务，必须先声明 inject）
export const inject = ['tools']

/**
 * Service Provider 的角色之一：往 ctx.tools 里放一个工具。
 *
 * 真身（packages/web/tool-web/src/search.ts）长这样：
 *   ctx.tools.register(defineTool({ name: 'web_search', ... }))
 * 我们连形状都照抄，只是把网络请求换成了假数据。
 */
export function apply(ctx: Context) {
  ctx.tools.register(defineTool({
    name: 'get_weather',
    description: '查询一个城市的天气。需要城市名。',
    parameters: {
      city: {
        type: 'string',
        required: true,
        description: '城市名，例如 "北京"',
      },
      unit: {
        type: 'string',
        enum: ['celsius', 'fahrenheit'],
        description: '温度单位，默认摄氏度。',
      },
    },
    async execute(args) {
      const city = String(args.city ?? '')
      // Keyless：假数据，不联网
      const table: Record<string, string> = {
        北京: '晴，12°C',
        上海: '小雨，18°C',
      }
      const forecast = table[city] ?? '晴，20°C（默认值）'
      const unit = args.unit === 'fahrenheit' ? '（已换算为华氏）' : ''
      return `${city}：${forecast}${unit}`
    },
  }))
}

import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from './define-tool.ts'

export const name = 'calc-tool'

export const inject = ['tools']

/**
 * 第二个工具插件。
 *
 * 它和 weather.ts 长得一模一样，唯一的差别是干的事不同。
 * 这就是"注册表"的全部意义：**加工具不用碰 loop 一行代码**，
 * 只要新写一个插件、在 cordis.yml 里加一行。
 */
export function apply(ctx: Context) {
  ctx.tools.register(defineTool({
    name: 'calc',
    description: '算一道四则运算。支持加减乘除。',
    parameters: {
      a: { type: 'number', required: true, description: '左操作数' },
      b: { type: 'number', required: true, description: '右操作数' },
      op: { type: 'string', enum: ['+', '-', '*', '/'], description: '运算符' },
    },
    execute(args) {
      const a = Number(args.a)
      const b = Number(args.b)
      switch (args.op) {
        case '+': return `${a} + ${b} = ${a + b}`
        case '-': return `${a} - ${b} = ${a - b}`
        case '*': return `${a} * ${b} = ${a * b}`
        case '/': return `${a} / ${b} = ${b === 0 ? '除数不能为 0' : a / b}`
        default:
          return `不支持的运算符：${String(args.op)}`
      }
    },
  }))
}

/**
 * 简化版 defineTool。
 *
 * harness 真身（packages/core/tools/src/schema.ts 第 554 行）在这里做三件事：
 * 1. 把手写的 JSON Schema DSL 编译成标准 JSON Schema，并用它校验模型传来的参数；
 * 2. 从 DSL 反推出 TypeScript 类型，让 execute 里的 args 有补全；
 * 3. 把校验包在 execute 外层，任何违规都以 ToolArgsError 的形式抛出。
 *
 * 第 10 课只做了"组装"。本课补上第 1 和第 3 件事——**校验**。
 */

import { compileNode, ToolArgsError, validateValue, type JsonSchemaNode, type SchemaSpec } from './json-schema.ts'

/** 模型传来的参数：一个 JSON 对象。 */
export type ToolArgs = Record<string, unknown>

/** 参数 schema：一棵 JSON Schema 树。 */
export type ToolParameters = Record<string, unknown>

/** 执行上下文：harness 真身叫 ToolRunContext，这里只保留两个字段。 */
export interface ToolRunContext {
  /** 本次调用的 id，由注册表分配。 */
  readonly callId: string
  /** 取消信号：调用方 abort 时，工具应当尽快收手。 */
  readonly signal?: AbortSignal
}

/** 一次工具调用的结果。成功失败都走这个壳，不抛异常。 */
export type ToolResult =
  | { ok: true; callId: string; name: string; value: unknown }
  | { ok: false; callId: string; name: string; error: string }

/** 一个工具的完整定义。 */
export interface ToolDefinition {
  readonly name: string
  /** 写给模型看的说明，模型据此决定要不要调用它。 */
  readonly description: string
  /** 编译后的参数 schema，既校验也进模型请求。 */
  readonly parameters: ToolParameters
  /** 具体干活的部分。参数已通过校验。 */
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}
export interface DefineToolOptions {
  name: string
  description: string
  /** 手写的参数 schema（第 11 课细讲）。 */
  parameters?: Record<string, SchemaSpec>
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}

/**
 * 定义工具。
 * @param options - 工具的名称、说明、参数 schema 和执行体。
 * @returns 一个 registry-ready 的定义，execute 已自带参数校验。
 */
export function defineTool(options: DefineToolOptions): ToolDefinition {
  const compiled = compileParameters(options.parameters)

  return {
    name: options.name,
    description: options.description,
    parameters: compiled,
    async execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> {
      // 校验发生在用户的 execute 之前：不合规的参数根本到不了业务代码
      const violations = validateValue(compiled, args)
      if (violations.length > 0) {
        throw new ToolArgsError(options.name, violations)
      }
      return options.execute(args, exec)
    },
  }
}

/** 把"每个参数一条声明"的手写 DSL 编译成一个对象根的 JSON Schema。 */
function compileParameters(spec: Record<string, SchemaSpec> | undefined): JsonSchemaNode {
  if (spec === undefined) return { type: 'object', additionalProperties: true }
  const node = compileNode({ type: 'object', properties: spec })
  // 顶层参数对象是"开放"的：模型可以额外带字段，不像 output schema 那样严苛
  node.additionalProperties = true
  return node
}

/**
 * 简化版 JSON Schema 校验器。
 *
 * harness 真身在 packages/core/tools/src/json-schema.ts，它只接受一个
 * 受限的 JSON Schema 子集：一个标量 type、对象 properties/required、
 * 布尔 additionalProperties、数组 items、标量 enum/const。任何子集之外的
 * 关键字直接拒绝，而不是"接受但不校验"——因为那会给作者一种虚假的安全感。
 *
 * 本课实现同款子集的教学版。
 */

/** 校验错误：模型传来的参数不符合声明。 */
export class ToolArgsError extends Error {
  constructor(
    readonly toolName: string,
    readonly violations: string[],
  ) {
    super(`invalid arguments: ${violations.join('; ')}`)
    this.name = 'ToolArgsError'
  }
}

/** 手写 DSL 里的一个节点。 */
export type SchemaSpec =
  | { type: 'string'; required?: true; description?: string; enum?: readonly string[] }
  | { type: 'number'; required?: true; description?: string }
  | { type: 'boolean'; required?: true; description?: string }
  | { type: 'array'; required?: true; description?: string; items?: SchemaSpec }
  | { type: 'object'; required?: true; description?: string; additionalProperties?: boolean; properties?: Record<string, SchemaSpec> }

/** 编译后的 JSON Schema 节点（只保留校验需要的字段）。 */
export interface JsonSchemaNode {
  type: string
  description?: string
  enum?: readonly (string | number | boolean | null)[]
  required?: string[]
  additionalProperties?: boolean
  items?: JsonSchemaNode
  properties?: Record<string, JsonSchemaNode>
  /** 允许作为普通 JSON 对象在工具之间传递。 */
  [key: string]: unknown
}

/**
 * 把手写 DSL 的一个节点编译成 JSON Schema。
 * @param spec - 手写 DSL 节点。
 * @returns 编译后的 JSON Schema 节点。
 */
export function compileNode(spec: SchemaSpec): JsonSchemaNode {
  const node: JsonSchemaNode = { type: spec.type }
  if (spec.description !== undefined) node.description = spec.description
  if ('enum' in spec && spec.enum !== undefined) node.enum = spec.enum
  if (spec.type === 'array' && spec.items !== undefined) {
    node.items = compileNode(spec.items)
  }
  if (spec.type === 'object') {
    node.additionalProperties = spec.additionalProperties ?? false
    if (spec.properties !== undefined) {
      node.properties = {}
      node.required = []
      for (const [key, child] of Object.entries(spec.properties)) {
        node.properties[key] = compileNode(child)
        if (child.required === true) node.required.push(key)
      }
      if (node.required.length === 0) delete node.required
    }
  }
  return node
}

/**
 * 校验一个值是否符合编译后的 schema。
 * @param schema - 编译后的 schema。
 * @param value - 待校验的值，任意来源。
 * @param path - 当前路径，用于错误信息定位。
 * @returns 违规列表；空数组表示通过。
 */
export function validateValue(schema: JsonSchemaNode, value: unknown, path = '$'): string[] {
  const violations: string[] = []
  const at = (suffix: string) => suffix === '' ? path : `${path}.${suffix}`

  switch (schema.type) {
    case 'string':
      if (typeof value !== 'string') {
        violations.push(`${at('')} 必须是字符串，收到 ${describe(value)}`)
        break
      }
      if (schema.enum !== undefined && !schema.enum.includes(value)) {
        violations.push(`${at('')} 必须是 ${schema.enum.map((entry) => JSON.stringify(entry)).join(' / ')} 之一`)
      }
      break

    case 'number':
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        violations.push(`${at('')} 必须是数字，收到 ${describe(value)}`)
      }
      break

    case 'boolean':
      if (typeof value !== 'boolean') {
        violations.push(`${at('')} 必须是布尔值，收到 ${describe(value)}`)
      }
      break

    case 'array': {
      if (!Array.isArray(value)) {
        violations.push(`${at('')} 必须是数组，收到 ${describe(value)}`)
        break
      }
      if (schema.items === undefined) break
      value.forEach((entry, index) => {
        violations.push(...validateValue(schema.items!, entry, `${path}[${index}]`))
      })
      break
    }

    case 'object': {
      if (typeof value !== 'object' || value === null || Array.isArray(value)) {
        violations.push(`${at('')} 必须是对象，收到 ${describe(value)}`)
        break
      }
      const record = value as Record<string, unknown>
      for (const key of schema.required ?? []) {
        if (record[key] === undefined) {
          violations.push(`${at(key)} 是必填项，但没有提供`)
        }
      }
      for (const [key, child] of Object.entries(schema.properties ?? {})) {
        if (record[key] === undefined) continue
        violations.push(...validateValue(child, record[key], at(key)))
      }
      if (schema.additionalProperties === false) {
        for (const key of Object.keys(record)) {
          if (schema.properties === undefined || !(key in schema.properties)) {
            violations.push(`${at(key)} 不是声明过的字段（additionalProperties: false）`)
          }
        }
      }
      break
    }

    default:
      throw new Error(`不支持的 schema 类型：${schema.type}`)
  }

  return violations
}

/** 把一个未知值描述成一句人能看懂的话，用于错误信息。 */
function describe(value: unknown): string {
  if (value === null) return 'null'
  if (Array.isArray(value)) return '数组'
  if (typeof value === 'object') return '对象'
  return JSON.stringify(value) ?? String(value)
}

import { Service, type Context } from '@deepseek-ai/cordis'

declare module '@deepseek-ai/cordis' {
  interface Context { llm: Llm }
  interface Events {
    /** 消费方向 llm 服务发出一次请求，由提供方处理。 */
    'llm/generate'(input: string): void
  }
}

export type StreamChunk =
  | { type: 'block-start'; index: number; blockType: 'text' | 'tool-call' }
  | { type: 'text-delta'; index: number; text: string }
  | { type: 'reasoning-delta'; index: number; text: string }
  | { type: 'tool-call-delta'; index: number; id: string; name?: string; argumentsDelta: string }
  | { type: 'block-end'; index: number; block: ContentBlock }
  | { type: 'usage'; usage: { inputTokens: number; outputTokens: number } }
  | { type: 'finish'; reason: { kind: 'stop' | 'tool-calls' | 'max-tokens' | 'error' } }

export type ContentBlock =
  | { type: 'text'; text: string }
  | { type: 'tool-call'; id: string; name: string; arguments: string }

export interface GenerateOptions {
  messages: { role: 'system' | 'user' | 'assistant' | 'tool'; content: string }[]
  maxTokens?: number
  signal?: AbortSignal
}

export abstract class Llm extends Service {
  constructor(ctx: Context) { super(ctx, 'llm') }
  abstract stream(options: GenerateOptions): AsyncIterable<StreamChunk>
}

import type { Context } from '@deepseek-ai/cordis'
import type { GenerateOptions, StreamChunk } from './llm.ts'
import type { SessionLine } from './session.ts'

declare module '@deepseek-ai/cordis' {
  interface Events {
    /** 用户说了一句话，agent 处理一轮。 */
    'agent/turn'(input: string): void
    /** 把前面的轮次折叠成一条摘要。 */
    'agent/compact'(fromSeq: number, toSeq: number, summary: string): void
  }
}

export const name = 'agent'
export const inject = ['llm', 'tools', 'session']

/** 一轮对话里模型给出的指令：要么说话，要么调工具。 */
type ModelTurn =
  | { kind: 'text'; text: string }
  | { kind: 'tool-call'; id: string; name: string; args: Record<string, unknown> }

/**
 * Consumer：agent loop 的第四版。
 *
 * 前三版跑完就忘（或者只记得自己那次）。本课补上**能力协商**：
 * 这个插件声明了自己要 `llm`、`tools`、`session` 三项能力，cordis 就
 * 替我们盯着它们。齐了才启动，缺了就 FAILED——而不是等第一次用的
 * 时候才炸。
 */
export function apply(ctx: Context) {
  ctx.on('agent/turn', (input) => { void run(input) })
  ctx.on('agent/compact', (fromSeq, toSeq, summary) => { compact(fromSeq, toSeq, summary) })

  // 启动第一件事：报告从磁盘恢复了什么
  const restored = ctx.session.restoredCount
  if (restored > 0) {
    console.log(`=== 从磁盘恢复了 ${restored} 条记录，seq 接着 #${ctx.session.list().at(-1)?.seq ?? 0} 往下编 ===`)
    console.log('=== 模型看到的历史 ===')
    for (const message of ctx.session.deriveMessages()) {
      console.log(`[${message.role}] ${message.content}`)
    }
    // 恢复之后直接问一个需要历史才能答的问题
    setTimeout(() => ctx.emit('agent/turn', '刚才我问了什么？'), 50)
  } else {
    console.log('=== 没有找到历史，开一个新会话 ===')
    setTimeout(() => ctx.emit('agent/turn', '北京天气怎么样？'), 50)
    setTimeout(() => ctx.emit('agent/turn', '帮我算 7*6'), 100)
    setTimeout(() => ctx.emit('agent/turn', '你好'), 150)
    // 三轮聊完，把 #1~#10 折成一条摘要。
    // endSeq 必须是**摘要之前最后一条记录**（#10）：摘要自己落在 #11，
    // 它还没进日志，写 11 会让"找终点"的那一步落空，压缩被静默跳过。
    setTimeout(() => ctx.emit('agent/compact', 1, 10, '（摘要）用户问了北京天气和一道乘法，模型分别调了 get_weather 和 calc。'), 200)
  }
  setTimeout(() => replay(), 400)

  /**
   * 工具清单：等注册表通知，不自己猜时机。
   *
   * 为什么不能在 apply 函数体里直接 `ctx.tools.schemas()`？因为 cordis 按
   * **依赖拓扑**排插件的加载顺序：agent 声明了 `inject: ['llm','tools','session']`，
   * 它要的三个服务必须先把 provider 建好，所以 agent 的 apply 排在 provider
   * 之后、**但排在 weather-tool / calc-tool 之前**——后两者只 inject 了
   * `tools`，拓扑上没人催它们，就按 cordis.yml 的顺序落到最后。
   *
   * 也就是说：apply 函数体执行的那一刻，注册表**恰好是空的**。
   * 而这个顺序由依赖关系决定，写 yml 的人控制不了。
   * 所以"现在有哪些工具"这件事，只能等注册表通知，不能自己数。
   *
   * 那为什么还要 `setTimeout` 包一层？因为插件是一个个加载的，
   * weather-tool 注册时会响一次，calc-tool 注册时又响一次。
   * 每次响都打印，就会打出两份不完整的清单。
   * 所以：**每次变化只重新排一次打印，等本轮事件循环安静下来再打**。
   */
  let scheduled = false
  ctx.on('tools/change', () => {
    if (scheduled) return
    scheduled = true
    setTimeout(printTools, 0)
  })

  function printTools() {
    console.log('=== 模型能选的工具 ===')
    for (const schema of ctx.tools.schemas()) {
      console.log(`- ${schema.name}：${schema.description}`)
    }
  }

  /**
   * 对账：我声明要的能力，注册表现在真的都有了吗？
   *
   * 这就是本课的主题。`ctx.fiber.inject` 是本插件声明的那张需求表，
   * `ctx.reflect.props` 是全应用登记过的服务名册。
   * 两边一减，缺谁一目了然——而且是在**启动阶段**减，不是等
   * 某次调用踩空了才炸。
   *
   * 注意它读的是 `props`（登记册），不是 `store`（实例）。
   * 登记册里有名字，不代表现在有实例——第 19 课的工具就是
   * 先登记、后注册的。缺名字才是真缺。
   */
  function reportCapabilities() {
    console.log('\n=== 能力对账 ===')
    for (const service of Object.keys(ctx.fiber.inject)) {
      const registered = Object.hasOwn(ctx.reflect.props, service)
      const status = registered ? '齐' : '缺'
      console.log(`- ${service}：${status}`)
      if (!registered) {
        console.log(`  没人提供 ${service}——cordis.yml 里少了一个 provider，或者它自己加载失败了`)
      }
    }
  }

  setTimeout(reportCapabilities, 300)

  async function run(input: string) {
    console.log(`\n=== 用户说：${input} ===`)
    ctx.session.append({ type: 'user/message', data: { content: input } })

    // 关键一行：messages 不是手搓的，是从日志折出来的
    const options: GenerateOptions = { messages: ctx.session.deriveMessages() }
    const turn = await collect(ctx.llm.stream(options))

    switch (turn.kind) {
      case 'text':
        console.log(`[模型回答] ${turn.text}`)
        ctx.session.append({ type: 'assistant/message', data: { text: turn.text } })
        break

      case 'tool-call': {
        console.log(`[模型决定] 调用 ${turn.name}，参数 ${JSON.stringify(turn.args)}`)
        // 注意：arguments 存的是模型吐出的**原始字符串**，不是我们 parse 后的对象
        ctx.session.append({
          type: 'tool/call',
          data: { callId: turn.id, name: turn.name, arguments: JSON.stringify(turn.args) },
        })
        await executeTool(turn)
        break
      }
    }
  }

  async function executeTool(call: Extract<ModelTurn, { kind: 'tool-call' }>) {
    const result = await ctx.tools.call(call.name, call.args)
    if (result.ok) {
      console.log(`[工具返回] ${String(result.value)}`)
      ctx.session.append({
        type: 'tool/result',
        data: { callId: call.id, name: call.name, value: result.value, isError: false },
      })

      // 工具结果有了，再问模型一次，让它说人话——这次它看得见刚才的调用和返回
      const follow = await collect(ctx.llm.stream({ messages: ctx.session.deriveMessages() }))
      if (follow.kind === 'text') {
        console.log(`[模型回答] ${follow.text}`)
        ctx.session.append({ type: 'assistant/message', data: { text: follow.text } })
      }
    } else {
      console.log(`[工具失败] ${result.error}`)
      ctx.session.append({
        type: 'tool/result',
        data: { callId: call.id, name: call.name, value: result.error, isError: true },
      })
    }
  }

  /**
   * 压缩：往日志里**追加**一条摘要，标记它顶掉 [fromSeq, toSeq]。
   *
   * 注意是追加，不是删除。旧的行一条不少地还在文件里，
   * 只是从此不进模型请求——这就是 harness 的 compaction 路子。
   */
  function compact(fromSeq: number, toSeq: number, summary: string) {
    console.log(`\n=== 压缩：#${fromSeq}~#${toSeq} 折成一条摘要 ===`)
    const seq = ctx.session.append(
      { type: 'assistant/message', data: { text: summary } },
      { op: 'replace', startSeq: fromSeq, endSeq: toSeq },
    )
    console.log(`摘要落成 #${seq}，它顶掉了 #${fromSeq}~#${toSeq}`)
  }

  /** 重放：日志是唯一事实来源，屏幕上的字早没了，日志还在。 */
  function replay() {
    const lines = ctx.session.list()
    console.log(`\n=== 日志全量（${lines.length} 条）===`)
    for (const line of lines) {
      console.log(`#${line.seq} [${line.type}] ${describe(line)}${opNote(line)}`)
    }

    const messages = ctx.session.deriveMessages()
    console.log(`\n=== 模型看到的历史（折叠后 ${messages.length} 条）===`)
    for (const message of messages) {
      console.log(`[${message.role}] ${message.content}`)
    }
  }

  /** 压缩标记只在日志里可见，模型那一侧看不到。 */
  function opNote(line: SessionLine): string {
    const op = line.surfaceOp
    if (op === undefined || op === 'append') return ''
    return `　← replace #${op.startSeq}~#${op.endSeq}`
  }

  function describe(line: SessionLine): string {
    switch (line.type) {
      case 'user/message':
        return line.data.content
      case 'assistant/message':
        return line.data.text
      case 'tool/call':
        return `${line.data.name}(${line.data.arguments})`
      case 'tool/result':
        return line.data.isError ? `失败：${String(line.data.value)}` : String(line.data.value)
    }
  }
}

/**
 * 把流式 chunk 收成一个完整的 ModelTurn。
 *
 * 这是第 09 课 `for await` 循环的升级版：不再是打印，
 * 而是**按 index 把碎片拼回整块**。真模型的工具参数被切成很多片，
 * 必须拼起来才能 JSON.parse。
 */
async function collect(stream: AsyncIterable<StreamChunk>): Promise<ModelTurn> {
  // index → 已拼接的文本/参数
  const texts = new Map<number, string>()
  const calls = new Map<number, { id: string; name: string; arguments: string }>()

  for await (const chunk of stream) {
    switch (chunk.type) {
      case 'text-delta':
        texts.set(chunk.index, (texts.get(chunk.index) ?? '') + chunk.text)
        break
      case 'tool-call-delta': {
        const existing = calls.get(chunk.index) ?? { id: chunk.id, name: '', arguments: '' }
        // name 可能只在第一条 delta 上出现
        if (chunk.name !== undefined) existing.name = chunk.name
        existing.arguments += chunk.argumentsDelta
        calls.set(chunk.index, existing)
        break
      }
      case 'block-end':
        if (chunk.block.type === 'tool-call') {
          return { kind: 'tool-call', id: chunk.block.id, name: chunk.block.name, args: parseArgs(chunk.block.arguments) }
        }
        break
      case 'finish':
        break
      default:
        break
    }
  }

  const text = [...texts.entries()].sort(([a], [b]) => a - b).map(([, value]) => value).join('')
  return { kind: 'text', text }
}

/** 解析工具参数；解析失败时返回空对象——校验层会给出准确报错。 */
function parseArgs(json: string): Record<string, unknown> {
  try {
    const parsed: unknown = JSON.parse(json)
    return typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)
      ? parsed as Record<string, unknown>
      : {}
  } catch {
    return {}
  }
}

import type { Context } from '@deepseek-ai/cordis'
import { Llm, type GenerateOptions, type StreamChunk } from './llm.ts'

export function textResponse(text: string): StreamChunk[] {
  return [
    { type: 'block-start', index: 0, blockType: 'text' },
    ...Array.from(text, (char): StreamChunk => ({ type: 'text-delta', index: 0, text: char })),
    { type: 'block-end', index: 0, block: { type: 'text', text } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: text.length } },
    { type: 'finish', reason: { kind: 'stop' } },
  ]
}

export function toolCallResponse(id: string, name: string, args: object): StreamChunk[] {
  const argumentsJson = JSON.stringify(args)
  return [
    { type: 'block-start', index: 0, blockType: 'tool-call' },
    { type: 'tool-call-delta', index: 0, id, name, argumentsDelta: argumentsJson.slice(0, 5) },
    { type: 'tool-call-delta', index: 0, id, argumentsDelta: argumentsJson.slice(5) },
    { type: 'block-end', index: 0, block: { type: 'tool-call', id, name, arguments: argumentsJson } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: 5 } },
    { type: 'finish', reason: { kind: 'tool-calls' } },
  ]
}

export const name = 'llm-mock'

export class MockAdapter extends Llm {
  private cursor = 0

  constructor(
    ctx: Context,
    private script: (StreamChunk[] | ((options: GenerateOptions) => StreamChunk[]))[],
  ) {
    super(ctx)
  }

  async *stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const entry = this.script[this.cursor]
    if (!entry) throw new Error('MockAdapter: 剧本用完了')

    // 两种条目的寿命不同，这是本课的关键设计：
    // 函数条目是"常驻大脑"——每一轮都重新问它一次，像真模型那样只看当前请求做决策；
    // 静态条目是一次性剧本——读过就翻页，第二次 stream 就取不到了。
    if (typeof entry !== 'function') this.cursor += 1

    const chunks = typeof entry === 'function' ? entry(options) : entry
    for (const chunk of chunks) { yield chunk }
  }
}

/**
 * 假模型的"大脑"：看用户输入决定这一轮说什么。
 *
 * 真模型是靠训练数据学会"什么时候该调工具"的；我们没法训练，
 * 就用 if 把同样的决策写死。重点不在这段逻辑，而在于
 * **它输出的形状和真模型一模一样**——消费方完全感知不到差别。
 *
 * 注意签名收的是 GenerateOptions（整个请求），不是一句字符串：
 * 真模型看的是全部 messages，我们只看最后一条——至于是谁说的，
 * 在"请求即历史"之后已经不重要了，压缩摘要也是一条历史。
 */
export function decide(options: GenerateOptions): StreamChunk[] {
  const input = options.messages.at(-1)?.content ?? ''
  // 工具结果又喂回来了：这次该说人话了
  if (input.includes('°C')) {
    return textResponse(`${input}。出门看情况带把伞。`)
  }
  if (input.includes('刚才')) {
    // 只有模型能看见摘要时才答得上来；原始记录被 replace 顶掉之后就看不到了
    const summary = options.messages.find((message) => message.content.startsWith('（摘要）'))
    if (summary) return textResponse('你问了我北京天气，我查完还提醒了你带伞。')
    return textResponse('我没有历史记忆，每次请求只带当前这一句。')
  }
  if (input.includes('北京')) {
    return toolCallResponse('call-1', 'get_weather', { city: '北京' })
  }
  if (input.includes('天气')) {
    return toolCallResponse('call-2', 'get_weather', { city: '北京' })
  }
  // 新增：模型"选"了另一个工具。它不需要认识 calc 的实现，
  // 只要注册表里有这个名字，loop 就能把它调起来。
  if (input.includes('算') || input.includes('+')) {
    return toolCallResponse('call-3', 'calc', { a: 7, b: 6, op: '*' })
  }
  // 工具结果又喂回来了：算数结果是 "7 * 6 = 42" 这种形状。
  // 注意上面那句不能写成 includes('*')——那会把结果也当成"要算数"。
  if (/^[\d.]+\s*[-+*/]\s*[\d.]+\s*=/.test(input)) {
    return textResponse(`算好了：${input}`)
  }
  return textResponse(`我不知道怎么回答"${input}"，但我可以查天气、也会算数。`)
}

export function apply(ctx: Context) {
  ctx.plugin(MockAdapter, [decide])
}

import type { Context } from '@deepseek-ai/cordis'
import { Tools, type ToolSchema } from './tools.ts'
import type { ToolArgs, ToolDefinition, ToolResult } from './define-tool.ts'

export const name = 'tools-registry'

/**
 * Service Provider：一个基于 Map 的工具注册表。
 *
 * register() 是第 02 课的"注册即效果"：注册方插件一卸载，
 * 这个工具定义自动从表里消失。
 */
class MapTools extends Tools {
  private readonly definitions = new Map<string, ToolDefinition>()
  private counter = 0

  register(definition: ToolDefinition): () => void {
    // ctx.effect 是"本插件卸载时自动执行"的注册点
    return this.ctx.effect(() => {
      this.definitions.set(definition.name, definition)
      // 注册即广播：谁想知道"现在有哪些工具"，挂这个事件就行
      this.ctx.emit('tools/change')
      return () => {
        this.definitions.delete(definition.name)
        this.ctx.emit('tools/change')
      }
    }, `tools.register(${definition.name})`)
  }

  get(name: string): ToolDefinition | undefined {
    return this.definitions.get(name)
  }

  list(): ToolDefinition[] {
    return [...this.definitions.values()]
  }

  schemas(): ToolSchema[] {
    // 只挑三个字段——execute 留在本地，不随请求出门
    return [...this.definitions.values()].map(({ name, description, parameters }) => ({
      name,
      description,
      parameters,
    }))
  }

  async call(name: string, args: unknown): Promise<ToolResult> {
    const definition = this.definitions.get(name)
    const callId = `call-${++this.counter}`
    if (!definition) {
      return { ok: false, callId, name, error: `工具不存在：${name}` }
    }
    try {
      const value = await definition.execute((args ?? {}) as ToolArgs, { callId })
      return { ok: true, callId, name, value }
    } catch (error) {
      return { ok: false, callId, name, error: error instanceof Error ? error.message : String(error) }
    }
  }
}

export function apply(ctx: Context) {
  ctx.plugin(MapTools)
}

import { Service, type Context } from '@deepseek-ai/cordis'
import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

/**
 * 一条会话记录。`data` 的形状由 `type` 决定。
 *
 * harness 真身里这是 `SessionEventMap`（packages/core/session/src/types.ts 第 281 行），
 * 同样是"一个 type 对应一种 data"的表。
 */
export interface SessionRecordMap {
  /** 用户说了一句话。 */
  'user/message': { content: string }
  /** 模型回答了一轮。 */
  'assistant/message': { text: string }
  /** 模型请求调用一个工具，arguments 是它吐出的原始 JSON 字符串。 */
  'tool/call': { callId: string; name: string; arguments: string }
  /** 工具执行完了，value 是返回值，isError 标记成功失败。 */
  'tool/result': { callId: string; name: string; value: unknown; isError: boolean }
}

/** 任意一种会话记录。 */
export type SessionRecord =
  | { [K in keyof SessionRecordMap]: { type: K; data: SessionRecordMap[K] } }[keyof SessionRecordMap]

/**
 * 会产生模型可见消息的记录类型。
 *
 * 日志里还有别的行（turn 边界、失败尝试），它们不进模型请求，
 * 只是排查问题时看的痕迹。harness 真身叫 `SurfaceEventType`
 * （packages/core/session/src/types.ts 第 439 行）。
 */
export type SurfaceRecordType = 'user/message' | 'assistant/message' | 'tool/result'

/** 一条记录在"模型能看到的历史"里的落点。 */
export type SurfaceOp =
  /** 追加到末尾：正常路径。 */
  | 'append'
  /** 替换一段已有节点：压缩上下文时用，被替换的行在日志里还在，只是不再进模型请求。 */
  | { op: 'replace'; startSeq: number; endSeq: number }

/**
 * 落盘的一行。
 *
 * 这是判别联合：`switch (line.type)` 会收窄 `line.data` 的类型，
 * 不用写任何断言。写法照抄 harness 真身的 `SessionEvent`
 * （packages/core/session/src/types.ts 第 493 行）——
 * `{ [K in ...]: {...} }[T]` 这层映射就是为了让联合生效。
 */
export type SessionLine = {
  [K in keyof SessionRecordMap]: {
    /** 会话内单调递增的序号，从 1 开始。 */
    readonly seq: number
    /** 写入时刻，Unix 毫秒。 */
    readonly time: number
    readonly type: K
    readonly data: SessionRecordMap[K]
    /** 它怎么进入模型可见历史。只有会产生消息的行带这个字段。 */
    readonly surfaceOp?: K extends SurfaceRecordType ? SurfaceOp : never
  }
}[keyof SessionRecordMap]

declare module '@deepseek-ai/cordis' {
  interface Context { session: Session }
}

/** 一条喂给模型的请求消息。 */
export interface ChatMessage {
  readonly role: 'user' | 'assistant' | 'tool'
  readonly content: string
}

/**
 * Service Definition：把"发生过的事"写进一条只增不减的日志。
 *
 * 这是 harness 的**唯一事实来源**。第 12 课的 agent loop 只在内存里跑，
 * 进程一退全忘了；有了它，任何时候都能把对话重放出来。
 */
export abstract class Session extends Service {
  constructor(ctx: Context) { super(ctx, 'session') }

  /**
   * 追加一条记录。
   * @param record - 记录内容。
   * @param op - 它怎么进入模型可见历史，默认 `'append'`。
   * @returns 分配到的序号。
   */
  abstract append(record: SessionRecord, op?: SurfaceOp): number

  /** 目前为止的全部记录，按 seq 升序。 */
  abstract list(): readonly SessionLine[]

  /**
   * 把日志折叠成模型能看的历史。
   *
   * 只走会产生消息的行；`replace` 标记的行会顶掉它覆盖的那一段。
   * 这就是 harness 的 `deriveMessages()`——每次请求前都重新折一遍，
   * 所以日志和模型看到的东西永远一致。
   */
  abstract deriveMessages(): ChatMessage[]

  /** 磁盘上已经有多少条记录——恢复来的，还是新起的。 */
  abstract readonly restoredCount: number

  /**
   * 从磁盘读回一个 session 的全部记录。
   *
   * 第一行是头行（`type: 'session'`），记录格式版本；剩下的是记录行。
   * 版本对不上直接抛错——**拒绝加载比猜着加载安全**。
   * @param file - session.jsonl 的路径。
   * @returns 按 seq 升序的记录。
   */
  static load(file: string): readonly SessionLine[] {
    const text = readFileSync(file, 'utf8')
    const lines = text.split('\n')
      .filter((line) => line.length > 0)
      .map((line) => JSON.parse(line) as SessionFileLine)
    const [header, ...rest] = lines
    if (header.type !== 'session') {
      throw new Error(`session 文件第一行必须是头行，实际是 ${String(header.type)}`)
    }
    if (header.version !== SESSION_FORMAT_VERSION) {
      throw new Error(
        `session 格式版本不匹配：文件是 v${header.version}，本程序只会 v${SESSION_FORMAT_VERSION}`,
      )
    }
    // 剩下的都是记录行；头行在上面已经核对掉了
    return rest.filter(isSessionLine)
  }
}

/** 头行不是记录。 */
function isSessionLine(line: SessionFileLine): line is SessionLine {
  return line.type !== 'session'
}

/**
 * 落盘文件的一行：要么是头行，要么是一条记录。
 *
 * 头行不是记录——它没有 `seq`，只说明"这个文件是什么格式的"。
 * harness 真身在 packages/session/session-persistence-jsonl/src/format.ts
 * 里也叫 `HeaderLine`，`type` 字段值是 `'session'`。
 */
export type SessionFileLine =
  | { type: 'session'; version: number }
  | SessionLine

/** 当前会话日志的格式版本。harness 真身是 `SESSION_FORMAT_VERSION = 4`。 */
export const SESSION_FORMAT_VERSION = 1

/**
 * Service Provider：JSONL 落地。
 *
 * 每行一条 JSON，追加写文件。harness 真身（packages/session/session-persistence-jsonl）
 * 用 zstd 压缩、分代文件名和原子替换，我们保留最核心的那个决定：
 * **append-only，写出去的行永不改写**。
 */
export class JsonlSession extends Session {
  private seq = 0
  private readonly records: SessionLine[] = []
  private readonly file: string
  /** 磁盘上已有多少条记录——恢复来的，还是新起的。 */
  readonly restoredCount: number

  constructor(ctx: Context, config: { file: string }) {
    super(ctx)
    this.file = join(config.file, 'session.jsonl')
    mkdirSync(dirname(this.file), { recursive: true })

    // 恢复：接着磁盘上已有的行往下写，seq 继续往上加
    if (existsSync(this.file)) {
      const existing = Session.load(this.file)
      this.records.push(...existing)
      this.seq = existing.at(-1)?.seq ?? 0
      this.restoredCount = existing.length
    } else {
      this.restoredCount = 0
      // 新文件第一行写头行：以后谁来读这个文件，先核对版本
      appendFileSync(this.file, `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`)
    }
  }

  append(record: SessionRecord, op: SurfaceOp = 'append'): number {
    this.seq += 1
    const line = this.toLine(this.seq, record, op)
    this.records.push(line)
    // 追加写：只往文件末尾加字节，不动已有内容
    appendFileSync(this.file, `${JSON.stringify(line)}\n`)
    return line.seq
  }

  /** 拼一行。`tool/call` 不进模型可见历史——它已经被同一轮的 assistant/message 代表了。 */
  private toLine(seq: number, record: SessionRecord, op: SurfaceOp): SessionLine {
    const time = Date.now()
    switch (record.type) {
      case 'user/message':
        return { seq, time, type: 'user/message', data: record.data, surfaceOp: op }
      case 'assistant/message':
        return { seq, time, type: 'assistant/message', data: record.data, surfaceOp: op }
      case 'tool/result':
        return { seq, time, type: 'tool/result', data: record.data, surfaceOp: op }
      case 'tool/call':
        return { seq, time, type: 'tool/call', data: record.data }
    }
  }

  list(): readonly SessionLine[] { return this.records }

  /**
   * 折叠日志。
   *
   * `surface` 是一个"模型能看到哪些 seq"的有序列表。
   * 追加就 push；替换就把 [startSeq, endSeq] 那段挖掉、换成新行。
   * 被挖掉的行在日志里一行不少，只是不再进模型请求。
   */
  deriveMessages(): ChatMessage[] {
    const surface: SessionLine[] = []
    for (const line of this.records) {
      const op = line.surfaceOp
      if (op === undefined) continue          // 非消息行：跳过
      if (op === 'append') { surface.push(line); continue }
      // replace：挖掉旧段，在原来的位置插入新行
      const start = surface.findIndex((node) => node.seq === op.startSeq)
      const end = surface.findIndex((node) => node.seq === op.endSeq)
      if (start === -1 || end === -1) continue
      surface.splice(start, end - start + 1, line)
    }
    return surface.map(toChatMessage)
  }

  /**
   * 把整个文件重写一遍。
   *
   * 注意头行得带上——它是文件的一部分，不是记录。
   * 这是本文件里唯一一处"整份重写"的路径，正常写入走的是 append。
   */
  flush(): void {
    const header = `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`
    const body = this.records.map((line) => `${JSON.stringify(line)}\n`).join('')
    writeFileSync(this.file, header + body)
  }
}

/** 把一条消息行翻译成模型请求里的消息。 */
function toChatMessage(line: SessionLine): ChatMessage {
  switch (line.type) {
    case 'user/message':
      return { role: 'user', content: line.data.content }
    case 'assistant/message':
      return { role: 'assistant', content: line.data.text }
    case 'tool/result':
      return { role: 'tool', content: String(line.data.value) }
    case 'tool/call':
      // 走不到这里：tool/call 没有 surfaceOp，deriveMessages 已经把它过滤掉了
      return { role: 'assistant', content: `${line.data.name}(${line.data.arguments})` }
  }
}

export function apply(ctx: Context) {
  ctx.plugin(JsonlSession, { file: '.sessions/demo' })
}

import { Service, type Context } from '@deepseek-ai/cordis'
import type { ToolDefinition, ToolParameters, ToolResult } from './define-tool.ts'

declare module '@deepseek-ai/cordis' {
  interface Context {
    tools: Tools
  }
  interface Events {
    /**
     * 有工具注册进来或摘出去。
     *
     * harness 真身（packages/core/tools/src/index.ts 第 208 行）也叫
     * `tools/change`。为什么需要它？因为插件的加载顺序由依赖拓扑决定，
     * **不写插件的人控制不了谁先谁后**。想知道"现在有哪些工具"，
     * 只能等注册表通知，不能在启动时假设它已经满了。
     * @mode emit
     */
    'tools/change'(): void
  }
}

/**
 * Service Definition：工具注册表。
 *
 * 它只知道"工具长什么样、怎么被调用"，不知道任何一个工具的具体实现。
 */
export abstract class Tools extends Service {
  constructor(ctx: Context) {
    super(ctx, 'tools')
  }

  /** 注册一个工具定义，返回的摘除函数随注册方插件的卸载自动执行。 */
  abstract register(definition: ToolDefinition): () => void

  /** 按名字取定义，没有则 undefined。 */
  abstract get(name: string): ToolDefinition | undefined

  /** 当前全部定义，按注册顺序排列。 */
  abstract list(): ToolDefinition[]

  /**
   * 递给模型看的工具清单。
   *
   * 只保留 name / description / parameters 三个字段——
   * `execute` 是本地代码，发给模型没有意义，还可能泄露实现细节。
   * harness 真身 [packages/core/tools/src/index.ts 第 1260 行](../../../deepseek-harness/packages/core/tools/src/index.ts#L1260)
   * 的 `schemas()` 干的就是这件事，注释里那词叫 allowlist（白名单）。
   */
  abstract schemas(): ToolSchema[]

  /** 执行一个工具；任何失败都收进 ToolResult，不往外抛。 */
  abstract call(name: string, args: unknown): Promise<ToolResult>
}

/** 递给模型看的工具描述：三个字段，缺一不可。 */
export interface ToolSchema {
  readonly name: string
  readonly description: string
  readonly parameters: ToolParameters
}

import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from './define-tool.ts'

export const name = 'weather-tool'

// 忘了这行，ctx.tools 会抛 "cannot get property "tools" without inject"
// （第 03 课的规矩：要拿 ctx 上的服务，必须先声明 inject）
export const inject = ['tools']

/**
 * Service Provider 的角色之一：往 ctx.tools 里放一个工具。
 *
 * 真身（packages/web/tool-web/src/search.ts）长这样：
 *   ctx.tools.register(defineTool({ name: 'web_search', ... }))
 * 我们连形状都照抄，只是把网络请求换成了假数据。
 */
export function apply(ctx: Context) {
  ctx.tools.register(defineTool({
    name: 'get_weather',
    description: '查询一个城市的天气。需要城市名。',
    parameters: {
      city: {
        type: 'string',
        required: true,
        description: '城市名，例如 "北京"',
      },
      unit: {
        type: 'string',
        enum: ['celsius', 'fahrenheit'],
        description: '温度单位，默认摄氏度。',
      },
    },
    async execute(args) {
      const city = String(args.city ?? '')
      // Keyless：假数据，不联网
      const table: Record<string, string> = {
        北京: '晴，12°C',
        上海: '小雨，18°C',
      }
      const forecast = table[city] ?? '晴，20°C（默认值）'
      const unit = args.unit === 'fahrenheit' ? '（已换算为华氏）' : ''
      return `${city}：${forecast}${unit}`
    },
  }))
}

import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from './define-tool.ts'

export const name = 'calc-tool'

export const inject = ['tools']

/**
 * 第二个工具插件。
 *
 * 它和 weather.ts 长得一模一样，唯一的差别是干的事不同。
 * 这就是"注册表"的全部意义：**加工具不用碰 loop 一行代码**，
 * 只要新写一个插件、在 cordis.yml 里加一行。
 */
export function apply(ctx: Context) {
  ctx.tools.register(defineTool({
    name: 'calc',
    description: '算一道四则运算。支持加减乘除。',
    parameters: {
      a: { type: 'number', required: true, description: '左操作数' },
      b: { type: 'number', required: true, description: '右操作数' },
      op: { type: 'string', enum: ['+', '-', '*', '/'], description: '运算符' },
    },
    execute(args) {
      const a = Number(args.a)
      const b = Number(args.b)
      switch (args.op) {
        case '+': return `${a} + ${b} = ${a + b}`
        case '-': return `${a} - ${b} = ${a - b}`
        case '*': return `${a} * ${b} = ${a * b}`
        case '/': return `${a} / ${b} = ${b === 0 ? '除数不能为 0' : a / b}`
        default:
          return `不支持的运算符：${String(args.op)}`
      }
    },
  }))
}

/**
 * 简化版 defineTool。
 *
 * harness 真身（packages/core/tools/src/schema.ts 第 554 行）在这里做三件事：
 * 1. 把手写的 JSON Schema DSL 编译成标准 JSON Schema，并用它校验模型传来的参数；
 * 2. 从 DSL 反推出 TypeScript 类型，让 execute 里的 args 有补全；
 * 3. 把校验包在 execute 外层，任何违规都以 ToolArgsError 的形式抛出。
 *
 * 第 10 课只做了"组装"。本课补上第 1 和第 3 件事——**校验**。
 */

import { compileNode, ToolArgsError, validateValue, type JsonSchemaNode, type SchemaSpec } from './json-schema.ts'

/** 模型传来的参数：一个 JSON 对象。 */
export type ToolArgs = Record<string, unknown>

/** 参数 schema：一棵 JSON Schema 树。 */
export type ToolParameters = Record<string, unknown>

/** 执行上下文：harness 真身叫 ToolRunContext，这里只保留两个字段。 */
export interface ToolRunContext {
  /** 本次调用的 id，由注册表分配。 */
  readonly callId: string
  /** 取消信号：调用方 abort 时，工具应当尽快收手。 */
  readonly signal?: AbortSignal
}

/** 一次工具调用的结果。成功失败都走这个壳，不抛异常。 */
export type ToolResult =
  | { ok: true; callId: string; name: string; value: unknown }
  | { ok: false; callId: string; name: string; error: string }

/** 一个工具的完整定义。 */
export interface ToolDefinition {
  readonly name: string
  /** 写给模型看的说明，模型据此决定要不要调用它。 */
  readonly description: string
  /** 编译后的参数 schema，既校验也进模型请求。 */
  readonly parameters: ToolParameters
  /** 具体干活的部分。参数已通过校验。 */
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}
export interface DefineToolOptions {
  name: string
  description: string
  /** 手写的参数 schema（第 11 课细讲）。 */
  parameters?: Record<string, SchemaSpec>
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}

/**
 * 定义工具。
 * @param options - 工具的名称、说明、参数 schema 和执行体。
 * @returns 一个 registry-ready 的定义，execute 已自带参数校验。
 */
export function defineTool(options: DefineToolOptions): ToolDefinition {
  const compiled = compileParameters(options.parameters)

  return {
    name: options.name,
    description: options.description,
    parameters: compiled,
    async execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> {
      // 校验发生在用户的 execute 之前：不合规的参数根本到不了业务代码
      const violations = validateValue(compiled, args)
      if (violations.length > 0) {
        throw new ToolArgsError(options.name, violations)
      }
      return options.execute(args, exec)
    },
  }
}

/** 把"每个参数一条声明"的手写 DSL 编译成一个对象根的 JSON Schema。 */
function compileParameters(spec: Record<string, SchemaSpec> | undefined): JsonSchemaNode {
  if (spec === undefined) return { type: 'object', additionalProperties: true }
  const node = compileNode({ type: 'object', properties: spec })
  // 顶层参数对象是"开放"的：模型可以额外带字段，不像 output schema 那样严苛
  node.additionalProperties = true
  return node
}

/**
 * 简化版 JSON Schema 校验器。
 *
 * harness 真身在 packages/core/tools/src/json-schema.ts，它只接受一个
 * 受限的 JSON Schema 子集：一个标量 type、对象 properties/required、
 * 布尔 additionalProperties、数组 items、标量 enum/const。任何子集之外的
 * 关键字直接拒绝，而不是"接受但不校验"——因为那会给作者一种虚假的安全感。
 *
 * 本课实现同款子集的教学版。
 */

/** 校验错误：模型传来的参数不符合声明。 */
export class ToolArgsError extends Error {
  constructor(
    readonly toolName: string,
    readonly violations: string[],
  ) {
    super(`invalid arguments: ${violations.join('; ')}`)
    this.name = 'ToolArgsError'
  }
}

/** 手写 DSL 里的一个节点。 */
export type SchemaSpec =
  | { type: 'string'; required?: true; description?: string; enum?: readonly string[] }
  | { type: 'number'; required?: true; description?: string }
  | { type: 'boolean'; required?: true; description?: string }
  | { type: 'array'; required?: true; description?: string; items?: SchemaSpec }
  | { type: 'object'; required?: true; description?: string; additionalProperties?: boolean; properties?: Record<string, SchemaSpec> }

/** 编译后的 JSON Schema 节点（只保留校验需要的字段）。 */
export interface JsonSchemaNode {
  type: string
  description?: string
  enum?: readonly (string | number | boolean | null)[]
  required?: string[]
  additionalProperties?: boolean
  items?: JsonSchemaNode
  properties?: Record<string, JsonSchemaNode>
  /** 允许作为普通 JSON 对象在工具之间传递。 */
  [key: string]: unknown
}

/**
 * 把手写 DSL 的一个节点编译成 JSON Schema。
 * @param spec - 手写 DSL 节点。
 * @returns 编译后的 JSON Schema 节点。
 */
export function compileNode(spec: SchemaSpec): JsonSchemaNode {
  const node: JsonSchemaNode = { type: spec.type }
  if (spec.description !== undefined) node.description = spec.description
  if ('enum' in spec && spec.enum !== undefined) node.enum = spec.enum
  if (spec.type === 'array' && spec.items !== undefined) {
    node.items = compileNode(spec.items)
  }
  if (spec.type === 'object') {
    node.additionalProperties = spec.additionalProperties ?? false
    if (spec.properties !== undefined) {
      node.properties = {}
      node.required = []
      for (const [key, child] of Object.entries(spec.properties)) {
        node.properties[key] = compileNode(child)
        if (child.required === true) node.required.push(key)
      }
      if (node.required.length === 0) delete node.required
    }
  }
  return node
}

/**
 * 校验一个值是否符合编译后的 schema。
 * @param schema - 编译后的 schema。
 * @param value - 待校验的值，任意来源。
 * @param path - 当前路径，用于错误信息定位。
 * @returns 违规列表；空数组表示通过。
 */
export function validateValue(schema: JsonSchemaNode, value: unknown, path = '$'): string[] {
  const violations: string[] = []
  const at = (suffix: string) => suffix === '' ? path : `${path}.${suffix}`

  switch (schema.type) {
    case 'string':
      if (typeof value !== 'string') {
        violations.push(`${at('')} 必须是字符串，收到 ${describe(value)}`)
        break
      }
      if (schema.enum !== undefined && !schema.enum.includes(value)) {
        violations.push(`${at('')} 必须是 ${schema.enum.map((entry) => JSON.stringify(entry)).join(' / ')} 之一`)
      }
      break

    case 'number':
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        violations.push(`${at('')} 必须是数字，收到 ${describe(value)}`)
      }
      break

    case 'boolean':
      if (typeof value !== 'boolean') {
        violations.push(`${at('')} 必须是布尔值，收到 ${describe(value)}`)
      }
      break

    case 'array': {
      if (!Array.isArray(value)) {
        violations.push(`${at('')} 必须是数组，收到 ${describe(value)}`)
        break
      }
      if (schema.items === undefined) break
      value.forEach((entry, index) => {
        violations.push(...validateValue(schema.items!, entry, `${path}[${index}]`))
      })
      break
    }

    case 'object': {
      if (typeof value !== 'object' || value === null || Array.isArray(value)) {
        violations.push(`${at('')} 必须是对象，收到 ${describe(value)}`)
        break
      }
      const record = value as Record<string, unknown>
      for (const key of schema.required ?? []) {
        if (record[key] === undefined) {
          violations.push(`${at(key)} 是必填项，但没有提供`)
        }
      }
      for (const [key, child] of Object.entries(schema.properties ?? {})) {
        if (record[key] === undefined) continue
        violations.push(...validateValue(child, record[key], at(key)))
      }
      if (schema.additionalProperties === false) {
        for (const key of Object.keys(record)) {
          if (schema.properties === undefined || !(key in schema.properties)) {
            violations.push(`${at(key)} 不是声明过的字段（additionalProperties: false）`)
          }
        }
      }
      break
    }

    default:
      throw new Error(`不支持的 schema 类型：${schema.type}`)
  }

  return violations
}

/** 把一个未知值描述成一句人能看懂的话，用于错误信息。 */
function describe(value: unknown): string {
  if (value === null) return 'null'
  if (Array.isArray(value)) return '数组'
  if (typeof value === 'object') return '对象'
  return JSON.stringify(value) ?? String(value)
}

import { Service, type Context } from '@deepseek-ai/cordis'

declare module '@deepseek-ai/cordis' {
  interface Context { llm: Llm }
  interface Events {
    /** 消费方向 llm 服务发出一次请求，由提供方处理。 */
    'llm/generate'(input: string): void
  }
}

export type StreamChunk =
  | { type: 'block-start'; index: number; blockType: 'text' | 'tool-call' }
  | { type: 'text-delta'; index: number; text: string }
  | { type: 'reasoning-delta'; index: number; text: string }
  | { type: 'tool-call-delta'; index: number; id: string; name?: string; argumentsDelta: string }
  | { type: 'block-end'; index: number; block: ContentBlock }
  | { type: 'usage'; usage: { inputTokens: number; outputTokens: number } }
  | { type: 'finish'; reason: { kind: 'stop' | 'tool-calls' | 'max-tokens' | 'error' } }

export type ContentBlock =
  | { type: 'text'; text: string }
  | { type: 'tool-call'; id: string; name: string; arguments: string }

export interface GenerateOptions {
  messages: { role: 'system' | 'user' | 'assistant' | 'tool'; content: string }[]
  maxTokens?: number
  signal?: AbortSignal
}

export abstract class Llm extends Service {
  constructor(ctx: Context) { super(ctx, 'llm') }
  abstract stream(options: GenerateOptions): AsyncIterable<StreamChunk>
}

import type { Context } from '@deepseek-ai/cordis'
import type { GenerateOptions, StreamChunk } from './llm.ts'
import type { SessionLine } from './session.ts'

declare module '@deepseek-ai/cordis' {
  interface Events {
    /** 用户说了一句话，agent 处理一轮。 */
    'agent/turn'(input: string): void
    /** 把前面的轮次折叠成一条摘要。 */
    'agent/compact'(fromSeq: number, toSeq: number, summary: string): void
  }
}

export const name = 'agent'
export const inject = ['llm', 'tools', 'session']

/** 一轮对话里模型给出的指令：要么说话，要么调工具。 */
type ModelTurn =
  | { kind: 'text'; text: string }
  | { kind: 'tool-call'; id: string; name: string; args: Record<string, unknown> }

/**
 * Consumer：agent loop 的第四版。
 *
 * 前三版跑完就忘（或者只记得自己那次）。本课补上**能力协商**：
 * 这个插件声明了自己要 `llm`、`tools`、`session` 三项能力，cordis 就
 * 替我们盯着它们。齐了才启动，缺了就 FAILED——而不是等第一次用的
 * 时候才炸。
 */
export function apply(ctx: Context) {
  ctx.on('agent/turn', (input) => { void run(input) })
  ctx.on('agent/compact', (fromSeq, toSeq, summary) => { compact(fromSeq, toSeq, summary) })

  // 启动第一件事：报告从磁盘恢复了什么
  const restored = ctx.session.restoredCount
  if (restored > 0) {
    console.log(`=== 从磁盘恢复了 ${restored} 条记录，seq 接着 #${ctx.session.list().at(-1)?.seq ?? 0} 往下编 ===`)
    console.log('=== 模型看到的历史 ===')
    for (const message of ctx.session.deriveMessages()) {
      console.log(`[${message.role}] ${message.content}`)
    }
    // 恢复之后直接问一个需要历史才能答的问题
    setTimeout(() => ctx.emit('agent/turn', '刚才我问了什么？'), 50)
  } else {
    console.log('=== 没有找到历史，开一个新会话 ===')
    setTimeout(() => ctx.emit('agent/turn', '北京天气怎么样？'), 50)
    setTimeout(() => ctx.emit('agent/turn', '帮我算 7*6'), 100)
    setTimeout(() => ctx.emit('agent/turn', '你好'), 150)
    // 三轮聊完，把 #1~#10 折成一条摘要。
    // endSeq 必须是**摘要之前最后一条记录**（#10）：摘要自己落在 #11，
    // 它还没进日志，写 11 会让"找终点"的那一步落空，压缩被静默跳过。
    setTimeout(() => ctx.emit('agent/compact', 1, 10, '（摘要）用户问了北京天气和一道乘法，模型分别调了 get_weather 和 calc。'), 200)
  }
  setTimeout(() => replay(), 400)

  /**
   * 工具清单：等注册表通知，不自己猜时机。
   *
   * 为什么不能在 apply 函数体里直接 `ctx.tools.schemas()`？因为 cordis 按
   * **依赖拓扑**排插件的加载顺序：agent 声明了 `inject: ['llm','tools','session']`，
   * 它要的三个服务必须先把 provider 建好，所以 agent 的 apply 排在 provider
   * 之后、**但排在 weather-tool / calc-tool 之前**——后两者只 inject 了
   * `tools`，拓扑上没人催它们，就按 cordis.yml 的顺序落到最后。
   *
   * 也就是说：apply 函数体执行的那一刻，注册表**恰好是空的**。
   * 而这个顺序由依赖关系决定，写 yml 的人控制不了。
   * 所以"现在有哪些工具"这件事，只能等注册表通知，不能自己数。
   *
   * 那为什么还要 `setTimeout` 包一层？因为插件是一个个加载的，
   * weather-tool 注册时会响一次，calc-tool 注册时又响一次。
   * 每次响都打印，就会打出两份不完整的清单。
   * 所以：**每次变化只重新排一次打印，等本轮事件循环安静下来再打**。
   */
  let scheduled = false
  ctx.on('tools/change', () => {
    if (scheduled) return
    scheduled = true
    setTimeout(printTools, 0)
  })

  function printTools() {
    console.log('=== 模型能选的工具 ===')
    for (const schema of ctx.tools.schemas()) {
      console.log(`- ${schema.name}：${schema.description}`)
    }
  }

  /**
   * 对账：我声明要的能力，注册表现在真的都有了吗？
   *
   * 这就是本课的主题。`ctx.fiber.inject` 是本插件声明的那张需求表，
   * `ctx.reflect.props` 是全应用登记过的服务名册。
   * 两边一减，缺谁一目了然——而且是在**启动阶段**减，不是等
   * 某次调用踩空了才炸。
   *
   * 注意它读的是 `props`（登记册），不是 `store`（实例）。
   * 登记册里有名字，不代表现在有实例——第 19 课的工具就是
   * 先登记、后注册的。缺名字才是真缺。
   */
  function reportCapabilities() {
    console.log('\n=== 能力对账 ===')
    for (const service of Object.keys(ctx.fiber.inject)) {
      const registered = Object.hasOwn(ctx.reflect.props, service)
      const status = registered ? '齐' : '缺'
      console.log(`- ${service}：${status}`)
      if (!registered) {
        console.log(`  没人提供 ${service}——cordis.yml 里少了一个 provider，或者它自己加载失败了`)
      }
    }
  }

  setTimeout(reportCapabilities, 300)

  async function run(input: string) {
    console.log(`\n=== 用户说：${input} ===`)
    ctx.session.append({ type: 'user/message', data: { content: input } })

    // 关键一行：messages 不是手搓的，是从日志折出来的
    const options: GenerateOptions = { messages: ctx.session.deriveMessages() }
    const turn = await collect(ctx.llm.stream(options))

    switch (turn.kind) {
      case 'text':
        console.log(`[模型回答] ${turn.text}`)
        ctx.session.append({ type: 'assistant/message', data: { text: turn.text } })
        break

      case 'tool-call': {
        console.log(`[模型决定] 调用 ${turn.name}，参数 ${JSON.stringify(turn.args)}`)
        // 注意：arguments 存的是模型吐出的**原始字符串**，不是我们 parse 后的对象
        ctx.session.append({
          type: 'tool/call',
          data: { callId: turn.id, name: turn.name, arguments: JSON.stringify(turn.args) },
        })
        await executeTool(turn)
        break
      }
    }
  }

  async function executeTool(call: Extract<ModelTurn, { kind: 'tool-call' }>) {
    const result = await ctx.tools.call(call.name, call.args)
    if (result.ok) {
      console.log(`[工具返回] ${String(result.value)}`)
      ctx.session.append({
        type: 'tool/result',
        data: { callId: call.id, name: call.name, value: result.value, isError: false },
      })

      // 工具结果有了，再问模型一次，让它说人话——这次它看得见刚才的调用和返回
      const follow = await collect(ctx.llm.stream({ messages: ctx.session.deriveMessages() }))
      if (follow.kind === 'text') {
        console.log(`[模型回答] ${follow.text}`)
        ctx.session.append({ type: 'assistant/message', data: { text: follow.text } })
      }
    } else {
      console.log(`[工具失败] ${result.error}`)
      ctx.session.append({
        type: 'tool/result',
        data: { callId: call.id, name: call.name, value: result.error, isError: true },
      })
    }
  }

  /**
   * 压缩：往日志里**追加**一条摘要，标记它顶掉 [fromSeq, toSeq]。
   *
   * 注意是追加，不是删除。旧的行一条不少地还在文件里，
   * 只是从此不进模型请求——这就是 harness 的 compaction 路子。
   */
  function compact(fromSeq: number, toSeq: number, summary: string) {
    console.log(`\n=== 压缩：#${fromSeq}~#${toSeq} 折成一条摘要 ===`)
    const seq = ctx.session.append(
      { type: 'assistant/message', data: { text: summary } },
      { op: 'replace', startSeq: fromSeq, endSeq: toSeq },
    )
    console.log(`摘要落成 #${seq}，它顶掉了 #${fromSeq}~#${toSeq}`)
  }

  /** 重放：日志是唯一事实来源，屏幕上的字早没了，日志还在。 */
  function replay() {
    const lines = ctx.session.list()
    console.log(`\n=== 日志全量（${lines.length} 条）===`)
    for (const line of lines) {
      console.log(`#${line.seq} [${line.type}] ${describe(line)}${opNote(line)}`)
    }

    const messages = ctx.session.deriveMessages()
    console.log(`\n=== 模型看到的历史（折叠后 ${messages.length} 条）===`)
    for (const message of messages) {
      console.log(`[${message.role}] ${message.content}`)
    }
  }

  /** 压缩标记只在日志里可见，模型那一侧看不到。 */
  function opNote(line: SessionLine): string {
    const op = line.surfaceOp
    if (op === undefined || op === 'append') return ''
    return `　← replace #${op.startSeq}~#${op.endSeq}`
  }

  function describe(line: SessionLine): string {
    switch (line.type) {
      case 'user/message':
        return line.data.content
      case 'assistant/message':
        return line.data.text
      case 'tool/call':
        return `${line.data.name}(${line.data.arguments})`
      case 'tool/result':
        return line.data.isError ? `失败：${String(line.data.value)}` : String(line.data.value)
    }
  }
}

/**
 * 把流式 chunk 收成一个完整的 ModelTurn。
 *
 * 这是第 09 课 `for await` 循环的升级版：不再是打印，
 * 而是**按 index 把碎片拼回整块**。真模型的工具参数被切成很多片，
 * 必须拼起来才能 JSON.parse。
 */
async function collect(stream: AsyncIterable<StreamChunk>): Promise<ModelTurn> {
  // index → 已拼接的文本/参数
  const texts = new Map<number, string>()
  const calls = new Map<number, { id: string; name: string; arguments: string }>()

  for await (const chunk of stream) {
    switch (chunk.type) {
      case 'text-delta':
        texts.set(chunk.index, (texts.get(chunk.index) ?? '') + chunk.text)
        break
      case 'tool-call-delta': {
        const existing = calls.get(chunk.index) ?? { id: chunk.id, name: '', arguments: '' }
        // name 可能只在第一条 delta 上出现
        if (chunk.name !== undefined) existing.name = chunk.name
        existing.arguments += chunk.argumentsDelta
        calls.set(chunk.index, existing)
        break
      }
      case 'block-end':
        if (chunk.block.type === 'tool-call') {
          return { kind: 'tool-call', id: chunk.block.id, name: chunk.block.name, args: parseArgs(chunk.block.arguments) }
        }
        break
      case 'finish':
        break
      default:
        break
    }
  }

  const text = [...texts.entries()].sort(([a], [b]) => a - b).map(([, value]) => value).join('')
  return { kind: 'text', text }
}

/** 解析工具参数；解析失败时返回空对象——校验层会给出准确报错。 */
function parseArgs(json: string): Record<string, unknown> {
  try {
    const parsed: unknown = JSON.parse(json)
    return typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)
      ? parsed as Record<string, unknown>
      : {}
  } catch {
    return {}
  }
}

import type { Context } from '@deepseek-ai/cordis'
import { Llm, type GenerateOptions, type StreamChunk } from './llm.ts'

export function textResponse(text: string): StreamChunk[] {
  return [
    { type: 'block-start', index: 0, blockType: 'text' },
    ...Array.from(text, (char): StreamChunk => ({ type: 'text-delta', index: 0, text: char })),
    { type: 'block-end', index: 0, block: { type: 'text', text } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: text.length } },
    { type: 'finish', reason: { kind: 'stop' } },
  ]
}

export function toolCallResponse(id: string, name: string, args: object): StreamChunk[] {
  const argumentsJson = JSON.stringify(args)
  return [
    { type: 'block-start', index: 0, blockType: 'tool-call' },
    { type: 'tool-call-delta', index: 0, id, name, argumentsDelta: argumentsJson.slice(0, 5) },
    { type: 'tool-call-delta', index: 0, id, argumentsDelta: argumentsJson.slice(5) },
    { type: 'block-end', index: 0, block: { type: 'tool-call', id, name, arguments: argumentsJson } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: 5 } },
    { type: 'finish', reason: { kind: 'tool-calls' } },
  ]
}

export const name = 'llm-mock'

export class MockAdapter extends Llm {
  private cursor = 0

  constructor(
    ctx: Context,
    private script: (StreamChunk[] | ((options: GenerateOptions) => StreamChunk[]))[],
  ) {
    super(ctx)
  }

  async *stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const entry = this.script[this.cursor]
    if (!entry) throw new Error('MockAdapter: 剧本用完了')

    // 两种条目的寿命不同，这是本课的关键设计：
    // 函数条目是"常驻大脑"——每一轮都重新问它一次，像真模型那样只看当前请求做决策；
    // 静态条目是一次性剧本——读过就翻页，第二次 stream 就取不到了。
    if (typeof entry !== 'function') this.cursor += 1

    const chunks = typeof entry === 'function' ? entry(options) : entry
    for (const chunk of chunks) { yield chunk }
  }
}

/**
 * 假模型的"大脑"：看用户输入决定这一轮说什么。
 *
 * 真模型是靠训练数据学会"什么时候该调工具"的；我们没法训练，
 * 就用 if 把同样的决策写死。重点不在这段逻辑，而在于
 * **它输出的形状和真模型一模一样**——消费方完全感知不到差别。
 *
 * 注意签名收的是 GenerateOptions（整个请求），不是一句字符串：
 * 真模型看的是全部 messages，我们只看最后一条——至于是谁说的，
 * 在"请求即历史"之后已经不重要了，压缩摘要也是一条历史。
 */
export function decide(options: GenerateOptions): StreamChunk[] {
  const input = options.messages.at(-1)?.content ?? ''
  // 工具结果又喂回来了：这次该说人话了
  if (input.includes('°C')) {
    return textResponse(`${input}。出门看情况带把伞。`)
  }
  if (input.includes('刚才')) {
    // 只有模型能看见摘要时才答得上来；原始记录被 replace 顶掉之后就看不到了
    const summary = options.messages.find((message) => message.content.startsWith('（摘要）'))
    if (summary) return textResponse('你问了我北京天气，我查完还提醒了你带伞。')
    return textResponse('我没有历史记忆，每次请求只带当前这一句。')
  }
  if (input.includes('北京')) {
    return toolCallResponse('call-1', 'get_weather', { city: '北京' })
  }
  if (input.includes('天气')) {
    return toolCallResponse('call-2', 'get_weather', { city: '北京' })
  }
  // 新增：模型"选"了另一个工具。它不需要认识 calc 的实现，
  // 只要注册表里有这个名字，loop 就能把它调起来。
  if (input.includes('算') || input.includes('+')) {
    return toolCallResponse('call-3', 'calc', { a: 7, b: 6, op: '*' })
  }
  // 工具结果又喂回来了：算数结果是 "7 * 6 = 42" 这种形状。
  // 注意上面那句不能写成 includes('*')——那会把结果也当成"要算数"。
  if (/^[\d.]+\s*[-+*/]\s*[\d.]+\s*=/.test(input)) {
    return textResponse(`算好了：${input}`)
  }
  return textResponse(`我不知道怎么回答"${input}"，但我可以查天气、也会算数。`)
}

export function apply(ctx: Context) {
  ctx.plugin(MockAdapter, [decide])
}

import type { Context } from '@deepseek-ai/cordis'
import { Service } from '@deepseek-ai/cordis'
import Schema from '@deepseek-ai/schemastery'

declare module '@deepseek-ai/cordis' {
  interface Events {
    /**
     * 目录加载器扫完一个目录，往 cordis 里加了一批插件。
     * @param dir - 被扫描的目录（相对路径）。
     * @param count - 从这个目录里加载了几个插件。
     * @mode emit
     */
    'plugin-directory/loaded'(dir: string, count: number): void
  }
}

/** 一个目录里的插件清单。 */
export interface DirectoryManifest {
  /** 这个目录是干什么的，出现在启动日志里。 */
  readonly purpose: string
  /** 插件文件列表，相对本目录。 */
  readonly plugins: readonly string[]
}

/** 插件配置：加载哪个目录。 */
export interface Config {
  /** 目录路径，相对 cordis.yml 所在位置。 */
  root: string
}

/** 同名 schema 给 Cordis 看：运行前验证，缺的补默认值。 */
export const Config: Schema<Config> = Schema.object({
  root: Schema.string().default('.'),
})

/**
 * 目录加载器：扫一个文件夹，把里面的插件一个个递给 cordis。
 *
 * 本课的主题。`ctx.loader.create()` 一次只认一个文件，
 * 而一个能力（比如"工具"）通常长在一个文件夹里。
 * 这个 Service 把"文件夹"变成加载单位。
 */
export abstract class PluginDirectory extends Service {
  constructor(ctx: Context) { super(ctx, 'pluginDirectory') }

  /**
   * 加载一个目录。
   * @param dir - 目录路径，相对 cordis.yml 所在位置。
   * @returns 从这个目录里加载了几个插件。
   */
  abstract load(dir: string): Promise<number>
}

/**
 * Service Provider：读 manifest.ts，逐个 ctx.loader.create。
 *
 * 为什么不直接 `readdirSync` 扫文件？因为**显式清单比目录扫描安全**：
 * 一个 `_backup.ts`、一个临时 `test.ts` 都会被扫进来，而它们可能
 * 不是插件，或者是不该现在加载的插件。harness 真身的
 * packages/ 也是靠 package.json 的 exports 声明，不是扫文件名。
 */
export class MapPluginDirectory extends PluginDirectory {
  async load(dir: string): Promise<number> {
    const manifestUrl = new URL(`${dir.replace(/\/$/, '')}/manifest.js`, this.ctx.baseUrl)
    const manifest = (await import((globalThis as any).__DSH_MANIFEST__ ?? manifestUrl.href)) as { default: DirectoryManifest }

    let count = 0
    for (const plugin of manifest.default.plugins) {
      const url = new URL(`${dir.replace(/\/$/, '')}/${plugin.replace(/\.ts$/, '.js')}`, this.ctx.baseUrl)
      await this.ctx.loader.create({ name: url.href })
      count += 1
    }

    this.ctx.emit('plugin-directory/loaded', dir, count)
    return count
  }

  /**
   * 插件启动钩子：本 fiber 激活后才跑，此时服务已经能从 ctx 上取到。
   *
   * 为什么不在 `apply()` 里直接 `await ctx.pluginDirectory.load()`？
   * 因为 `ctx.plugin(X)` 只是**登记**了服务，要等这个插件的 fiber
   * 真正激活（ACTIVE）之后，`ctx.pluginDirectory` 才取得出来。
   * 在 apply 里伸手，只会拿到
   * `cannot get property "pluginDirectory" without inject`。
   *
   * 这个钩子的调用时机正好：apply 跑完、fiber 就绪。
   */
  async *[Service.init]() {
    yield () => {}
    await this.load(this.#root)
  }

  /** 要加载的目录，由 apply 从配置里写进来。 */
  #root = '.'

  /** 记录要加载的目录。 */
  setRoot(root: string) {
    this.#root = root
  }
}

/**
 * 应用入口：登记服务，把配置里的目录记下来。
 *
 * 真正的加载发生在 `[Service.init]` 钩子里——那时本插件的 fiber 已激活，
 * `ctx.pluginDirectory` 取得出来，而且能安全地往 loader 里添新条目。
 */
export function apply(ctx: Context, config: Config) {
  ctx.plugin(MapPluginDirectory)
  ctx.reflect.get('pluginDirectory', false)?.setRoot(config.root)
}

import type { Context } from '@deepseek-ai/cordis'
import { Tools, type ToolSchema } from './tools.ts'
import type { ToolArgs, ToolDefinition, ToolResult } from './define-tool.ts'

export const name = 'tools-registry'

/**
 * Service Provider：一个基于 Map 的工具注册表。
 *
 * register() 是第 02 课的"注册即效果"：注册方插件一卸载，
 * 这个工具定义自动从表里消失。
 */
class MapTools extends Tools {
  private readonly definitions = new Map<string, ToolDefinition>()
  private counter = 0

  register(definition: ToolDefinition): () => void {
    // ctx.effect 是"本插件卸载时自动执行"的注册点
    return this.ctx.effect(() => {
      this.definitions.set(definition.name, definition)
      // 注册即广播：谁想知道"现在有哪些工具"，挂这个事件就行
      this.ctx.emit('tools/change')
      return () => {
        this.definitions.delete(definition.name)
        this.ctx.emit('tools/change')
      }
    }, `tools.register(${definition.name})`)
  }

  get(name: string): ToolDefinition | undefined {
    return this.definitions.get(name)
  }

  list(): ToolDefinition[] {
    return [...this.definitions.values()]
  }

  schemas(): ToolSchema[] {
    // 只挑三个字段——execute 留在本地，不随请求出门
    return [...this.definitions.values()].map(({ name, description, parameters }) => ({
      name,
      description,
      parameters,
    }))
  }

  async call(name: string, args: unknown): Promise<ToolResult> {
    const definition = this.definitions.get(name)
    const callId = `call-${++this.counter}`
    if (!definition) {
      return { ok: false, callId, name, error: `工具不存在：${name}` }
    }
    try {
      const value = await definition.execute((args ?? {}) as ToolArgs, { callId })
      return { ok: true, callId, name, value }
    } catch (error) {
      return { ok: false, callId, name, error: error instanceof Error ? error.message : String(error) }
    }
  }
}

export function apply(ctx: Context) {
  ctx.plugin(MapTools)
}

import { Service, type Context } from '@deepseek-ai/cordis'
import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

/**
 * 一条会话记录。`data` 的形状由 `type` 决定。
 *
 * harness 真身里这是 `SessionEventMap`（packages/core/session/src/types.ts 第 281 行），
 * 同样是"一个 type 对应一种 data"的表。
 */
export interface SessionRecordMap {
  /** 用户说了一句话。 */
  'user/message': { content: string }
  /** 模型回答了一轮。 */
  'assistant/message': { text: string }
  /** 模型请求调用一个工具，arguments 是它吐出的原始 JSON 字符串。 */
  'tool/call': { callId: string; name: string; arguments: string }
  /** 工具执行完了，value 是返回值，isError 标记成功失败。 */
  'tool/result': { callId: string; name: string; value: unknown; isError: boolean }
}

/** 任意一种会话记录。 */
export type SessionRecord =
  | { [K in keyof SessionRecordMap]: { type: K; data: SessionRecordMap[K] } }[keyof SessionRecordMap]

/**
 * 会产生模型可见消息的记录类型。
 *
 * 日志里还有别的行（turn 边界、失败尝试），它们不进模型请求，
 * 只是排查问题时看的痕迹。harness 真身叫 `SurfaceEventType`
 * （packages/core/session/src/types.ts 第 439 行）。
 */
export type SurfaceRecordType = 'user/message' | 'assistant/message' | 'tool/result'

/** 一条记录在"模型能看到的历史"里的落点。 */
export type SurfaceOp =
  /** 追加到末尾：正常路径。 */
  | 'append'
  /** 替换一段已有节点：压缩上下文时用，被替换的行在日志里还在，只是不再进模型请求。 */
  | { op: 'replace'; startSeq: number; endSeq: number }

/**
 * 落盘的一行。
 *
 * 这是判别联合：`switch (line.type)` 会收窄 `line.data` 的类型，
 * 不用写任何断言。写法照抄 harness 真身的 `SessionEvent`
 * （packages/core/session/src/types.ts 第 493 行）——
 * `{ [K in ...]: {...} }[T]` 这层映射就是为了让联合生效。
 */
export type SessionLine = {
  [K in keyof SessionRecordMap]: {
    /** 会话内单调递增的序号，从 1 开始。 */
    readonly seq: number
    /** 写入时刻，Unix 毫秒。 */
    readonly time: number
    readonly type: K
    readonly data: SessionRecordMap[K]
    /** 它怎么进入模型可见历史。只有会产生消息的行带这个字段。 */
    readonly surfaceOp?: K extends SurfaceRecordType ? SurfaceOp : never
  }
}[keyof SessionRecordMap]

declare module '@deepseek-ai/cordis' {
  interface Context { session: Session }
}

/** 一条喂给模型的请求消息。 */
export interface ChatMessage {
  readonly role: 'user' | 'assistant' | 'tool'
  readonly content: string
}

/**
 * Service Definition：把"发生过的事"写进一条只增不减的日志。
 *
 * 这是 harness 的**唯一事实来源**。第 12 课的 agent loop 只在内存里跑，
 * 进程一退全忘了；有了它，任何时候都能把对话重放出来。
 */
export abstract class Session extends Service {
  constructor(ctx: Context) { super(ctx, 'session') }

  /**
   * 追加一条记录。
   * @param record - 记录内容。
   * @param op - 它怎么进入模型可见历史，默认 `'append'`。
   * @returns 分配到的序号。
   */
  abstract append(record: SessionRecord, op?: SurfaceOp): number

  /** 目前为止的全部记录，按 seq 升序。 */
  abstract list(): readonly SessionLine[]

  /**
   * 把日志折叠成模型能看的历史。
   *
   * 只走会产生消息的行；`replace` 标记的行会顶掉它覆盖的那一段。
   * 这就是 harness 的 `deriveMessages()`——每次请求前都重新折一遍，
   * 所以日志和模型看到的东西永远一致。
   */
  abstract deriveMessages(): ChatMessage[]

  /** 磁盘上已经有多少条记录——恢复来的，还是新起的。 */
  abstract readonly restoredCount: number

  /**
   * 从磁盘读回一个 session 的全部记录。
   *
   * 第一行是头行（`type: 'session'`），记录格式版本；剩下的是记录行。
   * 版本对不上直接抛错——**拒绝加载比猜着加载安全**。
   * @param file - session.jsonl 的路径。
   * @returns 按 seq 升序的记录。
   */
  static load(file: string): readonly SessionLine[] {
    const text = readFileSync(file, 'utf8')
    const lines = text.split('\n')
      .filter((line) => line.length > 0)
      .map((line) => JSON.parse(line) as SessionFileLine)
    const [header, ...rest] = lines
    if (header.type !== 'session') {
      throw new Error(`session 文件第一行必须是头行，实际是 ${String(header.type)}`)
    }
    if (header.version !== SESSION_FORMAT_VERSION) {
      throw new Error(
        `session 格式版本不匹配：文件是 v${header.version}，本程序只会 v${SESSION_FORMAT_VERSION}`,
      )
    }
    // 剩下的都是记录行；头行在上面已经核对掉了
    return rest.filter(isSessionLine)
  }
}

/** 头行不是记录。 */
function isSessionLine(line: SessionFileLine): line is SessionLine {
  return line.type !== 'session'
}

/**
 * 落盘文件的一行：要么是头行，要么是一条记录。
 *
 * 头行不是记录——它没有 `seq`，只说明"这个文件是什么格式的"。
 * harness 真身在 packages/session/session-persistence-jsonl/src/format.ts
 * 里也叫 `HeaderLine`，`type` 字段值是 `'session'`。
 */
export type SessionFileLine =
  | { type: 'session'; version: number }
  | SessionLine

/** 当前会话日志的格式版本。harness 真身是 `SESSION_FORMAT_VERSION = 4`。 */
export const SESSION_FORMAT_VERSION = 1

/**
 * Service Provider：JSONL 落地。
 *
 * 每行一条 JSON，追加写文件。harness 真身（packages/session/session-persistence-jsonl）
 * 用 zstd 压缩、分代文件名和原子替换，我们保留最核心的那个决定：
 * **append-only，写出去的行永不改写**。
 */
export class JsonlSession extends Session {
  private seq = 0
  private readonly records: SessionLine[] = []
  private readonly file: string
  /** 磁盘上已有多少条记录——恢复来的，还是新起的。 */
  readonly restoredCount: number

  constructor(ctx: Context, config: { file: string }) {
    super(ctx)
    this.file = join(config.file, 'session.jsonl')
    mkdirSync(dirname(this.file), { recursive: true })

    // 恢复：接着磁盘上已有的行往下写，seq 继续往上加
    if (existsSync(this.file)) {
      const existing = Session.load(this.file)
      this.records.push(...existing)
      this.seq = existing.at(-1)?.seq ?? 0
      this.restoredCount = existing.length
    } else {
      this.restoredCount = 0
      // 新文件第一行写头行：以后谁来读这个文件，先核对版本
      appendFileSync(this.file, `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`)
    }
  }

  append(record: SessionRecord, op: SurfaceOp = 'append'): number {
    this.seq += 1
    const line = this.toLine(this.seq, record, op)
    this.records.push(line)
    // 追加写：只往文件末尾加字节，不动已有内容
    appendFileSync(this.file, `${JSON.stringify(line)}\n`)
    return line.seq
  }

  /** 拼一行。`tool/call` 不进模型可见历史——它已经被同一轮的 assistant/message 代表了。 */
  private toLine(seq: number, record: SessionRecord, op: SurfaceOp): SessionLine {
    const time = Date.now()
    switch (record.type) {
      case 'user/message':
        return { seq, time, type: 'user/message', data: record.data, surfaceOp: op }
      case 'assistant/message':
        return { seq, time, type: 'assistant/message', data: record.data, surfaceOp: op }
      case 'tool/result':
        return { seq, time, type: 'tool/result', data: record.data, surfaceOp: op }
      case 'tool/call':
        return { seq, time, type: 'tool/call', data: record.data }
    }
  }

  list(): readonly SessionLine[] { return this.records }

  /**
   * 折叠日志。
   *
   * `surface` 是一个"模型能看到哪些 seq"的有序列表。
   * 追加就 push；替换就把 [startSeq, endSeq] 那段挖掉、换成新行。
   * 被挖掉的行在日志里一行不少，只是不再进模型请求。
   */
  deriveMessages(): ChatMessage[] {
    const surface: SessionLine[] = []
    for (const line of this.records) {
      const op = line.surfaceOp
      if (op === undefined) continue          // 非消息行：跳过
      if (op === 'append') { surface.push(line); continue }
      // replace：挖掉旧段，在原来的位置插入新行
      const start = surface.findIndex((node) => node.seq === op.startSeq)
      const end = surface.findIndex((node) => node.seq === op.endSeq)
      if (start === -1 || end === -1) continue
      surface.splice(start, end - start + 1, line)
    }
    return surface.map(toChatMessage)
  }

  /**
   * 把整个文件重写一遍。
   *
   * 注意头行得带上——它是文件的一部分，不是记录。
   * 这是本文件里唯一一处"整份重写"的路径，正常写入走的是 append。
   */
  flush(): void {
    const header = `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`
    const body = this.records.map((line) => `${JSON.stringify(line)}\n`).join('')
    writeFileSync(this.file, header + body)
  }
}

/** 把一条消息行翻译成模型请求里的消息。 */
function toChatMessage(line: SessionLine): ChatMessage {
  switch (line.type) {
    case 'user/message':
      return { role: 'user', content: line.data.content }
    case 'assistant/message':
      return { role: 'assistant', content: line.data.text }
    case 'tool/result':
      return { role: 'tool', content: String(line.data.value) }
    case 'tool/call':
      // 走不到这里：tool/call 没有 surfaceOp，deriveMessages 已经把它过滤掉了
      return { role: 'assistant', content: `${line.data.name}(${line.data.arguments})` }
  }
}

export function apply(ctx: Context) {
  ctx.plugin(JsonlSession, { file: '.sessions/demo' })
}

import { Service, type Context } from '@deepseek-ai/cordis'
import type { ToolDefinition, ToolParameters, ToolResult } from './define-tool.ts'

declare module '@deepseek-ai/cordis' {
  interface Context {
    tools: Tools
  }
  interface Events {
    /**
     * 有工具注册进来或摘出去。
     *
     * harness 真身（packages/core/tools/src/index.ts 第 208 行）也叫
     * `tools/change`。为什么需要它？因为插件的加载顺序由依赖拓扑决定，
     * **不写插件的人控制不了谁先谁后**。想知道"现在有哪些工具"，
     * 只能等注册表通知，不能在启动时假设它已经满了。
     * @mode emit
     */
    'tools/change'(): void
  }
}

/**
 * Service Definition：工具注册表。
 *
 * 它只知道"工具长什么样、怎么被调用"，不知道任何一个工具的具体实现。
 */
export abstract class Tools extends Service {
  constructor(ctx: Context) {
    super(ctx, 'tools')
  }

  /** 注册一个工具定义，返回的摘除函数随注册方插件的卸载自动执行。 */
  abstract register(definition: ToolDefinition): () => void

  /** 按名字取定义，没有则 undefined。 */
  abstract get(name: string): ToolDefinition | undefined

  /** 当前全部定义，按注册顺序排列。 */
  abstract list(): ToolDefinition[]

  /**
   * 递给模型看的工具清单。
   *
   * 只保留 name / description / parameters 三个字段——
   * `execute` 是本地代码，发给模型没有意义，还可能泄露实现细节。
   * harness 真身 [packages/core/tools/src/index.ts 第 1260 行](../../../deepseek-harness/packages/core/tools/src/index.ts#L1260)
   * 的 `schemas()` 干的就是这件事，注释里那词叫 allowlist（白名单）。
   */
  abstract schemas(): ToolSchema[]

  /** 执行一个工具；任何失败都收进 ToolResult，不往外抛。 */
  abstract call(name: string, args: unknown): Promise<ToolResult>
}

/** 递给模型看的工具描述：三个字段，缺一不可。 */
export interface ToolSchema {
  readonly name: string
  readonly description: string
  readonly parameters: ToolParameters
}

import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from './define-tool.ts'

export const name = 'weather-tool'

// 忘了这行，ctx.tools 会抛 "cannot get property "tools" without inject"
// （第 03 课的规矩：要拿 ctx 上的服务，必须先声明 inject）
export const inject = ['tools']

/**
 * Service Provider 的角色之一：往 ctx.tools 里放一个工具。
 *
 * 真身（packages/web/tool-web/src/search.ts）长这样：
 *   ctx.tools.register(defineTool({ name: 'web_search', ... }))
 * 我们连形状都照抄，只是把网络请求换成了假数据。
 */
export function apply(ctx: Context) {
  ctx.tools.register(defineTool({
    name: 'get_weather',
    description: '查询一个城市的天气。需要城市名。',
    parameters: {
      city: {
        type: 'string',
        required: true,
        description: '城市名，例如 "北京"',
      },
      unit: {
        type: 'string',
        enum: ['celsius', 'fahrenheit'],
        description: '温度单位，默认摄氏度。',
      },
    },
    async execute(args) {
      const city = String(args.city ?? '')
      // Keyless：假数据，不联网
      const table: Record<string, string> = {
        北京: '晴，12°C',
        上海: '小雨，18°C',
      }
      const forecast = table[city] ?? '晴，20°C（默认值）'
      const unit = args.unit === 'fahrenheit' ? '（已换算为华氏）' : ''
      return `${city}：${forecast}${unit}`
    },
  }))
}

import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from './define-tool.ts'

export const name = 'calc-tool'

export const inject = ['tools']

/**
 * 第二个工具插件。
 *
 * 它和 weather.ts 长得一模一样，唯一的差别是干的事不同。
 * 这就是"注册表"的全部意义：**加工具不用碰 loop 一行代码**，
 * 只要新写一个插件、在 cordis.yml 里加一行。
 */
export function apply(ctx: Context) {
  ctx.tools.register(defineTool({
    name: 'calc',
    description: '算一道四则运算。支持加减乘除。',
    parameters: {
      a: { type: 'number', required: true, description: '左操作数' },
      b: { type: 'number', required: true, description: '右操作数' },
      op: { type: 'string', enum: ['+', '-', '*', '/'], description: '运算符' },
    },
    execute(args) {
      const a = Number(args.a)
      const b = Number(args.b)
      switch (args.op) {
        case '+': return `${a} + ${b} = ${a + b}`
        case '-': return `${a} - ${b} = ${a - b}`
        case '*': return `${a} * ${b} = ${a * b}`
        case '/': return `${a} / ${b} = ${b === 0 ? '除数不能为 0' : a / b}`
        default:
          return `不支持的运算符：${String(args.op)}`
      }
    },
  }))
}

/**
 * 简化版 defineTool。
 *
 * harness 真身（packages/core/tools/src/schema.ts 第 554 行）在这里做三件事：
 * 1. 把手写的 JSON Schema DSL 编译成标准 JSON Schema，并用它校验模型传来的参数；
 * 2. 从 DSL 反推出 TypeScript 类型，让 execute 里的 args 有补全；
 * 3. 把校验包在 execute 外层，任何违规都以 ToolArgsError 的形式抛出。
 *
 * 第 10 课只做了"组装"。本课补上第 1 和第 3 件事——**校验**。
 */

import { compileNode, ToolArgsError, validateValue, type JsonSchemaNode, type SchemaSpec } from './json-schema.ts'

/** 模型传来的参数：一个 JSON 对象。 */
export type ToolArgs = Record<string, unknown>

/** 参数 schema：一棵 JSON Schema 树。 */
export type ToolParameters = Record<string, unknown>

/** 执行上下文：harness 真身叫 ToolRunContext，这里只保留两个字段。 */
export interface ToolRunContext {
  /** 本次调用的 id，由注册表分配。 */
  readonly callId: string
  /** 取消信号：调用方 abort 时，工具应当尽快收手。 */
  readonly signal?: AbortSignal
}

/** 一次工具调用的结果。成功失败都走这个壳，不抛异常。 */
export type ToolResult =
  | { ok: true; callId: string; name: string; value: unknown }
  | { ok: false; callId: string; name: string; error: string }

/** 一个工具的完整定义。 */
export interface ToolDefinition {
  readonly name: string
  /** 写给模型看的说明，模型据此决定要不要调用它。 */
  readonly description: string
  /** 编译后的参数 schema，既校验也进模型请求。 */
  readonly parameters: ToolParameters
  /** 具体干活的部分。参数已通过校验。 */
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}
export interface DefineToolOptions {
  name: string
  description: string
  /** 手写的参数 schema（第 11 课细讲）。 */
  parameters?: Record<string, SchemaSpec>
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}

/**
 * 定义工具。
 * @param options - 工具的名称、说明、参数 schema 和执行体。
 * @returns 一个 registry-ready 的定义，execute 已自带参数校验。
 */
export function defineTool(options: DefineToolOptions): ToolDefinition {
  const compiled = compileParameters(options.parameters)

  return {
    name: options.name,
    description: options.description,
    parameters: compiled,
    async execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> {
      // 校验发生在用户的 execute 之前：不合规的参数根本到不了业务代码
      const violations = validateValue(compiled, args)
      if (violations.length > 0) {
        throw new ToolArgsError(options.name, violations)
      }
      return options.execute(args, exec)
    },
  }
}

/** 把"每个参数一条声明"的手写 DSL 编译成一个对象根的 JSON Schema。 */
function compileParameters(spec: Record<string, SchemaSpec> | undefined): JsonSchemaNode {
  if (spec === undefined) return { type: 'object', additionalProperties: true }
  const node = compileNode({ type: 'object', properties: spec })
  // 顶层参数对象是"开放"的：模型可以额外带字段，不像 output schema 那样严苛
  node.additionalProperties = true
  return node
}

/**
 * 简化版 JSON Schema 校验器。
 *
 * harness 真身在 packages/core/tools/src/json-schema.ts，它只接受一个
 * 受限的 JSON Schema 子集：一个标量 type、对象 properties/required、
 * 布尔 additionalProperties、数组 items、标量 enum/const。任何子集之外的
 * 关键字直接拒绝，而不是"接受但不校验"——因为那会给作者一种虚假的安全感。
 *
 * 本课实现同款子集的教学版。
 */

/** 校验错误：模型传来的参数不符合声明。 */
export class ToolArgsError extends Error {
  constructor(
    readonly toolName: string,
    readonly violations: string[],
  ) {
    super(`invalid arguments: ${violations.join('; ')}`)
    this.name = 'ToolArgsError'
  }
}

/** 手写 DSL 里的一个节点。 */
export type SchemaSpec =
  | { type: 'string'; required?: true; description?: string; enum?: readonly string[] }
  | { type: 'number'; required?: true; description?: string }
  | { type: 'boolean'; required?: true; description?: string }
  | { type: 'array'; required?: true; description?: string; items?: SchemaSpec }
  | { type: 'object'; required?: true; description?: string; additionalProperties?: boolean; properties?: Record<string, SchemaSpec> }

/** 编译后的 JSON Schema 节点（只保留校验需要的字段）。 */
export interface JsonSchemaNode {
  type: string
  description?: string
  enum?: readonly (string | number | boolean | null)[]
  required?: string[]
  additionalProperties?: boolean
  items?: JsonSchemaNode
  properties?: Record<string, JsonSchemaNode>
  /** 允许作为普通 JSON 对象在工具之间传递。 */
  [key: string]: unknown
}

/**
 * 把手写 DSL 的一个节点编译成 JSON Schema。
 * @param spec - 手写 DSL 节点。
 * @returns 编译后的 JSON Schema 节点。
 */
export function compileNode(spec: SchemaSpec): JsonSchemaNode {
  const node: JsonSchemaNode = { type: spec.type }
  if (spec.description !== undefined) node.description = spec.description
  if ('enum' in spec && spec.enum !== undefined) node.enum = spec.enum
  if (spec.type === 'array' && spec.items !== undefined) {
    node.items = compileNode(spec.items)
  }
  if (spec.type === 'object') {
    node.additionalProperties = spec.additionalProperties ?? false
    if (spec.properties !== undefined) {
      node.properties = {}
      node.required = []
      for (const [key, child] of Object.entries(spec.properties)) {
        node.properties[key] = compileNode(child)
        if (child.required === true) node.required.push(key)
      }
      if (node.required.length === 0) delete node.required
    }
  }
  return node
}

/**
 * 校验一个值是否符合编译后的 schema。
 * @param schema - 编译后的 schema。
 * @param value - 待校验的值，任意来源。
 * @param path - 当前路径，用于错误信息定位。
 * @returns 违规列表；空数组表示通过。
 */
export function validateValue(schema: JsonSchemaNode, value: unknown, path = '$'): string[] {
  const violations: string[] = []
  const at = (suffix: string) => suffix === '' ? path : `${path}.${suffix}`

  switch (schema.type) {
    case 'string':
      if (typeof value !== 'string') {
        violations.push(`${at('')} 必须是字符串，收到 ${describe(value)}`)
        break
      }
      if (schema.enum !== undefined && !schema.enum.includes(value)) {
        violations.push(`${at('')} 必须是 ${schema.enum.map((entry) => JSON.stringify(entry)).join(' / ')} 之一`)
      }
      break

    case 'number':
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        violations.push(`${at('')} 必须是数字，收到 ${describe(value)}`)
      }
      break

    case 'boolean':
      if (typeof value !== 'boolean') {
        violations.push(`${at('')} 必须是布尔值，收到 ${describe(value)}`)
      }
      break

    case 'array': {
      if (!Array.isArray(value)) {
        violations.push(`${at('')} 必须是数组，收到 ${describe(value)}`)
        break
      }
      if (schema.items === undefined) break
      value.forEach((entry, index) => {
        violations.push(...validateValue(schema.items!, entry, `${path}[${index}]`))
      })
      break
    }

    case 'object': {
      if (typeof value !== 'object' || value === null || Array.isArray(value)) {
        violations.push(`${at('')} 必须是对象，收到 ${describe(value)}`)
        break
      }
      const record = value as Record<string, unknown>
      for (const key of schema.required ?? []) {
        if (record[key] === undefined) {
          violations.push(`${at(key)} 是必填项，但没有提供`)
        }
      }
      for (const [key, child] of Object.entries(schema.properties ?? {})) {
        if (record[key] === undefined) continue
        violations.push(...validateValue(child, record[key], at(key)))
      }
      if (schema.additionalProperties === false) {
        for (const key of Object.keys(record)) {
          if (schema.properties === undefined || !(key in schema.properties)) {
            violations.push(`${at(key)} 不是声明过的字段（additionalProperties: false）`)
          }
        }
      }
      break
    }

    default:
      throw new Error(`不支持的 schema 类型：${schema.type}`)
  }

  return violations
}

/** 把一个未知值描述成一句人能看懂的话，用于错误信息。 */
function describe(value: unknown): string {
  if (value === null) return 'null'
  if (Array.isArray(value)) return '数组'
  if (typeof value === 'object') return '对象'
  return JSON.stringify(value) ?? String(value)
}

import { Service, type Context } from '@deepseek-ai/cordis'

declare module '@deepseek-ai/cordis' {
  interface Context { llm: Llm }
  interface Events {
    /** 消费方向 llm 服务发出一次请求，由提供方处理。 */
    'llm/generate'(input: string): void
  }
}

export type StreamChunk =
  | { type: 'block-start'; index: number; blockType: 'text' | 'tool-call' }
  | { type: 'text-delta'; index: number; text: string }
  | { type: 'reasoning-delta'; index: number; text: string }
  | { type: 'tool-call-delta'; index: number; id: string; name?: string; argumentsDelta: string }
  | { type: 'block-end'; index: number; block: ContentBlock }
  | { type: 'usage'; usage: { inputTokens: number; outputTokens: number } }
  | { type: 'finish'; reason: { kind: 'stop' | 'tool-calls' | 'max-tokens' | 'error' } }

export type ContentBlock =
  | { type: 'text'; text: string }
  | { type: 'tool-call'; id: string; name: string; arguments: string }

export interface GenerateOptions {
  messages: { role: 'system' | 'user' | 'assistant' | 'tool'; content: string }[]
  maxTokens?: number
  signal?: AbortSignal
}

export abstract class Llm extends Service {
  constructor(ctx: Context) { super(ctx, 'llm') }
  abstract stream(options: GenerateOptions): AsyncIterable<StreamChunk>
}

import type { Context } from '@deepseek-ai/cordis'
import type { GenerateOptions } from './llm.ts'
import type { SessionLine } from './session.ts'

declare module '@deepseek-ai/cordis' {
  interface Events {
    /** 用户说了一句话，agent 处理一轮。 */
    'agent/turn'(input: string): void
    /** 把前面的轮次折叠成一条摘要。 */
    'agent/compact'(fromSeq: number, toSeq: number, summary: string): void
  }
}

export const name = 'agent'
export const inject = ['llm', 'tools', 'session']

/** 一轮对话里模型给出的指令：要么说话，要么调工具。 */
type ModelTurn =
  | { kind: 'text'; text: string }
  | { kind: 'tool-call'; id: string; name: string; args: Record<string, unknown> }

/**
 * Consumer：agent loop 的第五版。
 *
 * 前三版跑完就忘（或者只记得自己那次）。第四版补上**能力协商**：
 * 这个插件声明了自己要 `llm`、`tools`、`session` 三项能力，cordis 就
 * 替我们盯着它们。齐了才启动，缺了就 FAILED——而不是等第一次用的
 * 时候才炸。
 *
 * 本版（第五版）的主题是**流式**：不再等模型把整句话说完，
 * 每收到一片 text-delta 就立刻打到屏幕上。协议一个字没改，
 * 改的是"什么时候用"。
 */
export function apply(ctx: Context) {
  ctx.on('agent/turn', (input) => { void run(input) })
  ctx.on('agent/compact', (fromSeq, toSeq, summary) => { compact(fromSeq, toSeq, summary) })

  // 启动第一件事：报告从磁盘恢复了什么
  const restored = ctx.session.restoredCount
  if (restored > 0) {
    console.log(`=== 从磁盘恢复了 ${restored} 条记录，seq 接着 #${ctx.session.list().at(-1)?.seq ?? 0} 往下编 ===`)
    console.log('=== 模型看到的历史 ===')
    for (const message of ctx.session.deriveMessages()) {
      console.log(`[${message.role}] ${message.content}`)
    }
  } else {
    console.log('=== 没有找到历史，开一个新会话 ===')
  }

  /**
   * 三轮对话，串行不并行。
   *
   * 上一课这里是三个 setTimeout，间隔 50ms——因为那一轮的
   * 模型是"瞬间吐完"的，50ms 足够跑完一整轮。
   * 本课不行了：**一轮现在要花几百毫秒**（几十片 × 60ms），
   * 50ms 后第二轮就会插进来，屏幕上三行字互相穿插，
   * 日志的 seq 也会因为两个 run 同时 append 而错乱。
   *
   * 所以改成 await 一个、再 await 下一个。
   * 这不是"流式特有的麻烦"，而是**任何异步流水线的通用纪律**：
   * 只要一步变慢了，原本靠"猜时间"排的队就会撞车。
   * 真正的排队方式是等前一个真的做完。
   */
  void (async () => {
    if (restored > 0) {
      await run('刚才我问了什么？')
    } else {
      await run('北京天气怎么样？')
      await run('帮我算 7*6')
      await run('你好')
      // 三轮聊完，把 #1~#10 折成一条摘要。
      // endSeq 必须是**摘要之前最后一条记录**（#10）：摘要自己落在 #11，
      // 它还没进日志，写 11 会让"找终点"的那一步落空，压缩被静默跳过。
      compact(1, 10, '（摘要）用户问了北京天气和一道乘法，模型分别调了 get_weather 和 calc。')
    }
    reportCapabilities()
    replay()
  })()

  /**
   * 工具清单：等注册表通知，不自己猜时机。
   *
   * 为什么不能在 apply 函数体里直接 `ctx.tools.schemas()`？因为 cordis 按
   * **依赖拓扑**排插件的加载顺序：agent 声明了 `inject: ['llm','tools','session']`，
   * 它要的三个服务必须先把 provider 建好，所以 agent 的 apply 排在 provider
   * 之后、**但排在 weather-tool / calc-tool 之前**——后两者只 inject 了
   * `tools`，拓扑上没人催它们，就按 cordis.yml 的顺序落到最后。
   *
   * 也就是说：apply 函数体执行的那一刻，注册表**恰好是空的**。
   * 而这个顺序由依赖关系决定，写 yml 的人控制不了。
   * 所以"现在有哪些工具"这件事，只能等注册表通知，不能自己数。
   *
   * 那为什么还要 `setTimeout` 包一层？因为插件是一个个加载的，
   * weather-tool 注册时会响一次，calc-tool 注册时又响一次。
   * 每次响都打印，就会打出两份不完整的清单。
   * 所以：**每次变化只重新排一次打印，等本轮事件循环安静下来再打**。
   */
  let scheduled = false
  ctx.on('tools/change', () => {
    if (scheduled) return
    scheduled = true
    setTimeout(printTools, 0)
  })

  function printTools() {
    console.log('=== 模型能选的工具 ===')
    for (const schema of ctx.tools.schemas()) {
      console.log(`- ${schema.name}：${schema.description}`)
    }
  }

  /**
   * 对账：我声明要的能力，注册表现在真的都有了吗？
   *
   * 这就是本课的主题。`ctx.fiber.inject` 是本插件声明的那张需求表，
   * `ctx.reflect.props` 是全应用登记过的服务名册。
   * 两边一减，缺谁一目了然——而且是在**启动阶段**减，不是等
   * 某次调用踩空了才炸。
   *
   * 注意它读的是 `props`（登记册），不是 `store`（实例）。
   * 登记册里有名字，不代表现在有实例——第 19 课的工具就是
   * 先登记、后注册的。缺名字才是真缺。
   */
  function reportCapabilities() {
    console.log('\n=== 能力对账 ===')
    for (const service of Object.keys(ctx.fiber.inject)) {
      const registered = Object.hasOwn(ctx.reflect.props, service)
      const status = registered ? '齐' : '缺'
      console.log(`- ${service}：${status}`)
      if (!registered) {
        console.log(`  没人提供 ${service}——cordis.yml 里少了一个 provider，或者它自己加载失败了`)
      }
    }
  }

  async function run(input: string) {
    console.log(`\n=== 用户说：${input} ===`)
    ctx.session.append({ type: 'user/message', data: { content: input } })

    // 关键一行：messages 不是手搓的，是从日志折出来的
    const options: GenerateOptions = { messages: ctx.session.deriveMessages() }
    const turn = await stream(ctx, options)

    switch (turn.kind) {
      case 'text':
        // 正文连标签一起在 stream() 里打完了，这里只写日志。
        // 上一课是 `console.log('[模型回答] ' + turn.text)` 整句一次打完；
        // 流式之后**不能再打一遍正文**——用户会看到同一个句子出现两次。
        ctx.session.append({ type: 'assistant/message', data: { text: turn.text } })
        break

      case 'tool-call': {
        console.log(`[模型决定] 调用 ${turn.name}，参数 ${JSON.stringify(turn.args)}`)
        // 注意：arguments 存的是模型吐出的**原始字符串**，不是我们 parse 后的对象
        ctx.session.append({
          type: 'tool/call',
          data: { callId: turn.id, name: turn.name, arguments: JSON.stringify(turn.args) },
        })
        await executeTool(turn)
        break
      }
    }
  }

  async function executeTool(call: Extract<ModelTurn, { kind: 'tool-call' }>) {
    const result = await ctx.tools.call(call.name, call.args)
    if (result.ok) {
      console.log(`[工具返回] ${String(result.value)}`)
      ctx.session.append({
        type: 'tool/result',
        data: { callId: call.id, name: call.name, value: result.value, isError: false },
      })

      // 工具结果有了，再问模型一次，让它说人话——这次它看得见刚才的调用和返回
      const follow = await stream(ctx, { messages: ctx.session.deriveMessages() })
      if (follow.kind === 'text') {
        ctx.session.append({ type: 'assistant/message', data: { text: follow.text } })
      }
    } else {
      console.log(`[工具失败] ${result.error}`)
      ctx.session.append({
        type: 'tool/result',
        data: { callId: call.id, name: call.name, value: result.error, isError: true },
      })
    }
  }

  /**
   * 压缩：往日志里**追加**一条摘要，标记它顶掉 [fromSeq, toSeq]。
   *
   * 注意是追加，不是删除。旧的行一条不少地还在文件里，
   * 只是从此不进模型请求——这就是 harness 的 compaction 路子。
   */
  function compact(fromSeq: number, toSeq: number, summary: string) {
    console.log(`\n=== 压缩：#${fromSeq}~#${toSeq} 折成一条摘要 ===`)
    const seq = ctx.session.append(
      { type: 'assistant/message', data: { text: summary } },
      { op: 'replace', startSeq: fromSeq, endSeq: toSeq },
    )
    console.log(`摘要落成 #${seq}，它顶掉了 #${fromSeq}~#${toSeq}`)
  }

  /** 重放：日志是唯一事实来源，屏幕上的字早没了，日志还在。 */
  function replay() {
    const lines = ctx.session.list()
    console.log(`\n=== 日志全量（${lines.length} 条）===`)
    for (const line of lines) {
      console.log(`#${line.seq} [${line.type}] ${describe(line)}${opNote(line)}`)
    }

    const messages = ctx.session.deriveMessages()
    console.log(`\n=== 模型看到的历史（折叠后 ${messages.length} 条）===`)
    for (const message of messages) {
      console.log(`[${message.role}] ${message.content}`)
    }
  }

  /** 压缩标记只在日志里可见，模型那一侧看不到。 */
  function opNote(line: SessionLine): string {
    const op = line.surfaceOp
    if (op === undefined || op === 'append') return ''
    return `　← replace #${op.startSeq}~#${op.endSeq}`
  }

  function describe(line: SessionLine): string {
    switch (line.type) {
      case 'user/message':
        return line.data.content
      case 'assistant/message':
        return line.data.text
      case 'tool/call':
        return `${line.data.name}(${line.data.arguments})`
      case 'tool/result':
        return line.data.isError ? `失败：${String(line.data.value)}` : String(line.data.value)
    }
  }
}

/**
 * 流式消费：每收到一片就打印，同时把碎片拼回整块。
 *
 * 和第 09 课的 `for await` 打印相比，这里多了一件事：
 * **打印和拼装同时进行。** 用户看到字一个个蹦出来（体验），
 * 日志拿到的是拼好的完整块（正确性）——两者不冲突，
 * 因为 text-delta 的拼接就是字符串相加，来一片加一片。
 *
 * 注意 `process.stdout.write` 而不是 `console.log`：
 * log 每次调用都自带换行，会把一行字拆成很多行。
 * 流式的要点就是**不换行**，直到块结束。
 *
 * `[模型回答]` 这个标签也在本函数里打，而且只在第一片正文到来时
 * 打一次。标签是"事前"的：它得和正文出现在同一行，事后再补
 * 就只能另起一行贴在后面，读起来像是另一个句子。
 */
async function stream(ctx: Context, options: GenerateOptions): Promise<ModelTurn> {
  // index → 已拼接的文本/参数
  const texts = new Map<number, string>()
  const calls = new Map<number, { id: string; name: string; arguments: string }>()
  // 这一轮有没有往屏幕上写过正文？工具调用那一轮一个字都不写，
  // 结尾就不能补换行——否则会多出一个空行。
  // reasoning-delta 不算正文：它没有标签，也不参与换行判断。
  let wroteText = false

  for await (const chunk of ctx.llm.stream(options)) {
    switch (chunk.type) {
      case 'text-delta':
        texts.set(chunk.index, (texts.get(chunk.index) ?? '') + chunk.text)
        // 第一片正文先亮标签，正文跟在它后面一个字一个字蹦出来
        if (!wroteText) {
          process.stdout.write('[模型回答] ')
          wroteText = true
        }
        process.stdout.write(chunk.text)
        break
      case 'reasoning-delta':
        // 思考过程：本课的假模型不产出它，但真模型会。
        // 打印出来让"流式"这件事更明显——它是先于正文出现的。
        process.stdout.write(chunk.text)
        break
      case 'tool-call-delta': {
        const existing = calls.get(chunk.index) ?? { id: chunk.id, name: '', arguments: '' }
        // name 可能只在第一条 delta 上出现
        if (chunk.name !== undefined) existing.name = chunk.name
        existing.arguments += chunk.argumentsDelta
        calls.set(chunk.index, existing)
        break
      }
      case 'block-end':
        if (chunk.block.type === 'tool-call') {
          // 工具参数拼完了，这里就是"模型说完话了"的时刻
          process.stdout.write('\n')
          return { kind: 'tool-call', id: chunk.block.id, name: chunk.block.name, args: parseArgs(chunk.block.arguments) }
        }
        break
      case 'usage':
        break
      case 'finish':
        break
      default:
        break
    }
  }

  const text = [...texts.entries()].sort(([a], [b]) => a - b).map(([, value]) => value).join('')
  // 正文逐字打完，补一个换行，让后面的 === 用户说 === 从新行开始
  if (wroteText) process.stdout.write('\n')
  return { kind: 'text', text }
}

/**
 * 上一课的 `collect(stream)` 长这样：
 *
 * ```ts
 * async function collect(stream: AsyncIterable<StreamChunk>): Promise<ModelTurn> {
 *   for await (const chunk of stream) { texts.set(chunk.index, ...) }
 *   return { kind: 'text', text: ... }
 * }
 * ```
 *
 * 它和上面这个函数的唯一区别：收完所有 chunk 才返回，
 * 所以手里没有任何东西可打——只能等整句话到齐再显示。
 * 流式和非流式的分界线**不在协议，在消费时机**：
 * 协议两边一模一样（都是 StreamChunk），差别只在
 * "我是在 yield 的那一刻用它，还是在流结束之后用它"。
 */

/** 解析工具参数；解析失败时返回空对象——校验层会给出准确报错。 */
function parseArgs(json: string): Record<string, unknown> {
  try {
    const parsed: unknown = JSON.parse(json)
    return typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)
      ? parsed as Record<string, unknown>
      : {}
  } catch {
    return {}
  }
}

import type { Context } from '@deepseek-ai/cordis'
import { Llm, type GenerateOptions, type StreamChunk } from './llm.ts'

export function textResponse(text: string): StreamChunk[] {
  return [
    { type: 'block-start', index: 0, blockType: 'text' },
    ...Array.from(text, (char): StreamChunk => ({ type: 'text-delta', index: 0, text: char })),
    { type: 'block-end', index: 0, block: { type: 'text', text } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: text.length } },
    { type: 'finish', reason: { kind: 'stop' } },
  ]
}

export function toolCallResponse(id: string, name: string, args: object): StreamChunk[] {
  const argumentsJson = JSON.stringify(args)
  return [
    { type: 'block-start', index: 0, blockType: 'tool-call' },
    { type: 'tool-call-delta', index: 0, id, name, argumentsDelta: argumentsJson.slice(0, 5) },
    { type: 'tool-call-delta', index: 0, id, argumentsDelta: argumentsJson.slice(5) },
    { type: 'block-end', index: 0, block: { type: 'tool-call', id, name, arguments: argumentsJson } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: 5 } },
    { type: 'finish', reason: { kind: 'tool-calls' } },
  ]
}

/**
 * 每片之间的间隔，毫秒。
 *
 * 不设成 0 的原因：生成器的 `yield` 之间如果没有 await，
 * 整个流会在**同一个 tick 里全部吐完**，消费方的 `for await`
 * 一次都等不到——那就不叫流式，叫批量。
 * 一个 `await sleep(0)` 就足以把控制权交回事件循环，
 * 但那样眼睛看不出来。这里故意放慢，让你在终端里看见字一个个来。
 */
const CHUNK_DELAY_MS = 60

/** 让出事件循环，等 `ms` 毫秒。 */
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => { setTimeout(resolve, ms) })
}

export const name = 'llm-mock'

export class MockAdapter extends Llm {
  private cursor = 0

  constructor(
    ctx: Context,
    private script: (StreamChunk[] | ((options: GenerateOptions) => StreamChunk[]))[],
  ) {
    super(ctx)
  }

  async *stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const entry = this.script[this.cursor]
    if (!entry) throw new Error('MockAdapter: 剧本用完了')

    // 两种条目的寿命不同，这是本课的关键设计：
    // 函数条目是"常驻大脑"——每一轮都重新问它一次，像真模型那样只看当前请求做决策；
    // 静态条目是一次性剧本——读过就翻页，第二次 stream 就取不到了。
    if (typeof entry !== 'function') this.cursor += 1

    const chunks = typeof entry === 'function' ? entry(options) : entry
    for (const chunk of chunks) {
      // 每片之前等一等。真模型的延迟来自网络和推理，
      // 我们没法真等，但**必须等**——否则流式协议是假的。
      await sleep(CHUNK_DELAY_MS)
      yield chunk
    }
  }
}

/**
 * 假模型的"大脑"：看用户输入决定这一轮说什么。
 *
 * 真模型是靠训练数据学会"什么时候该调工具"的；我们没法训练，
 * 就用 if 把同样的决策写死。重点不在这段逻辑，而在于
 * **它输出的形状和真模型一模一样**——消费方完全感知不到差别。
 *
 * 注意签名收的是 GenerateOptions（整个请求），不是一句字符串：
 * 真模型看的是全部 messages，我们只看最后一条——至于是谁说的，
 * 在"请求即历史"之后已经不重要了，压缩摘要也是一条历史。
 */
export function decide(options: GenerateOptions): StreamChunk[] {
  const input = options.messages.at(-1)?.content ?? ''
  // 工具结果又喂回来了：这次该说人话了
  if (input.includes('°C')) {
    return textResponse(`${input}。出门看情况带把伞。`)
  }
  if (input.includes('刚才')) {
    // 只有模型能看见摘要时才答得上来；原始记录被 replace 顶掉之后就看不到了
    const summary = options.messages.find((message) => message.content.startsWith('（摘要）'))
    if (summary) return textResponse('你问了我北京天气，我查完还提醒了你带伞。')
    return textResponse('我没有历史记忆，每次请求只带当前这一句。')
  }
  if (input.includes('北京')) {
    return toolCallResponse('call-1', 'get_weather', { city: '北京' })
  }
  if (input.includes('天气')) {
    return toolCallResponse('call-2', 'get_weather', { city: '北京' })
  }
  // 新增：模型"选"了另一个工具。它不需要认识 calc 的实现，
  // 只要注册表里有这个名字，loop 就能把它调起来。
  if (input.includes('算') || input.includes('+')) {
    return toolCallResponse('call-3', 'calc', { a: 7, b: 6, op: '*' })
  }
  // 工具结果又喂回来了：算数结果是 "7 * 6 = 42" 这种形状。
  // 注意上面那句不能写成 includes('*')——那会把结果也当成"要算数"。
  if (/^[\d.]+\s*[-+*/]\s*[\d.]+\s*=/.test(input)) {
    return textResponse(`算好了：${input}`)
  }
  return textResponse(`我不知道怎么回答"${input}"，但我可以查天气、也会算数。`)
}

export function apply(ctx: Context) {
  ctx.plugin(MockAdapter, [decide])
}

import type { Context } from '@deepseek-ai/cordis'
import { Service } from '@deepseek-ai/cordis'
import Schema from '@deepseek-ai/schemastery'

declare module '@deepseek-ai/cordis' {
  interface Events {
    /**
     * 目录加载器扫完一个目录，往 cordis 里加了一批插件。
     * @param dir - 被扫描的目录（相对路径）。
     * @param count - 从这个目录里加载了几个插件。
     * @mode emit
     */
    'plugin-directory/loaded'(dir: string, count: number): void
  }
}

/** 一个目录里的插件清单。 */
export interface DirectoryManifest {
  /** 这个目录是干什么的，出现在启动日志里。 */
  readonly purpose: string
  /** 插件文件列表，相对本目录。 */
  readonly plugins: readonly string[]
}

/** 插件配置：加载哪个目录。 */
export interface Config {
  /** 目录路径，相对 cordis.yml 所在位置。 */
  root: string
}

/** 同名 schema 给 Cordis 看：运行前验证，缺的补默认值。 */
export const Config: Schema<Config> = Schema.object({
  root: Schema.string().default('.'),
})

/**
 * 目录加载器：扫一个文件夹，把里面的插件一个个递给 cordis。
 *
 * 本课的主题。`ctx.loader.create()` 一次只认一个文件，
 * 而一个能力（比如"工具"）通常长在一个文件夹里。
 * 这个 Service 把"文件夹"变成加载单位。
 */
export abstract class PluginDirectory extends Service {
  constructor(ctx: Context) { super(ctx, 'pluginDirectory') }

  /**
   * 加载一个目录。
   * @param dir - 目录路径，相对 cordis.yml 所在位置。
   * @returns 从这个目录里加载了几个插件。
   */
  abstract load(dir: string): Promise<number>
}

/**
 * Service Provider：读 manifest.ts，逐个 ctx.loader.create。
 *
 * 为什么不直接 `readdirSync` 扫文件？因为**显式清单比目录扫描安全**：
 * 一个 `_backup.ts`、一个临时 `test.ts` 都会被扫进来，而它们可能
 * 不是插件，或者是不该现在加载的插件。harness 真身的
 * packages/ 也是靠 package.json 的 exports 声明，不是扫文件名。
 */
export class MapPluginDirectory extends PluginDirectory {
  async load(dir: string): Promise<number> {
    const manifestUrl = new URL(`${dir.replace(/\/$/, '')}/manifest.js`, this.ctx.baseUrl)
    const manifest = (await import((globalThis as any).__DSH_MANIFEST__ ?? manifestUrl.href)) as { default: DirectoryManifest }

    let count = 0
    for (const plugin of manifest.default.plugins) {
      const url = new URL(`${dir.replace(/\/$/, '')}/${plugin.replace(/\.ts$/, '.js')}`, this.ctx.baseUrl)
      await this.ctx.loader.create({ name: url.href })
      count += 1
    }

    this.ctx.emit('plugin-directory/loaded', dir, count)
    return count
  }

  /**
   * 插件启动钩子：本 fiber 激活后才跑，此时服务已经能从 ctx 上取到。
   *
   * 为什么不在 `apply()` 里直接 `await ctx.pluginDirectory.load()`？
   * 因为 `ctx.plugin(X)` 只是**登记**了服务，要等这个插件的 fiber
   * 真正激活（ACTIVE）之后，`ctx.pluginDirectory` 才取得出来。
   * 在 apply 里伸手，只会拿到
   * `cannot get property "pluginDirectory" without inject`。
   *
   * 这个钩子的调用时机正好：apply 跑完、fiber 就绪。
   */
  async *[Service.init]() {
    yield () => {}
    await this.load(this.#root)
  }

  /** 要加载的目录，由 apply 从配置里写进来。 */
  #root = '.'

  /** 记录要加载的目录。 */
  setRoot(root: string) {
    this.#root = root
  }
}

/**
 * 应用入口：登记服务，把配置里的目录记下来。
 *
 * 真正的加载发生在 `[Service.init]` 钩子里——那时本插件的 fiber 已激活，
 * `ctx.pluginDirectory` 取得出来，而且能安全地往 loader 里添新条目。
 */
export function apply(ctx: Context, config: Config) {
  ctx.plugin(MapPluginDirectory)
  ctx.reflect.get('pluginDirectory', false)?.setRoot(config.root)
}

import type { Context } from '@deepseek-ai/cordis'
import { Tools, type ToolSchema } from './tools.ts'
import type { ToolArgs, ToolDefinition, ToolResult } from './define-tool.ts'

export const name = 'tools-registry'

/**
 * Service Provider：一个基于 Map 的工具注册表。
 *
 * register() 是第 02 课的"注册即效果"：注册方插件一卸载，
 * 这个工具定义自动从表里消失。
 */
class MapTools extends Tools {
  private readonly definitions = new Map<string, ToolDefinition>()
  private counter = 0

  register(definition: ToolDefinition): () => void {
    // ctx.effect 是"本插件卸载时自动执行"的注册点
    return this.ctx.effect(() => {
      this.definitions.set(definition.name, definition)
      // 注册即广播：谁想知道"现在有哪些工具"，挂这个事件就行
      this.ctx.emit('tools/change')
      return () => {
        this.definitions.delete(definition.name)
        this.ctx.emit('tools/change')
      }
    }, `tools.register(${definition.name})`)
  }

  get(name: string): ToolDefinition | undefined {
    return this.definitions.get(name)
  }

  list(): ToolDefinition[] {
    return [...this.definitions.values()]
  }

  schemas(): ToolSchema[] {
    // 只挑三个字段——execute 留在本地，不随请求出门
    return [...this.definitions.values()].map(({ name, description, parameters }) => ({
      name,
      description,
      parameters,
    }))
  }

  async call(name: string, args: unknown): Promise<ToolResult> {
    const definition = this.definitions.get(name)
    const callId = `call-${++this.counter}`
    if (!definition) {
      return { ok: false, callId, name, error: `工具不存在：${name}` }
    }
    try {
      const value = await definition.execute((args ?? {}) as ToolArgs, { callId })
      return { ok: true, callId, name, value }
    } catch (error) {
      return { ok: false, callId, name, error: error instanceof Error ? error.message : String(error) }
    }
  }
}

export function apply(ctx: Context) {
  ctx.plugin(MapTools)
}

import { Service, type Context } from '@deepseek-ai/cordis'
import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

/**
 * 一条会话记录。`data` 的形状由 `type` 决定。
 *
 * harness 真身里这是 `SessionEventMap`（packages/core/session/src/types.ts 第 281 行），
 * 同样是"一个 type 对应一种 data"的表。
 */
export interface SessionRecordMap {
  /** 用户说了一句话。 */
  'user/message': { content: string }
  /** 模型回答了一轮。 */
  'assistant/message': { text: string }
  /** 模型请求调用一个工具，arguments 是它吐出的原始 JSON 字符串。 */
  'tool/call': { callId: string; name: string; arguments: string }
  /** 工具执行完了，value 是返回值，isError 标记成功失败。 */
  'tool/result': { callId: string; name: string; value: unknown; isError: boolean }
}

/** 任意一种会话记录。 */
export type SessionRecord =
  | { [K in keyof SessionRecordMap]: { type: K; data: SessionRecordMap[K] } }[keyof SessionRecordMap]

/**
 * 会产生模型可见消息的记录类型。
 *
 * 日志里还有别的行（turn 边界、失败尝试），它们不进模型请求，
 * 只是排查问题时看的痕迹。harness 真身叫 `SurfaceEventType`
 * （packages/core/session/src/types.ts 第 439 行）。
 */
export type SurfaceRecordType = 'user/message' | 'assistant/message' | 'tool/result'

/** 一条记录在"模型能看到的历史"里的落点。 */
export type SurfaceOp =
  /** 追加到末尾：正常路径。 */
  | 'append'
  /** 替换一段已有节点：压缩上下文时用，被替换的行在日志里还在，只是不再进模型请求。 */
  | { op: 'replace'; startSeq: number; endSeq: number }

/**
 * 落盘的一行。
 *
 * 这是判别联合：`switch (line.type)` 会收窄 `line.data` 的类型，
 * 不用写任何断言。写法照抄 harness 真身的 `SessionEvent`
 * （packages/core/session/src/types.ts 第 493 行）——
 * `{ [K in ...]: {...} }[T]` 这层映射就是为了让联合生效。
 */
export type SessionLine = {
  [K in keyof SessionRecordMap]: {
    /** 会话内单调递增的序号，从 1 开始。 */
    readonly seq: number
    /** 写入时刻，Unix 毫秒。 */
    readonly time: number
    readonly type: K
    readonly data: SessionRecordMap[K]
    /** 它怎么进入模型可见历史。只有会产生消息的行带这个字段。 */
    readonly surfaceOp?: K extends SurfaceRecordType ? SurfaceOp : never
  }
}[keyof SessionRecordMap]

declare module '@deepseek-ai/cordis' {
  interface Context { session: Session }
}

/** 一条喂给模型的请求消息。 */
export interface ChatMessage {
  readonly role: 'user' | 'assistant' | 'tool'
  readonly content: string
}

/**
 * Service Definition：把"发生过的事"写进一条只增不减的日志。
 *
 * 这是 harness 的**唯一事实来源**。第 12 课的 agent loop 只在内存里跑，
 * 进程一退全忘了；有了它，任何时候都能把对话重放出来。
 */
export abstract class Session extends Service {
  constructor(ctx: Context) { super(ctx, 'session') }

  /**
   * 追加一条记录。
   * @param record - 记录内容。
   * @param op - 它怎么进入模型可见历史，默认 `'append'`。
   * @returns 分配到的序号。
   */
  abstract append(record: SessionRecord, op?: SurfaceOp): number

  /** 目前为止的全部记录，按 seq 升序。 */
  abstract list(): readonly SessionLine[]

  /**
   * 把日志折叠成模型能看的历史。
   *
   * 只走会产生消息的行；`replace` 标记的行会顶掉它覆盖的那一段。
   * 这就是 harness 的 `deriveMessages()`——每次请求前都重新折一遍，
   * 所以日志和模型看到的东西永远一致。
   */
  abstract deriveMessages(): ChatMessage[]

  /** 磁盘上已经有多少条记录——恢复来的，还是新起的。 */
  abstract readonly restoredCount: number

  /**
   * 从磁盘读回一个 session 的全部记录。
   *
   * 第一行是头行（`type: 'session'`），记录格式版本；剩下的是记录行。
   * 版本对不上直接抛错——**拒绝加载比猜着加载安全**。
   * @param file - session.jsonl 的路径。
   * @returns 按 seq 升序的记录。
   */
  static load(file: string): readonly SessionLine[] {
    const text = readFileSync(file, 'utf8')
    const lines = text.split('\n')
      .filter((line) => line.length > 0)
      .map((line) => JSON.parse(line) as SessionFileLine)
    const [header, ...rest] = lines
    if (header.type !== 'session') {
      throw new Error(`session 文件第一行必须是头行，实际是 ${String(header.type)}`)
    }
    if (header.version !== SESSION_FORMAT_VERSION) {
      throw new Error(
        `session 格式版本不匹配：文件是 v${header.version}，本程序只会 v${SESSION_FORMAT_VERSION}`,
      )
    }
    // 剩下的都是记录行；头行在上面已经核对掉了
    return rest.filter(isSessionLine)
  }
}

/** 头行不是记录。 */
function isSessionLine(line: SessionFileLine): line is SessionLine {
  return line.type !== 'session'
}

/**
 * 落盘文件的一行：要么是头行，要么是一条记录。
 *
 * 头行不是记录——它没有 `seq`，只说明"这个文件是什么格式的"。
 * harness 真身在 packages/session/session-persistence-jsonl/src/format.ts
 * 里也叫 `HeaderLine`，`type` 字段值是 `'session'`。
 */
export type SessionFileLine =
  | { type: 'session'; version: number }
  | SessionLine

/** 当前会话日志的格式版本。harness 真身是 `SESSION_FORMAT_VERSION = 4`。 */
export const SESSION_FORMAT_VERSION = 1

/**
 * Service Provider：JSONL 落地。
 *
 * 每行一条 JSON，追加写文件。harness 真身（packages/session/session-persistence-jsonl）
 * 用 zstd 压缩、分代文件名和原子替换，我们保留最核心的那个决定：
 * **append-only，写出去的行永不改写**。
 */
export class JsonlSession extends Session {
  private seq = 0
  private readonly records: SessionLine[] = []
  private readonly file: string
  /** 磁盘上已有多少条记录——恢复来的，还是新起的。 */
  readonly restoredCount: number

  constructor(ctx: Context, config: { file: string }) {
    super(ctx)
    this.file = join(config.file, 'session.jsonl')
    mkdirSync(dirname(this.file), { recursive: true })

    // 恢复：接着磁盘上已有的行往下写，seq 继续往上加
    if (existsSync(this.file)) {
      const existing = Session.load(this.file)
      this.records.push(...existing)
      this.seq = existing.at(-1)?.seq ?? 0
      this.restoredCount = existing.length
    } else {
      this.restoredCount = 0
      // 新文件第一行写头行：以后谁来读这个文件，先核对版本
      appendFileSync(this.file, `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`)
    }
  }

  append(record: SessionRecord, op: SurfaceOp = 'append'): number {
    this.seq += 1
    const line = this.toLine(this.seq, record, op)
    this.records.push(line)
    // 追加写：只往文件末尾加字节，不动已有内容
    appendFileSync(this.file, `${JSON.stringify(line)}\n`)
    return line.seq
  }

  /** 拼一行。`tool/call` 不进模型可见历史——它已经被同一轮的 assistant/message 代表了。 */
  private toLine(seq: number, record: SessionRecord, op: SurfaceOp): SessionLine {
    const time = Date.now()
    switch (record.type) {
      case 'user/message':
        return { seq, time, type: 'user/message', data: record.data, surfaceOp: op }
      case 'assistant/message':
        return { seq, time, type: 'assistant/message', data: record.data, surfaceOp: op }
      case 'tool/result':
        return { seq, time, type: 'tool/result', data: record.data, surfaceOp: op }
      case 'tool/call':
        return { seq, time, type: 'tool/call', data: record.data }
    }
  }

  list(): readonly SessionLine[] { return this.records }

  /**
   * 折叠日志。
   *
   * `surface` 是一个"模型能看到哪些 seq"的有序列表。
   * 追加就 push；替换就把 [startSeq, endSeq] 那段挖掉、换成新行。
   * 被挖掉的行在日志里一行不少，只是不再进模型请求。
   */
  deriveMessages(): ChatMessage[] {
    const surface: SessionLine[] = []
    for (const line of this.records) {
      const op = line.surfaceOp
      if (op === undefined) continue          // 非消息行：跳过
      if (op === 'append') { surface.push(line); continue }
      // replace：挖掉旧段，在原来的位置插入新行
      const start = surface.findIndex((node) => node.seq === op.startSeq)
      const end = surface.findIndex((node) => node.seq === op.endSeq)
      if (start === -1 || end === -1) continue
      surface.splice(start, end - start + 1, line)
    }
    return surface.map(toChatMessage)
  }

  /**
   * 把整个文件重写一遍。
   *
   * 注意头行得带上——它是文件的一部分，不是记录。
   * 这是本文件里唯一一处"整份重写"的路径，正常写入走的是 append。
   */
  flush(): void {
    const header = `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`
    const body = this.records.map((line) => `${JSON.stringify(line)}\n`).join('')
    writeFileSync(this.file, header + body)
  }
}

/** 把一条消息行翻译成模型请求里的消息。 */
function toChatMessage(line: SessionLine): ChatMessage {
  switch (line.type) {
    case 'user/message':
      return { role: 'user', content: line.data.content }
    case 'assistant/message':
      return { role: 'assistant', content: line.data.text }
    case 'tool/result':
      return { role: 'tool', content: String(line.data.value) }
    case 'tool/call':
      // 走不到这里：tool/call 没有 surfaceOp，deriveMessages 已经把它过滤掉了
      return { role: 'assistant', content: `${line.data.name}(${line.data.arguments})` }
  }
}

export function apply(ctx: Context) {
  ctx.plugin(JsonlSession, { file: '.sessions/demo' })
}

import { Service, type Context } from '@deepseek-ai/cordis'
import type { ToolDefinition, ToolParameters, ToolResult } from './define-tool.ts'

declare module '@deepseek-ai/cordis' {
  interface Context {
    tools: Tools
  }
  interface Events {
    /**
     * 有工具注册进来或摘出去。
     *
     * harness 真身（packages/core/tools/src/index.ts 第 208 行）也叫
     * `tools/change`。为什么需要它？因为插件的加载顺序由依赖拓扑决定，
     * **不写插件的人控制不了谁先谁后**。想知道"现在有哪些工具"，
     * 只能等注册表通知，不能在启动时假设它已经满了。
     * @mode emit
     */
    'tools/change'(): void
  }
}

/**
 * Service Definition：工具注册表。
 *
 * 它只知道"工具长什么样、怎么被调用"，不知道任何一个工具的具体实现。
 */
export abstract class Tools extends Service {
  constructor(ctx: Context) {
    super(ctx, 'tools')
  }

  /** 注册一个工具定义，返回的摘除函数随注册方插件的卸载自动执行。 */
  abstract register(definition: ToolDefinition): () => void

  /** 按名字取定义，没有则 undefined。 */
  abstract get(name: string): ToolDefinition | undefined

  /** 当前全部定义，按注册顺序排列。 */
  abstract list(): ToolDefinition[]

  /**
   * 递给模型看的工具清单。
   *
   * 只保留 name / description / parameters 三个字段——
   * `execute` 是本地代码，发给模型没有意义，还可能泄露实现细节。
   * harness 真身 [packages/core/tools/src/index.ts 第 1260 行](../../../deepseek-harness/packages/core/tools/src/index.ts#L1260)
   * 的 `schemas()` 干的就是这件事，注释里那词叫 allowlist（白名单）。
   */
  abstract schemas(): ToolSchema[]

  /** 执行一个工具；任何失败都收进 ToolResult，不往外抛。 */
  abstract call(name: string, args: unknown): Promise<ToolResult>
}

/** 递给模型看的工具描述：三个字段，缺一不可。 */
export interface ToolSchema {
  readonly name: string
  readonly description: string
  readonly parameters: ToolParameters
}

import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from './define-tool.ts'

export const name = 'weather-tool'

// 忘了这行，ctx.tools 会抛 "cannot get property "tools" without inject"
// （第 03 课的规矩：要拿 ctx 上的服务，必须先声明 inject）
export const inject = ['tools']

/**
 * Service Provider 的角色之一：往 ctx.tools 里放一个工具。
 *
 * 真身（packages/web/tool-web/src/search.ts）长这样：
 *   ctx.tools.register(defineTool({ name: 'web_search', ... }))
 * 我们连形状都照抄，只是把网络请求换成了假数据。
 */
export function apply(ctx: Context) {
  ctx.tools.register(defineTool({
    name: 'get_weather',
    description: '查询一个城市的天气。需要城市名。',
    parameters: {
      city: {
        type: 'string',
        required: true,
        description: '城市名，例如 "北京"',
      },
      unit: {
        type: 'string',
        enum: ['celsius', 'fahrenheit'],
        description: '温度单位，默认摄氏度。',
      },
    },
    async execute(args) {
      const city = String(args.city ?? '')
      // Keyless：假数据，不联网
      const table: Record<string, string> = {
        北京: '晴，12°C',
        上海: '小雨，18°C',
      }
      const forecast = table[city] ?? '晴，20°C（默认值）'
      const unit = args.unit === 'fahrenheit' ? '（已换算为华氏）' : ''
      return `${city}：${forecast}${unit}`
    },
  }))
}

import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from './define-tool.ts'

export const name = 'calc-tool'

export const inject = ['tools']

/**
 * 第二个工具插件。
 *
 * 它和 weather.ts 长得一模一样，唯一的差别是干的事不同。
 * 这就是"注册表"的全部意义：**加工具不用碰 loop 一行代码**，
 * 只要新写一个插件、在 cordis.yml 里加一行。
 */
export function apply(ctx: Context) {
  ctx.tools.register(defineTool({
    name: 'calc',
    description: '算一道四则运算。支持加减乘除。',
    parameters: {
      a: { type: 'number', required: true, description: '左操作数' },
      b: { type: 'number', required: true, description: '右操作数' },
      // required：模型漏了它就该被校验器拦住，而不是走到 default 分支
      // 吐一句"不支持的运算符：undefined"——那种失败模型看不懂，也学不会。
      op: { type: 'string', required: true, enum: ['+', '-', '*', '/'], description: '运算符' },
    },
    execute(args) {
      const a = Number(args.a)
      const b = Number(args.b)
      switch (args.op) {
        case '+': return `${a} + ${b} = ${a + b}`
        case '-': return `${a} - ${b} = ${a - b}`
        case '*': return `${a} * ${b} = ${a * b}`
        case '/': return `${a} / ${b} = ${b === 0 ? '除数不能为 0' : a / b}`
        default:
          return `不支持的运算符：${String(args.op)}`
      }
    },
  }))
}

/**
 * 简化版 defineTool。
 *
 * harness 真身（packages/core/tools/src/schema.ts 第 554 行）在这里做三件事：
 * 1. 把手写的 JSON Schema DSL 编译成标准 JSON Schema，并用它校验模型传来的参数；
 * 2. 从 DSL 反推出 TypeScript 类型，让 execute 里的 args 有补全；
 * 3. 把校验包在 execute 外层，任何违规都以 ToolArgsError 的形式抛出。
 *
 * 第 10 课只做了"组装"。本课补上第 1 和第 3 件事——**校验**。
 */

import { compileNode, ToolArgsError, validateValue, type JsonSchemaNode, type SchemaSpec } from './json-schema.ts'

/** 模型传来的参数：一个 JSON 对象。 */
export type ToolArgs = Record<string, unknown>

/** 参数 schema：一棵 JSON Schema 树。 */
export type ToolParameters = Record<string, unknown>

/** 执行上下文：harness 真身叫 ToolRunContext，这里只保留两个字段。 */
export interface ToolRunContext {
  /** 本次调用的 id，由注册表分配。 */
  readonly callId: string
  /** 取消信号：调用方 abort 时，工具应当尽快收手。 */
  readonly signal?: AbortSignal
}

/** 一次工具调用的结果。成功失败都走这个壳，不抛异常。 */
export type ToolResult =
  | { ok: true; callId: string; name: string; value: unknown }
  | { ok: false; callId: string; name: string; error: string }

/** 一个工具的完整定义。 */
export interface ToolDefinition {
  readonly name: string
  /** 写给模型看的说明，模型据此决定要不要调用它。 */
  readonly description: string
  /** 编译后的参数 schema，既校验也进模型请求。 */
  readonly parameters: ToolParameters
  /** 具体干活的部分。参数已通过校验。 */
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}
export interface DefineToolOptions {
  name: string
  description: string
  /** 手写的参数 schema（第 11 课细讲）。 */
  parameters?: Record<string, SchemaSpec>
  execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> | unknown
}

/**
 * 定义工具。
 * @param options - 工具的名称、说明、参数 schema 和执行体。
 * @returns 一个 registry-ready 的定义，execute 已自带参数校验。
 */
export function defineTool(options: DefineToolOptions): ToolDefinition {
  const compiled = compileParameters(options.parameters)

  return {
    name: options.name,
    description: options.description,
    parameters: compiled,
    async execute(args: ToolArgs, exec: ToolRunContext): Promise<unknown> {
      // 校验发生在用户的 execute 之前：不合规的参数根本到不了业务代码
      const violations = validateValue(compiled, args)
      if (violations.length > 0) {
        throw new ToolArgsError(options.name, violations)
      }
      return options.execute(args, exec)
    },
  }
}

/** 把"每个参数一条声明"的手写 DSL 编译成一个对象根的 JSON Schema。 */
function compileParameters(spec: Record<string, SchemaSpec> | undefined): JsonSchemaNode {
  if (spec === undefined) return { type: 'object', additionalProperties: true }
  const node = compileNode({ type: 'object', properties: spec })
  // 顶层参数对象是"开放"的：模型可以额外带字段，不像 output schema 那样严苛
  node.additionalProperties = true
  return node
}

/**
 * 简化版 JSON Schema 校验器。
 *
 * harness 真身在 packages/core/tools/src/json-schema.ts，它只接受一个
 * 受限的 JSON Schema 子集：一个标量 type、对象 properties/required、
 * 布尔 additionalProperties、数组 items、标量 enum/const。任何子集之外的
 * 关键字直接拒绝，而不是"接受但不校验"——因为那会给作者一种虚假的安全感。
 *
 * 本课实现同款子集的教学版。
 */

/** 校验错误：模型传来的参数不符合声明。 */
export class ToolArgsError extends Error {
  constructor(
    readonly toolName: string,
    readonly violations: string[],
  ) {
    super(`invalid arguments: ${violations.join('; ')}`)
    this.name = 'ToolArgsError'
  }
}

/** 手写 DSL 里的一个节点。 */
export type SchemaSpec =
  | { type: 'string'; required?: true; description?: string; enum?: readonly string[] }
  | { type: 'number'; required?: true; description?: string }
  | { type: 'boolean'; required?: true; description?: string }
  | { type: 'array'; required?: true; description?: string; items?: SchemaSpec }
  | { type: 'object'; required?: true; description?: string; additionalProperties?: boolean; properties?: Record<string, SchemaSpec> }

/** 编译后的 JSON Schema 节点（只保留校验需要的字段）。 */
export interface JsonSchemaNode {
  type: string
  description?: string
  enum?: readonly (string | number | boolean | null)[]
  required?: string[]
  additionalProperties?: boolean
  items?: JsonSchemaNode
  properties?: Record<string, JsonSchemaNode>
  /** 允许作为普通 JSON 对象在工具之间传递。 */
  [key: string]: unknown
}

/**
 * 把手写 DSL 的一个节点编译成 JSON Schema。
 * @param spec - 手写 DSL 节点。
 * @returns 编译后的 JSON Schema 节点。
 */
export function compileNode(spec: SchemaSpec): JsonSchemaNode {
  const node: JsonSchemaNode = { type: spec.type }
  if (spec.description !== undefined) node.description = spec.description
  if ('enum' in spec && spec.enum !== undefined) node.enum = spec.enum
  if (spec.type === 'array' && spec.items !== undefined) {
    node.items = compileNode(spec.items)
  }
  if (spec.type === 'object') {
    node.additionalProperties = spec.additionalProperties ?? false
    if (spec.properties !== undefined) {
      node.properties = {}
      node.required = []
      for (const [key, child] of Object.entries(spec.properties)) {
        node.properties[key] = compileNode(child)
        if (child.required === true) node.required.push(key)
      }
      if (node.required.length === 0) delete node.required
    }
  }
  return node
}

/**
 * 校验一个值是否符合编译后的 schema。
 * @param schema - 编译后的 schema。
 * @param value - 待校验的值，任意来源。
 * @param path - 当前路径，用于错误信息定位。
 * @returns 违规列表；空数组表示通过。
 */
export function validateValue(schema: JsonSchemaNode, value: unknown, path = '$'): string[] {
  const violations: string[] = []
  const at = (suffix: string) => suffix === '' ? path : `${path}.${suffix}`

  switch (schema.type) {
    case 'string':
      if (typeof value !== 'string') {
        violations.push(`${at('')} 必须是字符串，收到 ${describe(value)}`)
        break
      }
      if (schema.enum !== undefined && !schema.enum.includes(value)) {
        violations.push(`${at('')} 必须是 ${schema.enum.map((entry) => JSON.stringify(entry)).join(' / ')} 之一`)
      }
      break

    case 'number':
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        violations.push(`${at('')} 必须是数字，收到 ${describe(value)}`)
      }
      break

    case 'boolean':
      if (typeof value !== 'boolean') {
        violations.push(`${at('')} 必须是布尔值，收到 ${describe(value)}`)
      }
      break

    case 'array': {
      if (!Array.isArray(value)) {
        violations.push(`${at('')} 必须是数组，收到 ${describe(value)}`)
        break
      }
      if (schema.items === undefined) break
      value.forEach((entry, index) => {
        violations.push(...validateValue(schema.items!, entry, `${path}[${index}]`))
      })
      break
    }

    case 'object': {
      if (typeof value !== 'object' || value === null || Array.isArray(value)) {
        violations.push(`${at('')} 必须是对象，收到 ${describe(value)}`)
        break
      }
      const record = value as Record<string, unknown>
      for (const key of schema.required ?? []) {
        if (record[key] === undefined) {
          violations.push(`${at(key)} 是必填项，但没有提供`)
        }
      }
      for (const [key, child] of Object.entries(schema.properties ?? {})) {
        if (record[key] === undefined) continue
        violations.push(...validateValue(child, record[key], at(key)))
      }
      if (schema.additionalProperties === false) {
        for (const key of Object.keys(record)) {
          if (schema.properties === undefined || !(key in schema.properties)) {
            violations.push(`${at(key)} 不是声明过的字段（additionalProperties: false）`)
          }
        }
      }
      break
    }

    default:
      throw new Error(`不支持的 schema 类型：${schema.type}`)
  }

  return violations
}

/** 把一个未知值描述成一句人能看懂的话，用于错误信息。 */
function describe(value: unknown): string {
  if (value === null) return 'null'
  if (Array.isArray(value)) return '数组'
  if (typeof value === 'object') return '对象'
  return JSON.stringify(value) ?? String(value)
}

import { Service, type Context } from '@deepseek-ai/cordis'

declare module '@deepseek-ai/cordis' {
  interface Context { llm: Llm }
  interface Events {
    /** 消费方向 llm 服务发出一次请求，由提供方处理。 */
    'llm/generate'(input: string): void
  }
}

export type StreamChunk =
  | { type: 'block-start'; index: number; blockType: 'text' | 'tool-call' }
  | { type: 'text-delta'; index: number; text: string }
  | { type: 'reasoning-delta'; index: number; text: string }
  | { type: 'tool-call-delta'; index: number; id: string; name?: string; argumentsDelta: string }
  | { type: 'block-end'; index: number; block: ContentBlock }
  | { type: 'usage'; usage: { inputTokens: number; outputTokens: number } }
  | { type: 'finish'; reason: { kind: 'stop' | 'tool-calls' | 'max-tokens' | 'error' } }

export type ContentBlock =
  | { type: 'text'; text: string }
  | { type: 'tool-call'; id: string; name: string; arguments: string }

export interface GenerateOptions {
  messages: { role: 'system' | 'user' | 'assistant' | 'tool'; content: string }[]
  maxTokens?: number
  signal?: AbortSignal
}

export abstract class Llm extends Service {
  constructor(ctx: Context) { super(ctx, 'llm') }
  abstract stream(options: GenerateOptions): AsyncIterable<StreamChunk>
}

import type { Context } from '@deepseek-ai/cordis'
import type { GenerateOptions } from './llm.ts'
import type { ToolResult } from './define-tool.ts'
import type { SessionLine } from './session.ts'

declare module '@deepseek-ai/cordis' {
  interface Events {
    /** 用户说了一句话，agent 处理一轮。 */
    'agent/turn'(input: string): void
    /** 把前面的轮次折叠成一条摘要。 */
    'agent/compact'(fromSeq: number, toSeq: number, summary: string): void
  }
}

export const name = 'agent'
export const inject = ['llm', 'tools', 'session']

/**
 * 一次工具调用的时限，毫秒。
 *
 * 真身是 guard/timeout-policy：每个工具自己声明 `timeoutMs`，
 * 包装器 armed 这个期限，到点把 signal abort 掉，再把结果替换成
 * 一条结构化的 TOOL_TIMEOUT。教学版没法让假工具挂住，所以用
 * 一个统一的常量——但它演示的是同一件事：**等待必须有上限。**
 */
const TOOL_TIMEOUT_MS = 500

/**
 * 重复调用多少次算"没有进展"。
 *
 * 真身 repeat-tool-reminder 的默认阈值是 [3, 5, 8]：第一次温柔提醒，
 * 后面逐步升级到带工具名和参数详情的警告。教学版取 3，
 * 而且只演示"到阈值就提醒"这一档。
 */
const REPEAT_THRESHOLD = 3

/** 失败后最多再让模型试几次。递归没有头就会绕到天荒地老。 */
const MAX_RECOVERY_DEPTH = 2

/** 一轮对话里模型给出的指令：要么说话，要么调工具。 */
type ModelTurn =
  | { kind: 'text'; text: string }
  | { kind: 'tool-call'; id: string; name: string; args: Record<string, unknown> }

/**
 * Consumer：agent loop 的第六版。
 *
 * 前三版跑完就忘（或者只记得自己那次）。第四版补上**能力协商**：
 * 这个插件声明了自己要 `llm`、`tools`、`session` 三项能力，cordis 就
 * 替我们盯着它们。齐了才启动，缺了就 FAILED——而不是等第一次用的
 * 时候才炸。
 *
 * 第五版的主题是**流式**：不再等模型把整句话说完，每收到一片
 * text-delta 就立刻打到屏幕上。协议一个字没改，改的是"什么时候用"。
 *
 * 本版（第六版）的主题是**错误恢复**：工具失败了，这一轮不能就这么
 * 散了。失败得进日志、得让模型看见、得给它一次换办法的机会——
 * 但也要有边界（超时、重复检测、重试上限），否则恢复本身会变成新的死循环。
 */
export function apply(ctx: Context) {
  ctx.on('agent/turn', (input) => { void run(input) })
  ctx.on('agent/compact', (fromSeq, toSeq, summary) => { compact(fromSeq, toSeq, summary) })

  // 启动第一件事：报告从磁盘恢复了什么
  const restored = ctx.session.restoredCount
  if (restored > 0) {
    console.log(`=== 从磁盘恢复了 ${restored} 条记录，seq 接着 #${ctx.session.list().at(-1)?.seq ?? 0} 往下编 ===`)
    console.log('=== 模型看到的历史 ===')
    for (const message of ctx.session.deriveMessages()) {
      console.log(`[${message.role}] ${message.content}`)
    }
  } else {
    console.log('=== 没有找到历史，开一个新会话 ===')
  }

  /**
   * 三轮对话，串行不并行。
   *
   * 上一课这里是三个 setTimeout，间隔 50ms——因为那一轮的
   * 模型是"瞬间吐完"的，50ms 足够跑完一整轮。
   * 本课不行了：**一轮现在要花几百毫秒**（几十片 × 60ms），
   * 50ms 后第二轮就会插进来，屏幕上三行字互相穿插，
   * 日志的 seq 也会因为两个 run 同时 append 而错乱。
   *
   * 所以改成 await 一个、再 await 下一个。
   * 这不是"流式特有的麻烦"，而是**任何异步流水线的通用纪律**：
   * 只要一步变慢了，原本靠"猜时间"排的队就会撞车。
   * 真正的排队方式是等前一个真的做完。
   */
  void (async () => {
    if (restored > 0) {
      await run('刚才我问了什么？')
    } else {
      await run('北京天气怎么样？')
      await run('帮我算 7*6')
      await run('你好')
      // 聊完，把 #1~#12 折成一条摘要。
      // endSeq 必须是**摘要之前最后一条记录**：#12（你好那一轮的 assistant/message）。
      // 摘要自己落在 #13，它还没进日志，写 13 会让"找终点"的那一步落空，
      // 压缩被静默跳过。多写几轮这个数字就得重数——第 25 课会处理它。
      compact(1, 12, '（摘要）用户问了北京天气和一道乘法，模型分别调了 get_weather 和 calc。')
    }
    reportCapabilities()
    replay()
  })()

  /**
   * 工具清单：等注册表通知，不自己猜时机。
   *
   * 为什么不能在 apply 函数体里直接 `ctx.tools.schemas()`？因为 cordis 按
   * **依赖拓扑**排插件的加载顺序：agent 声明了 `inject: ['llm','tools','session']`，
   * 它要的三个服务必须先把 provider 建好，所以 agent 的 apply 排在 provider
   * 之后、**但排在 weather-tool / calc-tool 之前**——后两者只 inject 了
   * `tools`，拓扑上没人催它们，就按 cordis.yml 的顺序落到最后。
   *
   * 也就是说：apply 函数体执行的那一刻，注册表**恰好是空的**。
   * 而这个顺序由依赖关系决定，写 yml 的人控制不了。
   * 所以"现在有哪些工具"这件事，只能等注册表通知，不能自己数。
   *
   * 那为什么还要 `setTimeout` 包一层？因为插件是一个个加载的，
   * weather-tool 注册时会响一次，calc-tool 注册时又响一次。
   * 每次响都打印，就会打出两份不完整的清单。
   * 所以：**每次变化只重新排一次打印，等本轮事件循环安静下来再打**。
   */
  let scheduled = false
  ctx.on('tools/change', () => {
    if (scheduled) return
    scheduled = true
    setTimeout(printTools, 0)
  })

  function printTools() {
    console.log('=== 模型能选的工具 ===')
    for (const schema of ctx.tools.schemas()) {
      console.log(`- ${schema.name}：${schema.description}`)
    }
  }

  /**
   * 对账：我声明要的能力，注册表现在真的都有了吗？
   *
   * 这就是本课的主题。`ctx.fiber.inject` 是本插件声明的那张需求表，
   * `ctx.reflect.props` 是全应用登记过的服务名册。
   * 两边一减，缺谁一目了然——而且是在**启动阶段**减，不是等
   * 某次调用踩空了才炸。
   *
   * 注意它读的是 `props`（登记册），不是 `store`（实例）。
   * 登记册里有名字，不代表现在有实例——第 19 课的工具就是
   * 先登记、后注册的。缺名字才是真缺。
   */
  function reportCapabilities() {
    console.log('\n=== 能力对账 ===')
    for (const service of Object.keys(ctx.fiber.inject)) {
      const registered = Object.hasOwn(ctx.reflect.props, service)
      const status = registered ? '齐' : '缺'
      console.log(`- ${service}：${status}`)
      if (!registered) {
        console.log(`  没人提供 ${service}——cordis.yml 里少了一个 provider，或者它自己加载失败了`)
      }
    }
  }

  async function run(input: string) {
    console.log(`\n=== 用户说：${input} ===`)
    ctx.session.append({ type: 'user/message', data: { content: input } })

    // 关键一行：messages 不是手搓的，是从日志折出来的
    const options: GenerateOptions = { messages: ctx.session.deriveMessages() }
    const turn = await stream(ctx, options)

    switch (turn.kind) {
      case 'text':
        // 正文连标签一起在 stream() 里打完了，这里只写日志。
        // 上一课是 `console.log('[模型回答] ' + turn.text)` 整句一次打完；
        // 流式之后**不能再打一遍正文**——用户会看到同一个句子出现两次。
        ctx.session.append({ type: 'assistant/message', data: { text: turn.text } })
        break

      case 'tool-call': {
        console.log(`[模型决定] 调用 ${turn.name}，参数 ${JSON.stringify(turn.args)}`)
        // 注意：arguments 存的是模型吐出的**原始字符串**，不是我们 parse 后的对象
        ctx.session.append({
          type: 'tool/call',
          data: { callId: turn.id, name: turn.name, arguments: JSON.stringify(turn.args) },
        })
        await executeTool(turn)
        break
      }
    }
  }

  /**
   * 执行一次工具调用，失败后**把失败喂回模型**。
   *
   * 上一课这里是个 if/else：成功就问一次模型，失败就打印+记日志，
   * 然后 run() 返回——这一轮就这么结束了，模型一个字都不知道。
   * 本课补上另一半：**失败也是一次结果，模型有权看见它、换一个办法。**
   *
   * 这是真身 `packages/guard` 想解决的问题。`repeat-tool-reminder` 盯着
   * "模型用一模一样的参数反复调同一个工具"，`timeout-policy` 给工具
   * 装上时限。两件事的共同前提是：**失败必须回到对话里**，否则
   * 模型只会一遍遍重复同一个动作——它看不见别的东西。
   */
  async function executeTool(call: Extract<ModelTurn, { kind: 'tool-call' }>, depth = 0) {
    // 超时：给工具一个上限。真身是 guard/timeout-policy，工具自己声明
    // timeoutMs、honor exec.signal；教学版简化成统一的超时常数，
    // 用 AbortController 把"到点了"变成一个 signal。
    const abort = new AbortController()
    const timer = setTimeout(() => { abort.abort() }, TOOL_TIMEOUT_MS)
    let result: ToolResult
    try {
      result = await ctx.tools.call(call.name, call.args, abort.signal)
    } catch (error) {
      // 工具直接抛异常（不是返回失败）：第 19 课的注册表只兜 execute 里的错，
      // 这里兜的是"连注册表都没走完"的错。一样当失败处理，不能让它炸掉 loop。
      result = { ok: false, callId: call.id, name: call.name, error: describeError(error) }
    } finally {
      clearTimeout(timer)
    }

    if (result.ok) {
      console.log(`[工具返回] ${String(result.value)}`)
      ctx.session.append({
        type: 'tool/result',
        data: { callId: call.id, name: call.name, value: result.value, isError: false },
      })

      // 工具结果有了，再问模型一次，让它说人话——这次它看得见刚才的调用和返回
      const follow = await stream(ctx, { messages: ctx.session.deriveMessages() })
      if (follow.kind === 'text') {
        ctx.session.append({ type: 'assistant/message', data: { text: follow.text } })
      }
      return
    }

    // 失败路径：先看见，再判断要不要提醒，最后把话筒还给模型
    console.log(`[工具失败] ${result.error}`)
    ctx.session.append({
      type: 'tool/result',
      data: { callId: call.id, name: call.name, value: result.error, isError: true },
    })

    // 重复检测：同样的工具+同样的参数，连续第几次了？
    const repeats = observeRepeat(call.name, JSON.stringify(call.args))
    if (repeats >= REPEAT_THRESHOLD) {
      // 这不是一条"给模型看的结果"，是一条**旁白**：提醒它换个办法。
      // 真身叫 additionalContexts，带 source 标签，渲染时不会冒充用户说的话。
      const notice = `你已经用同样的参数连续调了 ${repeats} 次 ${call.name}，这没有进展。换个工具、换些参数，或者直接告诉用户你做不到。`
      console.log(`[循环提醒] ${notice}`)
      ctx.session.append({ type: 'notice/message', data: { text: notice } })
    }

    // 失败之后也问一次模型。它看得见刚才的 tool/result（isError: true），
    // 有机会换一个工具、换一组参数，或者老实说"这个我办不到"。
    // **不问的话，这一轮就白失败了**——日志里多一行，对话里什么都没发生。
    const recovery = await stream(ctx, { messages: ctx.session.deriveMessages() })
    switch (recovery.kind) {
      case 'text':
        ctx.session.append({ type: 'assistant/message', data: { text: recovery.text } })
        break
      case 'tool-call': {
        // 模型换了个办法。递归要有个头——超过重试上限就收手，
        // 否则一个坏工具能让它绕到天荒地老。
        if (depth >= MAX_RECOVERY_DEPTH) {
          console.log(`[放弃恢复] 已经重试 ${MAX_RECOVERY_DEPTH} 次，收手`)
          ctx.session.append({
            type: 'notice/message',
            data: { text: `恢复重试达到上限（${MAX_RECOVERY_DEPTH} 次），本轮结束。` },
          })
          return
        }
        ctx.session.append({
          type: 'tool/call',
          data: { callId: recovery.id, name: recovery.name, arguments: JSON.stringify(recovery.args) },
        })
        await executeTool(recovery, depth + 1)
        break
      }
    }
  }

  /**
   * 压缩：往日志里**追加**一条摘要，标记它顶掉 [fromSeq, toSeq]。
   *
   * 注意是追加，不是删除。旧的行一条不少地还在文件里，
   * 只是从此不进模型请求——这就是 harness 的 compaction 路子。
   */
  function compact(fromSeq: number, toSeq: number, summary: string) {
    console.log(`\n=== 压缩：#${fromSeq}~#${toSeq} 折成一条摘要 ===`)
    const seq = ctx.session.append(
      { type: 'assistant/message', data: { text: summary } },
      { op: 'replace', startSeq: fromSeq, endSeq: toSeq },
    )
    console.log(`摘要落成 #${seq}，它顶掉了 #${fromSeq}~#${toSeq}`)
  }

  /** 重放：日志是唯一事实来源，屏幕上的字早没了，日志还在。 */
  function replay() {
    const lines = ctx.session.list()
    console.log(`\n=== 日志全量（${lines.length} 条）===`)
    for (const line of lines) {
      console.log(`#${line.seq} [${line.type}] ${describe(line)}${opNote(line)}`)
    }

    const messages = ctx.session.deriveMessages()
    console.log(`\n=== 模型看到的历史（折叠后 ${messages.length} 条）===`)
    for (const message of messages) {
      console.log(`[${message.role}] ${message.content}`)
    }
  }

  /** 压缩标记只在日志里可见，模型那一侧看不到。 */
  function opNote(line: SessionLine): string {
    const op = line.surfaceOp
    if (op === undefined || op === 'append') return ''
    return `　← replace #${op.startSeq}~#${op.endSeq}`
  }

  function describe(line: SessionLine): string {
    switch (line.type) {
      case 'user/message':
        return line.data.content
      case 'assistant/message':
        return line.data.text
      case 'tool/call':
        return `${line.data.name}(${line.data.arguments})`
      case 'tool/result':
        return line.data.isError ? `失败：${String(line.data.value)}` : String(line.data.value)
      case 'notice/message':
        return line.data.text
    }
  }
}

/**
 * 流式消费：每收到一片就打印，同时把碎片拼回整块。
 *
 * 和第 09 课的 `for await` 打印相比，这里多了一件事：
 * **打印和拼装同时进行。** 用户看到字一个个蹦出来（体验），
 * 日志拿到的是拼好的完整块（正确性）——两者不冲突，
 * 因为 text-delta 的拼接就是字符串相加，来一片加一片。
 *
 * 注意 `process.stdout.write` 而不是 `console.log`：
 * log 每次调用都自带换行，会把一行字拆成很多行。
 * 流式的要点就是**不换行**，直到块结束。
 *
 * `[模型回答]` 这个标签也在本函数里打，而且只在第一片正文到来时
 * 打一次。标签是"事前"的：它得和正文出现在同一行，事后再补
 * 就只能另起一行贴在后面，读起来像是另一个句子。
 */
async function stream(ctx: Context, options: GenerateOptions): Promise<ModelTurn> {
  // index → 已拼接的文本/参数
  const texts = new Map<number, string>()
  const calls = new Map<number, { id: string; name: string; arguments: string }>()
  // 这一轮有没有往屏幕上写过正文？工具调用那一轮一个字都不写，
  // 结尾就不能补换行——否则会多出一个空行。
  // reasoning-delta 不算正文：它没有标签，也不参与换行判断。
  let wroteText = false

  for await (const chunk of ctx.llm.stream(options)) {
    switch (chunk.type) {
      case 'text-delta':
        texts.set(chunk.index, (texts.get(chunk.index) ?? '') + chunk.text)
        // 第一片正文先亮标签，正文跟在它后面一个字一个字蹦出来
        if (!wroteText) {
          process.stdout.write('[模型回答] ')
          wroteText = true
        }
        process.stdout.write(chunk.text)
        break
      case 'reasoning-delta':
        // 思考过程：本课的假模型不产出它，但真模型会。
        // 打印出来让"流式"这件事更明显——它是先于正文出现的。
        process.stdout.write(chunk.text)
        break
      case 'tool-call-delta': {
        const existing = calls.get(chunk.index) ?? { id: chunk.id, name: '', arguments: '' }
        // name 可能只在第一条 delta 上出现
        if (chunk.name !== undefined) existing.name = chunk.name
        existing.arguments += chunk.argumentsDelta
        calls.set(chunk.index, existing)
        break
      }
      case 'block-end':
        if (chunk.block.type === 'tool-call') {
          // 工具参数拼完了，这里就是"模型说完话了"的时刻
          process.stdout.write('\n')
          return { kind: 'tool-call', id: chunk.block.id, name: chunk.block.name, args: parseArgs(chunk.block.arguments) }
        }
        break
      case 'usage':
        break
      case 'finish':
        break
      default:
        break
    }
  }

  const text = [...texts.entries()].sort(([a], [b]) => a - b).map(([, value]) => value).join('')
  // 正文逐字打完，补一个换行，让后面的 === 用户说 === 从新行开始
  if (wroteText) process.stdout.write('\n')
  return { kind: 'text', text }
}

/**
 * 上一课的 `collect(stream)` 长这样：
 *
 * ```ts
 * async function collect(stream: AsyncIterable<StreamChunk>): Promise<ModelTurn> {
 *   for await (const chunk of stream) { texts.set(chunk.index, ...) }
 *   return { kind: 'text', text: ... }
 * }
 * ```
 *
 * 它和上面这个函数的唯一区别：收完所有 chunk 才返回，
 * 所以手里没有任何东西可打——只能等整句话到齐再显示。
 * 流式和非流式的分界线**不在协议，在消费时机**：
 * 协议两边一模一样（都是 StreamChunk），差别只在
 * "我是在 yield 的那一刻用它，还是在流结束之后用它"。
 */

/** 解析工具参数；解析失败时返回空对象——校验层会给出准确报错。 */
function parseArgs(json: string): Record<string, unknown> {
  try {
    const parsed: unknown = JSON.parse(json)
    return typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)
      ? parsed as Record<string, unknown>
      : {}
  } catch {
    return {}
  }
}

/**
 * 连续重复检测。
 *
 * 记录上一次调用的身份（工具名 + 规范化参数），和这次的比一比：
 * 一样就连贯计数 +1，不一样就重新从 1 开始。
 *
 * 真身 repeat-tool-reminder 比这讲究得多——它深排序 JSON 再序列化，
 * 所以 `{a:1,b:2}` 和 `{b:2,a:1}` 算同一次调用；还支持 include/exclude
 * 通配符和分级阈值。教学版只保留那个核心判断：**同样的动作连续做，
 * 就是没有进展。**
 */
function observeRepeat(name: string, argsJson: string): number {
  const key = `${name}(${argsJson})`
  const count = lastCallKey === key ? lastCallCount + 1 : 1
  lastCallKey = key
  lastCallCount = count
  return count
}

/** 上一次调用的身份，见 observeRepeat。 */
let lastCallKey = ''
/** 它已经连续重复了几次。 */
let lastCallCount = 0

/**
 * 把任意异常描述成一句人能看懂的话。
 *
 * `catch (error)` 收到的是 `unknown`——TypeScript 不允许你直接
 * `.message`。先收窄到 Error，剩下的用 String() 兜底。
 * 注意这里**不重新抛出**：到了这一层，任何异常都是"工具失败"，
 * 都要变成模型能看见的一句话。
 */
function describeError(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

import type { Context } from '@deepseek-ai/cordis'
import { Llm, type GenerateOptions, type StreamChunk } from './llm.ts'

export function textResponse(text: string): StreamChunk[] {
  return [
    { type: 'block-start', index: 0, blockType: 'text' },
    ...Array.from(text, (char): StreamChunk => ({ type: 'text-delta', index: 0, text: char })),
    { type: 'block-end', index: 0, block: { type: 'text', text } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: text.length } },
    { type: 'finish', reason: { kind: 'stop' } },
  ]
}

export function toolCallResponse(id: string, name: string, args: object): StreamChunk[] {
  const argumentsJson = JSON.stringify(args)
  return [
    { type: 'block-start', index: 0, blockType: 'tool-call' },
    { type: 'tool-call-delta', index: 0, id, name, argumentsDelta: argumentsJson.slice(0, 5) },
    { type: 'tool-call-delta', index: 0, id, argumentsDelta: argumentsJson.slice(5) },
    { type: 'block-end', index: 0, block: { type: 'tool-call', id, name, arguments: argumentsJson } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: 5 } },
    { type: 'finish', reason: { kind: 'tool-calls' } },
  ]
}

/**
 * 每片之间的间隔，毫秒。
 *
 * 不设成 0 的原因：生成器的 `yield` 之间如果没有 await，
 * 整个流会在**同一个 tick 里全部吐完**，消费方的 `for await`
 * 一次都等不到——那就不叫流式，叫批量。
 * 一个 `await sleep(0)` 就足以把控制权交回事件循环，
 * 但那样眼睛看不出来。这里故意放慢，让你在终端里看见字一个个来。
 */
const CHUNK_DELAY_MS = 60

/** 让出事件循环，等 `ms` 毫秒。 */
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => { setTimeout(resolve, ms) })
}

export const name = 'llm-mock'

export class MockAdapter extends Llm {
  private cursor = 0

  constructor(
    ctx: Context,
    private script: (StreamChunk[] | ((options: GenerateOptions) => StreamChunk[]))[],
  ) {
    super(ctx)
  }

  async *stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const entry = this.script[this.cursor]
    if (!entry) throw new Error('MockAdapter: 剧本用完了')

    // 两种条目的寿命不同，这是本课的关键设计：
    // 函数条目是"常驻大脑"——每一轮都重新问它一次，像真模型那样只看当前请求做决策；
    // 静态条目是一次性剧本——读过就翻页，第二次 stream 就取不到了。
    if (typeof entry !== 'function') this.cursor += 1

    const chunks = typeof entry === 'function' ? entry(options) : entry
    for (const chunk of chunks) {
      // 每片之前等一等。真模型的延迟来自网络和推理，
      // 我们没法真等，但**必须等**——否则流式协议是假的。
      await sleep(CHUNK_DELAY_MS)
      yield chunk
    }
  }
}

/**
 * 假模型的"大脑"：看用户输入决定这一轮说什么。
 *
 * 真模型是靠训练数据学会"什么时候该调工具"的；我们没法训练，
 * 就用 if 把同样的决策写死。重点不在这段逻辑，而在于
 * **它输出的形状和真模型一模一样**——消费方完全感知不到差别。
 *
 * 注意签名收的是 GenerateOptions（整个请求），不是一句字符串：
 * 真模型看的是全部 messages，我们只看最后一条——至于是谁说的，
 * 在"请求即历史"之后已经不重要了，压缩摘要也是一条历史。
 */
export function decide(options: GenerateOptions): StreamChunk[] {
  const input = options.messages.at(-1)?.content ?? ''
  // 工具结果又喂回来了：这次该说人话了
  if (input.includes('°C')) {
    return textResponse(`${input}。出门看情况带把伞。`)
  }
  // 恢复路径：模型看见了**失败**的工具结果（isError: true）。
  // 上一课走到这里就只剩 default 分支——模型压根不知道刚才失败了，
  // 只会顺着自己的思路说下一句。本课它能看见失败，于是补上漏掉的参数重试。
  if (input.includes('必填项')) {
    return toolCallResponse('call-3-fix', 'calc', { a: 7, b: 6, op: '*' })
  }
  if (input.includes('刚才')) {
    // 只有模型能看见摘要时才答得上来；原始记录被 replace 顶掉之后就看不到了
    const summary = options.messages.find((message) => message.content.startsWith('（摘要）'))
    if (summary) return textResponse('你问了我北京天气、让我算 7*6，还打了个招呼。')
    return textResponse('我没有历史记忆，每次请求只带当前这一句。')
  }
  if (input.includes('北京')) {
    return toolCallResponse('call-1', 'get_weather', { city: '北京' })
  }
  if (input.includes('天气')) {
    return toolCallResponse('call-2', 'get_weather', { city: '北京' })
  }
  // 新增：模型"选"了另一个工具。它不需要认识 calc 的实现，
  // 只要注册表里有这个名字，loop 就能把它调起来。
  if (input.includes('算') || input.includes('+')) {
    // 注意这里**故意漏了 op**：模型不是永远正确的，漏参数是最常见的错。
    // 漏掉的参数会被第 11 课的校验器拦住，错误信息原样喂回给模型。
    return toolCallResponse('call-3', 'calc', { a: 7, b: 6 })
  }
  // 工具结果又喂回来了：算数结果是 "7 * 6 = 42" 这种形状。
  // 注意上面那句不能写成 includes('*')——那会把结果也当成"要算数"。
  if (/^[\d.]+\s*[-+*/]\s*[\d.]+\s*=/.test(input)) {
    return textResponse(`算好了：${input}`)
  }
  return textResponse(`我不知道怎么回答"${input}"，但我可以查天气、也会算数。`)
}

export function apply(ctx: Context) {
  ctx.plugin(MockAdapter, [decide])
}

import type { Context } from '@deepseek-ai/cordis'
import { Service } from '@deepseek-ai/cordis'
import Schema from '@deepseek-ai/schemastery'

declare module '@deepseek-ai/cordis' {
  interface Events {
    /**
     * 目录加载器扫完一个目录，往 cordis 里加了一批插件。
     * @param dir - 被扫描的目录（相对路径）。
     * @param count - 从这个目录里加载了几个插件。
     * @mode emit
     */
    'plugin-directory/loaded'(dir: string, count: number): void
  }
}

/** 一个目录里的插件清单。 */
export interface DirectoryManifest {
  /** 这个目录是干什么的，出现在启动日志里。 */
  readonly purpose: string
  /** 插件文件列表，相对本目录。 */
  readonly plugins: readonly string[]
}

/** 插件配置：加载哪个目录。 */
export interface Config {
  /** 目录路径，相对 cordis.yml 所在位置。 */
  root: string
}

/** 同名 schema 给 Cordis 看：运行前验证，缺的补默认值。 */
export const Config: Schema<Config> = Schema.object({
  root: Schema.string().default('.'),
})

/**
 * 目录加载器：扫一个文件夹，把里面的插件一个个递给 cordis。
 *
 * 本课的主题。`ctx.loader.create()` 一次只认一个文件，
 * 而一个能力（比如"工具"）通常长在一个文件夹里。
 * 这个 Service 把"文件夹"变成加载单位。
 */
export abstract class PluginDirectory extends Service {
  constructor(ctx: Context) { super(ctx, 'pluginDirectory') }

  /**
   * 加载一个目录。
   * @param dir - 目录路径，相对 cordis.yml 所在位置。
   * @returns 从这个目录里加载了几个插件。
   */
  abstract load(dir: string): Promise<number>
}

/**
 * Service Provider：读 manifest.ts，逐个 ctx.loader.create。
 *
 * 为什么不直接 `readdirSync` 扫文件？因为**显式清单比目录扫描安全**：
 * 一个 `_backup.ts`、一个临时 `test.ts` 都会被扫进来，而它们可能
 * 不是插件，或者是不该现在加载的插件。harness 真身的
 * packages/ 也是靠 package.json 的 exports 声明，不是扫文件名。
 */
export class MapPluginDirectory extends PluginDirectory {
  async load(dir: string): Promise<number> {
    const manifestUrl = new URL(`${dir.replace(/\/$/, '')}/manifest.js`, this.ctx.baseUrl)
    const manifest = (await import((globalThis as any).__DSH_MANIFEST__ ?? manifestUrl.href)) as { default: DirectoryManifest }

    let count = 0
    for (const plugin of manifest.default.plugins) {
      const url = new URL(`${dir.replace(/\/$/, '')}/${plugin.replace(/\.ts$/, '.js')}`, this.ctx.baseUrl)
      await this.ctx.loader.create({ name: url.href })
      count += 1
    }

    this.ctx.emit('plugin-directory/loaded', dir, count)
    return count
  }

  /**
   * 插件启动钩子：本 fiber 激活后才跑，此时服务已经能从 ctx 上取到。
   *
   * 为什么不在 `apply()` 里直接 `await ctx.pluginDirectory.load()`？
   * 因为 `ctx.plugin(X)` 只是**登记**了服务，要等这个插件的 fiber
   * 真正激活（ACTIVE）之后，`ctx.pluginDirectory` 才取得出来。
   * 在 apply 里伸手，只会拿到
   * `cannot get property "pluginDirectory" without inject`。
   *
   * 这个钩子的调用时机正好：apply 跑完、fiber 就绪。
   */
  async *[Service.init]() {
    yield () => {}
    await this.load(this.#root)
  }

  /** 要加载的目录，由 apply 从配置里写进来。 */
  #root = '.'

  /** 记录要加载的目录。 */
  setRoot(root: string) {
    this.#root = root
  }
}

/**
 * 应用入口：登记服务，把配置里的目录记下来。
 *
 * 真正的加载发生在 `[Service.init]` 钩子里——那时本插件的 fiber 已激活，
 * `ctx.pluginDirectory` 取得出来，而且能安全地往 loader 里添新条目。
 */
export function apply(ctx: Context, config: Config) {
  ctx.plugin(MapPluginDirectory)
  ctx.reflect.get('pluginDirectory', false)?.setRoot(config.root)
}

import type { Context } from '@deepseek-ai/cordis'
import { Tools, type ToolSchema } from './tools.ts'
import type { ToolArgs, ToolDefinition, ToolResult } from './define-tool.ts'

export const name = 'tools-registry'

/**
 * Service Provider：一个基于 Map 的工具注册表。
 *
 * register() 是第 02 课的"注册即效果"：注册方插件一卸载，
 * 这个工具定义自动从表里消失。
 */
class MapTools extends Tools {
  private readonly definitions = new Map<string, ToolDefinition>()
  private counter = 0

  register(definition: ToolDefinition): () => void {
    // ctx.effect 是"本插件卸载时自动执行"的注册点
    return this.ctx.effect(() => {
      this.definitions.set(definition.name, definition)
      // 注册即广播：谁想知道"现在有哪些工具"，挂这个事件就行
      this.ctx.emit('tools/change')
      return () => {
        this.definitions.delete(definition.name)
        this.ctx.emit('tools/change')
      }
    }, `tools.register(${definition.name})`)
  }

  get(name: string): ToolDefinition | undefined {
    return this.definitions.get(name)
  }

  list(): ToolDefinition[] {
    return [...this.definitions.values()]
  }

  schemas(): ToolSchema[] {
    // 只挑三个字段——execute 留在本地，不随请求出门
    return [...this.definitions.values()].map(({ name, description, parameters }) => ({
      name,
      description,
      parameters,
    }))
  }

  async call(name: string, args: unknown, signal?: AbortSignal): Promise<ToolResult> {
    const definition = this.definitions.get(name)
    const callId = `call-${++this.counter}`
    if (!definition) {
      return { ok: false, callId, name, error: `工具不存在：${name}` }
    }
    try {
      // 先看调用方是不是已经到点了。真身里这一步由 timeout-policy 的
      // 包装器做——它把 exec.signal 换成自己的期限，工具只需要
      // honor 传进来的 signal，不需要知道期限是谁定的。
      if (signal?.aborted) {
        return { ok: false, callId, name, error: '调用已取消' }
      }
      const value = await definition.execute((args ?? {}) as ToolArgs, { callId, signal })
      // execute 回来了，但调用方可能已经等不下去走了。
      // 一个 honor signal 的工具会在 abort 时尽快抛出/返回，
      // 但**不保证**——所以这里再查一次，宁可丢弃结果也不假装成功。
      if (signal?.aborted) {
        return { ok: false, callId, name, error: '调用已取消' }
      }
      return { ok: true, callId, name, value }
    } catch (error) {
      // abort 导致的异常也是失败，不是 bug：换个说法，别把 stack 摔用户脸上
      if (signal?.aborted) {
        return { ok: false, callId, name, error: '调用已取消' }
      }
      return { ok: false, callId, name, error: error instanceof Error ? error.message : String(error) }
    }
  }
}

export function apply(ctx: Context) {
  ctx.plugin(MapTools)
}

import { Service, type Context } from '@deepseek-ai/cordis'
import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

/**
 * 一条会话记录。`data` 的形状由 `type` 决定。
 *
 * harness 真身里这是 `SessionEventMap`（packages/core/session/src/types.ts 第 281 行），
 * 同样是"一个 type 对应一种 data"的表。
 */
export interface SessionRecordMap {
  /** 用户说了一句话。 */
  'user/message': { content: string }
  /** 模型回答了一轮。 */
  'assistant/message': { text: string }
  /** 模型请求调用一个工具，arguments 是它吐出的原始 JSON 字符串。 */
  'tool/call': { callId: string; name: string; arguments: string }
  /** 工具执行完了，value 是返回值，isError 标记成功失败。 */
  'tool/result': { callId: string; name: string; value: unknown; isError: boolean }
  /** 一条旁白：循环写给自己的提醒，模型看不见。 */
  'notice/message': { text: string }
}

/** 任意一种会话记录。 */
export type SessionRecord =
  | { [K in keyof SessionRecordMap]: { type: K; data: SessionRecordMap[K] } }[keyof SessionRecordMap]

/**
 * 会产生模型可见消息的记录类型。
 *
 * 日志里还有别的行（turn 边界、失败尝试），它们不进模型请求，
 * 只是排查问题时看的痕迹。harness 真身叫 `SurfaceEventType`
 * （packages/core/session/src/types.ts 第 439 行）。
 */
export type SurfaceRecordType = 'user/message' | 'assistant/message' | 'tool/result'

/** 一条记录在"模型能看到的历史"里的落点。 */
export type SurfaceOp =
  /** 追加到末尾：正常路径。 */
  | 'append'
  /** 替换一段已有节点：压缩上下文时用，被替换的行在日志里还在，只是不再进模型请求。 */
  | { op: 'replace'; startSeq: number; endSeq: number }

/**
 * 落盘的一行。
 *
 * 这是判别联合：`switch (line.type)` 会收窄 `line.data` 的类型，
 * 不用写任何断言。写法照抄 harness 真身的 `SessionEvent`
 * （packages/core/session/src/types.ts 第 493 行）——
 * `{ [K in ...]: {...} }[T]` 这层映射就是为了让联合生效。
 */
export type SessionLine = {
  [K in keyof SessionRecordMap]: {
    /** 会话内单调递增的序号，从 1 开始。 */
    readonly seq: number
    /** 写入时刻，Unix 毫秒。 */
    readonly time: number
    readonly type: K
    readonly data: SessionRecordMap[K]
    /** 它怎么进入模型可见历史。只有会产生消息的行带这个字段。 */
    readonly surfaceOp?: K extends SurfaceRecordType ? SurfaceOp : never
  }
}[keyof SessionRecordMap]

declare module '@deepseek-ai/cordis' {
  interface Context { session: Session }
}

/** 一条喂给模型的请求消息。 */
export interface ChatMessage {
  readonly role: 'user' | 'assistant' | 'tool'
  readonly content: string
}

/**
 * Service Definition：把"发生过的事"写进一条只增不减的日志。
 *
 * 这是 harness 的**唯一事实来源**。第 12 课的 agent loop 只在内存里跑，
 * 进程一退全忘了；有了它，任何时候都能把对话重放出来。
 */
export abstract class Session extends Service {
  constructor(ctx: Context) { super(ctx, 'session') }

  /**
   * 追加一条记录。
   * @param record - 记录内容。
   * @param op - 它怎么进入模型可见历史，默认 `'append'`。
   * @returns 分配到的序号。
   */
  abstract append(record: SessionRecord, op?: SurfaceOp): number

  /** 目前为止的全部记录，按 seq 升序。 */
  abstract list(): readonly SessionLine[]

  /**
   * 把日志折叠成模型能看的历史。
   *
   * 只走会产生消息的行；`replace` 标记的行会顶掉它覆盖的那一段。
   * 这就是 harness 的 `deriveMessages()`——每次请求前都重新折一遍，
   * 所以日志和模型看到的东西永远一致。
   */
  abstract deriveMessages(): ChatMessage[]

  /** 磁盘上已经有多少条记录——恢复来的，还是新起的。 */
  abstract readonly restoredCount: number

  /**
   * 从磁盘读回一个 session 的全部记录。
   *
   * 第一行是头行（`type: 'session'`），记录格式版本；剩下的是记录行。
   * 版本对不上直接抛错——**拒绝加载比猜着加载安全**。
   * @param file - session.jsonl 的路径。
   * @returns 按 seq 升序的记录。
   */
  static load(file: string): readonly SessionLine[] {
    const text = readFileSync(file, 'utf8')
    const lines = text.split('\n')
      .filter((line) => line.length > 0)
      .map((line) => JSON.parse(line) as SessionFileLine)
    const [header, ...rest] = lines
    if (header.type !== 'session') {
      throw new Error(`session 文件第一行必须是头行，实际是 ${String(header.type)}`)
    }
    if (header.version !== SESSION_FORMAT_VERSION) {
      throw new Error(
        `session 格式版本不匹配：文件是 v${header.version}，本程序只会 v${SESSION_FORMAT_VERSION}`,
      )
    }
    // 剩下的都是记录行；头行在上面已经核对掉了
    return rest.filter(isSessionLine)
  }
}

/** 头行不是记录。 */
function isSessionLine(line: SessionFileLine): line is SessionLine {
  return line.type !== 'session'
}

/**
 * 落盘文件的一行：要么是头行，要么是一条记录。
 *
 * 头行不是记录——它没有 `seq`，只说明"这个文件是什么格式的"。
 * harness 真身在 packages/session/session-persistence-jsonl/src/format.ts
 * 里也叫 `HeaderLine`，`type` 字段值是 `'session'`。
 */
export type SessionFileLine =
  | { type: 'session'; version: number }
  | SessionLine

/** 当前会话日志的格式版本。harness 真身是 `SESSION_FORMAT_VERSION = 4`。 */
export const SESSION_FORMAT_VERSION = 1

/**
 * Service Provider：JSONL 落地。
 *
 * 每行一条 JSON，追加写文件。harness 真身（packages/session/session-persistence-jsonl）
 * 用 zstd 压缩、分代文件名和原子替换，我们保留最核心的那个决定：
 * **append-only，写出去的行永不改写**。
 */
export class JsonlSession extends Session {
  private seq = 0
  private readonly records: SessionLine[] = []
  private readonly file: string
  /** 磁盘上已有多少条记录——恢复来的，还是新起的。 */
  readonly restoredCount: number

  constructor(ctx: Context, config: { file: string }) {
    super(ctx)
    this.file = join(config.file, 'session.jsonl')
    mkdirSync(dirname(this.file), { recursive: true })

    // 恢复：接着磁盘上已有的行往下写，seq 继续往上加
    if (existsSync(this.file)) {
      const existing = Session.load(this.file)
      this.records.push(...existing)
      this.seq = existing.at(-1)?.seq ?? 0
      this.restoredCount = existing.length
    } else {
      this.restoredCount = 0
      // 新文件第一行写头行：以后谁来读这个文件，先核对版本
      appendFileSync(this.file, `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`)
    }
  }

  append(record: SessionRecord, op: SurfaceOp = 'append'): number {
    this.seq += 1
    const line = this.toLine(this.seq, record, op)
    this.records.push(line)
    // 追加写：只往文件末尾加字节，不动已有内容
    appendFileSync(this.file, `${JSON.stringify(line)}\n`)
    return line.seq
  }

  /** 拼一行。`tool/call` 不进模型可见历史——它已经被同一轮的 assistant/message 代表了。 */
  private toLine(seq: number, record: SessionRecord, op: SurfaceOp): SessionLine {
    const time = Date.now()
    switch (record.type) {
      case 'user/message':
        return { seq, time, type: 'user/message', data: record.data, surfaceOp: op }
      case 'assistant/message':
        return { seq, time, type: 'assistant/message', data: record.data, surfaceOp: op }
      case 'tool/result':
        return { seq, time, type: 'tool/result', data: record.data, surfaceOp: op }
      case 'tool/call':
        return { seq, time, type: 'tool/call', data: record.data }
      case 'notice/message':
        return { seq, time, type: 'notice/message', data: record.data }
    }
  }

  list(): readonly SessionLine[] { return this.records }

  /**
   * 折叠日志。
   *
   * `surface` 是一个"模型能看到哪些 seq"的有序列表。
   * 追加就 push；替换就把 [startSeq, endSeq] 那段挖掉、换成新行。
   * 被挖掉的行在日志里一行不少，只是不再进模型请求。
   */
  deriveMessages(): ChatMessage[] {
    const surface: SessionLine[] = []
    for (const line of this.records) {
      const op = line.surfaceOp
      if (op === undefined) continue          // 非消息行：跳过
      if (op === 'append') { surface.push(line); continue }
      // replace：挖掉旧段，在原来的位置插入新行
      const start = surface.findIndex((node) => node.seq === op.startSeq)
      const end = surface.findIndex((node) => node.seq === op.endSeq)
      if (start === -1 || end === -1) continue
      surface.splice(start, end - start + 1, line)
    }
    return surface.map(toChatMessage)
  }

  /**
   * 把整个文件重写一遍。
   *
   * 注意头行得带上——它是文件的一部分，不是记录。
   * 这是本文件里唯一一处"整份重写"的路径，正常写入走的是 append。
   */
  flush(): void {
    const header = `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`
    const body = this.records.map((line) => `${JSON.stringify(line)}\n`).join('')
    writeFileSync(this.file, header + body)
  }
}

/** 把一条消息行翻译成模型请求里的消息。 */
function toChatMessage(line: SessionLine): ChatMessage {
  switch (line.type) {
    case 'user/message':
      return { role: 'user', content: line.data.content }
    case 'assistant/message':
      return { role: 'assistant', content: line.data.text }
    case 'tool/result':
      return { role: 'tool', content: String(line.data.value) }
    case 'tool/call':
      // 走不到这里：tool/call 没有 surfaceOp，deriveMessages 已经把它过滤掉了
      return { role: 'assistant', content: `${line.data.name}(${line.data.arguments})` }
    case 'notice/message':
      // 走不到这里：旁白没有 surfaceOp，deriveMessages 已经把它过滤掉了
      return { role: 'assistant', content: line.data.text }
  }
}

