/**
 * 一次工具调用的时限，毫秒。
 *
 * 真身是 guard/timeout-policy：每个工具自己声明 `timeoutMs`，
 * 包装器 armed 这个期限，到点把 signal abort 掉，再把结果替换成
 * 一条结构化的 TOOL_TIMEOUT。教学版没法让假工具挂住，所以用
 * 一个统一的常量——但它演示的是同一件事：**等待必须有上限。**
 */
const TOOL_TIMEOUT_MS = 500

/**
 * 重复调用多少次算"没有进展"。
 *
 * 真身 repeat-tool-reminder 的默认阈值是 [3, 5, 8]：第一次温柔提醒，
 * 后面逐步升级到带工具名和参数详情的警告。教学版取 3，
 * 而且只演示"到阈值就提醒"这一档。
 */
const REPEAT_THRESHOLD = 3

/** 失败后最多再让模型试几次。递归没有头就会绕到天荒地老。 */
const MAX_RECOVERY_DEPTH = 2

/**
 * 上下文窗口，token。
 *
 * 真身里这是 adapter 的能力（`ctx.llm.resolveModelInfo().context.contextWindow`），
 * 每个模型自己声明。教学版的假模型没有这个字段，就摆一个常量——
 * 关键是**它是配置，不是算式里的魔法数**：换成 128k 只要改这一行。
 *
 * 这里摆 320 而不是 131072，是因为本课的剧本只有四轮，
 * 按真实窗口算到天荒地老也压不了一次——那样"预算告急"这条路
 * 在输出里根本看不见。缩小 400 倍，阈值 256 落在第四轮头上
 * （前三轮 163 / 197 / 246），正好只压一次。
 */
const CONTEXT_WINDOW = 320

/**
 * 压力阈值：请求估算超过窗口的这个比例就触发压缩。
 *
 * 真身 compaction-basic 的 `thresholdRatio` 默认 0.8——
 * 不等到塞满，留 20% 给回答和抖动。320 × 0.8 = 256。
 */
const THRESHOLD_RATIO = 0.8

/**
 * 保留窗口：压缩时原样留下最近这么多 token 的对话。
 *
 * 真身叫 `retainTokens`（或按 `retainRatio` 折算）。为什么必须留？
 * 因为**最近几句几乎必然和当前这轮有关**，折成摘要反而丢细节。
 * 默认 0.16——窗口的 16%，这里折算成 40 是为了让本课的剧本
 * 真的压上一次、看得见效果。
 */
const RETAIN_TOKENS = 40

/**
 * 摘要请求自己的输出上限，token。
 *
 * 真身 compaction-basic 的 `summarizationMaxTokens`。注意它是
 * **单独一项配置**，不跟着主请求的 maxTokens 走——摘要要的是
 * "够用就好"，写长了反而压不下预算。
 */
const SUMMARY_MAX_TOKENS = 128

/** 摘要正文的开闭标签。真身是 `<compacted-summary>`。 */
const SUMMARY_OPEN_TAG = '<summary>'
const SUMMARY_CLOSE_TAG = '</summary>'

/**
 * 压缩指令：作为最后一条 user 消息追加在被折历史后面。
 *
 * 真身叫 `COMPACTION_INSTRUCTION`，是一段七段式 Markdown 模板
 * （Primary Request and Intent / Key Technical Concepts / Files and Code /
 * Errors and Fixes / Pending Jobs / Current Work / Next Step /
 * Critical Context）。教学版缩成四段——**结构本身才是重点**：
 * 分段逼模型分门别类地回忆，不分段它就吐一段流水账，
 * 而流水账里"用户最初要什么"和"刚才在试什么"是混在一起的。
 *
 * 注意它是**消息**，不是 system prompt：追加在被折历史的末尾，
 * 让 provider 的 KV cache 还能命中前面那段前缀。
 */
const COMPACTION_INSTRUCTION = [
  'You are a compaction engine. Condense the conversation ABOVE into a checkpoint that lets another model resume the work with no loss of essential context.',
  '',
  'Output EXACTLY the structure below, and wrap it in <summary> ... </summary> tags:',
  '',
  '## Primary Request and Intent',
  '- [用户最初的目标，以及它有没有变过]',
  '',
  '## Current Work',
  '- [此刻进行到哪一步，最近一次交互是什么]',
  '',
  '## Next Step',
  '- [接下来该做的那一件事]',
  '',
  'Rules: 用中文写要点，不要写段落。保留确切的文件路径、命令、错误字符串和数字。不要提"这是一次压缩"，也不要调用任何工具。',
].join('\n')

/**
 * 落盘关卡的触发点。
 *
 * 真身是 `session-checkpoint-policy`，三处 await `session/flush`：
 * `llm/stream`（流构造前）、`tools/execute`（顶层工具 body 前）、
 * `agent/pre-step`。三处的共同理由：**危险动作发生之前，
 * 日志必须先已经在盘上**。请求发出去、工具跑起来，进程随时
 * 可能死；死了之后能拿来还原现场的只有盘上的东西。
 *
 * 教学版只挑最要紧的一处：模型请求发出之前。工具的假执行
 * 是同步返回的，放在那里只会刷屏。
 */
const FLUSH_BEFORE_REQUEST = true

/**
 * 系统提示。
 *
 * 26 课及之前，`measureRequest()` 里的 `systemTokens` 恒 0——
 * 账本上一直有这一项，从来没有人往里写过一个字。本课第一次
 * 真的有系统提示：**它不是一条消息，是请求体上一个独立的
 * 顶层字段**（见 real-provider.ts 的 `WireRequest.system`）。
 *
 * 真身这里是一整套（角色卡、工具使用规范、环境信息），而且
 * 按模型的 `systemPromptUpdate` 策略决定要不要进历史。
 * 教学版只写一句，够说明"它不在 messages 里"这件事。
 */
const SYSTEM_PROMPT = [
  '你是 deepseek-harness 教学版的助手，用中文回答。',
  '需要外部数据时调用工具，不要编造。',
].join('\n')

/**
 * 一轮对话里模型给出的指令：要么说话，要么调工具。
 */
type ModelTurn =
  | { kind: 'text'; text: string }
  | { kind: 'tool-call'; id: string; name: string; args: Record<string, unknown> }

/**
 * Consumer：agent loop 的第十版。
 *
 * 前四版跑完就忘。第五版补上**能力协商**：这个插件声明了自己要
 * `llm`、`tools`、`session`、`tokenMeter` 四项能力，cordis 就替我们
 * 盯着它们。第六版的主题是**流式**：每收到一片 text-delta 就立刻
 * 打到屏幕上。第七版的主题是**错误恢复**：工具失败了，这一轮不能
 * 就这么散了。第八版的主题是**让模型自己写摘要**。第九版的主题是
 * **看见 session 的一生**。
 *
 * 本版（第十版）的主题是**接真 API**。而这一版最反直觉的地方是：
 * **本文件几乎没改**。改了的是 `llm.ts`（多了两个字段）、
 * `real-provider.ts`（新文件）、`session.ts`（callId 透传）和
 * `token-meter.ts`（导出两个常量）——Consumer 这边只多了
 * system/tools 的透传和一次 usage 分账。
 *
 * 这正是第 01 课那个 capability seam 的意义：Provider 从 if 换成
 * HTTP，Consumer 不知道。
 */
export function apply(ctx: Context) {
  ctx.on('agent/turn', (input) => { void run(input) })
  ctx.on('agent/compact', (fromSeq, toSeq, summary) => { compact(fromSeq, toSeq, summary) })

  // 本课新增：听 session 的一生。四条事件各管一个阶段，
  // 合起来就是"一个会话从问世到入土"的完整轨迹。
  //
  // 注意这里读的还是 `restoredCount`，不是等 `session/created`
  // 送过来——因为 **provider 先加载、我们后加载**（inject 的
  // 拓扑序），session 问世时我们还没出生，那条事件听不到。
  // 这是 cordis 的一个通用事实：**监听只能从现在开始，之前
  // 发生的事要靠别的方式补**。
  let events = 0
  ctx.on('session/created', (_session, restored) => {
    // 本课的剧本里这条走不到：agent 比 session 晚加载。
    // 留着它是为了让"为什么听不到"这件事有地方对照。
    console.log(`[session 一生] 问世（恢复 ${restored} 条）`)
  })
  ctx.on('session/event', (_session, line) => {
    events += 1
    console.log(`[session 一生] #${line.seq} ${line.type} 落定（累计 ${events} 条）`)
  })
  ctx.on('session/flush', async () => {
    // 这是 await 型事件：监听器返回的 Promise 会被
    // ctx.parallel 一起等完。所以这里"打一行字"这件事
    // 是真的会拖慢调用方的——不能在里面干重活。
    console.log('[session 一生] 落盘关卡：日志已全部在盘上')
  })
  ctx.on('session/disposed', (_session) => {
    console.log(`[session 一生] 入土（一生共 ${events} 条记录）`)
  })

  // 区间锁：25 课声明了这两条事件却没有任何人听，本课补上。
  //
  // 真身在 begin 和 end 两端各挂一个断言：
  // `assertSelectedSpanStable`（摘要生成期间，选中的区间
  // 一条都不许动）和 `assertWholeSurfaceUnchanged`（除了
  // 摘要那一行，别的地方也不许动）。教学版的循环是串行
  // await 的，期间确实没有别人能插进来——所以这两条
  // 事件现在是**纯观测**。但监听它们的位置，就是真身
  // 放不变量检查的位置：看得见。
  ctx.on('agent/compact-begin', (fromSeq, toSeq) => {
    console.log(`[区间锁] #${fromSeq}~#${toSeq} 冻结，开始生成摘要`)
  })
  ctx.on('agent/compact-end', (fromSeq, toSeq, summarySeq) => {
    console.log(`[区间锁] 解冻：区间收成 #${summarySeq}，#${fromSeq}~#${toSeq} 就此退出模型视野`)
  })

  // 收尾：进程要退了，把 session 埋了。
  //
  // 为什么用 `ctx.effect` 而不是 `ctx.on('dispose')`？因为 cordis
  // 没有 `'dispose'` 这个事件——清理的钩子是 `ctx.effect(() => () => ...)`
  // 的**返回值**：插件卸载时它逆序执行。这就是第 02 课的
  // "注册即效果"：注册一个动作，同时注册它的撤销。
  //
  // 顺序上它一定跑在 session 服务被拆之前吗？不一定。cordis 按
  // 反序卸载 fiber，而 agent 比 session 晚加载，所以 agent 的
  // effect 先跑——**在本课的这个配置下**成立。真身不需要操心
  // 这个：SessionStore 自己管生命周期，`session/disposed` 由
  // store 在会话离开时广播，不劳别人。
  ctx.effect(() => () => { ctx.session.dispose() }, 'session.dispose')

  // 启动第一件事：报告从磁盘恢复了什么
  const restored = ctx.session.restoredCount
  if (restored > 0) {
    console.log(`=== 从磁盘恢复了 ${restored} 条记录，seq 接着 #${ctx.session.list().at(-1)?.seq ?? 0} 往下编 ===`)
    console.log('=== 模型看到的历史 ===')
    for (const message of ctx.session.deriveMessages()) {
      console.log(`[${message.role}] ${message.content}`)
    }
  } else {
    console.log('=== 没有找到历史，开一个新会话 ===')
  }

  /**
   * 三轮对话，串行不并行。
   *
   * 第七课这里是三个 setTimeout，间隔 50ms——因为那一轮的
   * 模型是"瞬间吐完"的，50ms 足够跑完一整轮。
   * 第七课不行了：**一轮现在要花几百毫秒**（几十片 × 60ms），
   * 50ms 后第二轮就会插进来，屏幕上三行字互相穿插，
   * 日志的 seq 也会因为两个 run 同时 append 而错乱。
   *
   * 所以改成 await 一个、再 await 下一个。
   * 这不是"流式特有的麻烦"，而是**任何异步流水线的通用纪律**：
   * 只要一步变慢了，原本靠"猜时间"排的队就会撞车。
   * 真正的排队方式是等前一个真的做完。
   */
  void (async () => {
    if (restored > 0) {
      await run('刚才我问了什么？')
    } else {
      await run('北京天气怎么样？')
      await run('帮我算 7*6')
      await run('你好')
      // 三轮下来日志已经 12 条，而第四轮"你好"会把预算推过阈值——
      // 它一开始 compactIfNeeded 就会自动折一次，这里不手写了。
      // 23 课那句写死的 compact() 删掉：它折的 #1~#12 已经被自动压缩
      // 覆盖，再折一次 endSeq 落空，压缩会被静默跳过。
    }
    reportCapabilities()
    replay()

    // 落幕：把这个会话埋了。
    //
    // 为什么显式调用，而不是等插件卸载？卸载的时机不由我们定，
    // 而且 fiber 一拆，挂在它上面的监听器跟着被摘掉——
    // `session/disposed` 可能刚发出来就已经没人听了。
    // 显式调用完全确定：发事件的这一刻，听事件的那四条
    // 监听器全都活着。
    //
    // `ctx.effect` 里那个清理钩子仍然留着：它管的是**另一种**
    // 收场——插件被卸载（真身的 store 关会话走的就是这条）。
    // 两条路都通向 dispose()，所以它必须幂等：
    // 第二次调用什么都不做。
    ctx.session.dispose()
  })()

  /**
   * 工具清单：等注册表通知，不自己猜时机。
   *
   * 为什么不能在 apply 函数体里直接 `ctx.tools.schemas()`？因为 cordis 按
   * **依赖拓扑**排插件的加载顺序：agent 声明了 `inject: ['llm','tools','session','tokenMeter']`，
   * 它要的服务必须先把 provider 建好，所以 agent 的 apply 排在 provider
   * 之后、**但排在 weather-tool / calc-tool 之前**——后两者只 inject 了
   * `tools`，拓扑上没人催它们，就按 cordis.yml 的顺序落到最后。
   *
   * 也就是说：apply 函数体执行的那一刻，注册表**恰好是空的**。
   * 而这个顺序由依赖关系决定，写 yml 的人控制不了。
   * 所以"现在有哪些工具"这件事，只能等注册表通知，不能自己数。
   *
   * 那为什么还要 `setTimeout` 包一层？因为插件是一个个加载的，
   * weather-tool 注册时会响一次，calc-tool 注册时又响一次。
   * 每次响都打印，就会打出两份不完整的清单。
   * 所以：**每次变化只重新排一次打印，等本轮事件循环安静下来再打**。
   */
  let scheduled = false
  ctx.on('tools/change', () => {
    if (scheduled) return
    scheduled = true
    setTimeout(printTools, 0)
  })

  function printTools() {
    console.log('=== 模型能选的工具 ===')
    for (const schema of ctx.tools.schemas()) {
      console.log(`- ${schema.name}：${schema.description}`)
    }
  }

  /**
   * 对账：我声明要的能力，注册表现在真的都有了吗？
   *
   * 这就是第 20 课的主题。`ctx.fiber.inject` 是本插件声明的那张需求表，
   * `ctx.reflect.props` 是全应用登记过的服务名册。
   * 两边一减，缺谁一目了然——而且是在**启动阶段**减，不是等
   * 某次调用踩空了才炸。
   *
   * 注意它读的是 `props`（登记册），不是 `store`（实例）。
   * 登记册里有名字，不代表现在有实例——第 19 课的工具就是
   * 先登记、后注册的。缺名字才是真缺。
   */
  function reportCapabilities() {
    console.log('\n=== 能力对账 ===')
    for (const service of Object.keys(ctx.fiber.inject)) {
      const registered = Object.hasOwn(ctx.reflect.props, service)
      const status = registered ? '齐' : '缺'
      console.log(`- ${service}：${status}`)
      if (!registered) {
        console.log(`  没人提供 ${service}——cordis.yml 里少了一个 provider，或者它自己加载失败了`)
      }
    }
  }

  async function run(input: string) {
    console.log(`\n=== 用户说：${input} ===`)
    ctx.session.append({ type: 'user/message', data: { content: input } })

    // 关键一行：messages 不是手搓的，是从日志折出来的。
    // 它每轮都要重新折一次——历史随时可能在压缩中变短。
    //
    // 27 课新增两样**不在 messages 里**的东西：system 和 tools。
    // 它们每轮都一样，但每轮都要发——清单是请求的一部分，
    // 压不掉也得算钱（见 toolsTokens）。
    const options: GenerateOptions = {
      messages: ctx.session.deriveMessages(),
      system: SYSTEM_PROMPT,
      tools: ctx.tools.schemas(),
    }

    // 第七课新增：发出请求之前，先算一次账。
    // 注意顺序——**先折、再量、后问**。预算永远基于
    // 这一轮真正要发出去的那个 messages，不是历史总量。
    await compactIfNeeded(options)
    measureRequest(options)

    // 本课新增：请求出门之前，先让日志落盘。
    //
    // 真身 checkpoint-policy 把这个动作做成**策略插件**，
    // 在 llm/stream 构造前 await `session/flush`——agent loop
    // 自己一行都不写。教学版直接调 `ctx.session.flush()`，
    // 效果一样：`session/flush` 事件被 parallel 出去，
    // 所有监听器做完，请求才发。
    //
    // 为什么非做不可？请求一离开进程，我们就把控制权交出去了：
    // 网络可能断，进程可能被杀，机器可能断电。**能证明
    // "我们问过什么"的，只有盘上那条日志。**
    if (FLUSH_BEFORE_REQUEST) {
      ctx.session.flush()
    }

    const turn = await stream(ctx, options)

    switch (turn.kind) {
      case 'text':
        // 正文连标签一起在 stream() 里打完了，这里只写日志。
        // 第六课是 `console.log('[模型回答] ' + turn.text)` 整句一次打完；
        // 流式之后**不能再打一遍正文**——用户会看到同一个句子出现两次。
        ctx.session.append({ type: 'assistant/message', data: { text: turn.text } })
        break

      case 'tool-call': {
        console.log(`[模型决定] 调用 ${turn.name}，参数 ${JSON.stringify(turn.args)}`)
        // 注意：arguments 存的是模型吐出的**原始字符串**，不是我们 parse 后的对象
        ctx.session.append({
          type: 'tool/call',
          data: { callId: turn.id, name: turn.name, arguments: JSON.stringify(turn.args) },
        })
        await executeTool(turn)
        break
      }
    }
  }

  /**
   * 执行一次工具调用，失败后**把失败喂回模型**。
   *
   * 第七课这里是个 if/else：成功就问一次模型，失败就打印+记日志，
   * 然后 run() 返回——这一轮就这么结束了，模型一个字都不知道。
   * 第七课补上另一半：**失败也是一次结果，模型有权看见它、换一个办法。**
   *
   * 这是真身 `packages/guard` 想解决的问题。`repeat-tool-reminder` 盯着
   * "模型用一模一样的参数反复调同一个工具"，`timeout-policy` 给工具
   * 装上时限。两件事的共同前提是：**失败必须回到对话里**，否则
   * 模型只会一遍遍重复同一个动作——它看不见别的东西。
   */
  async function executeTool(call: Extract<ModelTurn, { kind: 'tool-call' }>, depth = 0) {
    // 超时：给工具一个上限。真身是 guard/timeout-policy，工具自己声明
    // timeoutMs、honor exec.signal；教学版简化成统一的超时常量，
    // 用 AbortController 把"到点了"变成一个 signal。
    const abort = new AbortController()
    const timer = setTimeout(() => { abort.abort() }, TOOL_TIMEOUT_MS)
    let result: ToolResult
    try {
      result = await ctx.tools.call(call.name, call.args, abort.signal)
    } catch (error) {
      // 工具直接抛异常（不是返回失败）：第 19 课的注册表只兜 execute 里的错，
      // 这里兜的是"连注册表都没走完"的错。一样当失败处理，不能让它炸掉 loop。
      result = { ok: false, callId: call.id, name: call.name, error: describeError(error) }
    } finally {
      clearTimeout(timer)
    }

    if (result.ok) {
      console.log(`[工具返回] ${String(result.value)}`)
      ctx.session.append({
        type: 'tool/result',
        data: { callId: result.callId, name: result.name, value: result.value, isError: false },
      })

      // 工具结果有了，再问模型一次，让它说人话——这次它看得见刚才的调用和返回。
      // 第七课起，这些追问也走 compactIfNeeded：**模型每被问一次，就是一次请求。**
      const follow: GenerateOptions = {
        messages: ctx.session.deriveMessages(),
        system: SYSTEM_PROMPT,
        tools: ctx.tools.schemas(),
      }
      await compactIfNeeded(follow)
      if (FLUSH_BEFORE_REQUEST) {
        ctx.session.flush()
      }
      const turn = await stream(ctx, follow)
      if (turn.kind === 'text') {
        ctx.session.append({ type: 'assistant/message', data: { text: turn.text } })
      }
      return
    }

    // 失败路径：先看见，再判断要不要提醒，最后把话筒还给模型
    console.log(`[工具失败] ${result.error}`)
    ctx.session.append({
      type: 'tool/result',
      data: { callId: result.callId, name: result.name, value: result.error, isError: true },
    })

    // 重复检测：同样的工具+同样的参数，连续第几次了？
    const repeats = observeRepeat(call.name, JSON.stringify(call.args))
    if (repeats >= REPEAT_THRESHOLD) {
      // 这不是一条"给模型看的结果"，是一条**旁白**：提醒它换个办法。
      // 真身叫 additionalContexts，带 source 标签，渲染时不会冒充用户说的话。
      const notice = `你已经用同样的参数连续调了 ${repeats} 次 ${call.name}，这没有进展。换个工具、换些参数，或者直接告诉用户你做不到。`
      console.log(`[循环提醒] ${notice}`)
      ctx.session.append({ type: 'notice/message', data: { text: notice } })
    }

    // 失败之后也问一次模型。它看得见刚才的 tool/result（isError: true），
    // 有机会换一个工具、换一组参数，或者老实说"这个我办不到"。
    // **不问的话，这一轮就白失败了**——日志里多一行，对话里什么都没发生。
    const followUp: GenerateOptions = {
      messages: ctx.session.deriveMessages(),
      system: SYSTEM_PROMPT,
      tools: ctx.tools.schemas(),
    }
    await compactIfNeeded(followUp)
    if (FLUSH_BEFORE_REQUEST) {
      ctx.session.flush()
    }
    const recovery = await stream(ctx, followUp)
    switch (recovery.kind) {
      case 'text':
        ctx.session.append({ type: 'assistant/message', data: { text: recovery.text } })
        break
      case 'tool-call': {
        // 模型换了个办法。递归要有个头——超过重试上限就收手，
        // 否则一个坏工具能让它绕到天荒地老。
        if (depth >= MAX_RECOVERY_DEPTH) {
          console.log(`[放弃恢复] 已经重试 ${MAX_RECOVERY_DEPTH} 次，收手`)
          ctx.session.append({
            type: 'notice/message',
            data: { text: `恢复重试达到上限（${MAX_RECOVERY_DEPTH} 次），本轮结束。` },
          })
          return
        }
        ctx.session.append({
          type: 'tool/call',
          data: { callId: recovery.id, name: recovery.name, arguments: JSON.stringify(recovery.args) },
        })
        await executeTool(recovery, depth + 1)
        break
      }
    }
  }

  /**
   * 压缩：往日志里**追加**一条摘要，标记它顶掉 [fromSeq, toSeq]。
   *
   * 注意是追加，不是删除。旧的行一条不少地还在文件里，
   * 只是从此不进模型请求——这就是 harness 的 compaction 路子。
   */
  function compact(fromSeq: number, toSeq: number, summary: string) {
    console.log(`\n=== 压缩：#${fromSeq}~#${toSeq} 折成一条摘要 ===`)
    const seq = ctx.session.append(
      { type: 'assistant/message', data: { text: summary } },
      { op: 'replace', startSeq: fromSeq, endSeq: toSeq },
    )
    console.log(`摘要落成 #${seq}，它顶掉了 #${fromSeq}~#${toSeq}`)
  }

  // ===== 第七课新增：上下文预算 =====

  /**
   * 量一次请求：把这一轮真正要发出去的东西折算成 token。
   *
   * 三个组成部分，对应真身 [token-meter](../../../deepseek-harness/packages/llm/token-meter/src/estimate.ts)
   * 的 `contextBreakdown`：
   *
   * 1. **工具清单**（toolsTokens）——`ctx.tools.schemas()` 序列化后的
   *    JSON Schema。这是最容易被忘掉的一块：两个工具的 schema 就能吃掉
   *    几百 token，而它们**每一轮都在**。
   * 2. **消息**（nodes）——`deriveMessages()` 折出来的历史。
   * 3. **系统提示**（systemTokens）——26 课及之前这里恒 0，因为从来
   *    没有系统提示。本课第一次真的算它：**它不在 messages 里，
   *    但一样花钱。**
   *
   * 只量 messages 不算账——那正是"日志进了请求"的误解。
   */
  function measureRequest(options: GenerateOptions) {
    const budget = ctx.tokenMeter.measure(options.messages, toolsTokens(), systemTokens())
    console.log(
      `[预算] 本次请求 ≈ ${budget.totalTokens} token`
      + `（消息 ${budget.totalTokens - budget.toolsTokens - budget.systemTokens}`
      + ` + 工具清单 ${budget.toolsTokens}`
      + ` + 系统提示 ${budget.systemTokens}`
      + `，窗口 ${CONTEXT_WINDOW}，阈值 ${thresholdTokens()}）`,
    )
  }

  /**
   * 系统提示占多少 token。
   *
   * 26 课这个函数不存在——那一行打印里写死 `+ 系统提示 0`。
   * 真身 `estimate.ts` 给 system 开了一条**不带 BLOCK_OVERHEAD**
   * 的岔路：系统提示序列化成一个纯字符串字段，不是带 type 标签的
   * 内容块。教学版照抄这条岔路，所以只有角色开销没有块开销。
   */
  function systemTokens(): number {
    return Math.ceil(SYSTEM_PROMPT.length / CHARS_PER_TOKEN) + ROLE_OVERHEAD
  }

  /** 触发压缩的绝对 token 数。真身是 `floor(contextWindow × thresholdRatio)`。 */
  function thresholdTokens(): number {
    return Math.floor(CONTEXT_WINDOW * THRESHOLD_RATIO)
  }

  /**
   * 预算驱动：超了就先折历史，再发请求。
   *
   * 第七课的核心。压缩靠一句手写的 `compact(1, 12, '（摘要）…')`——
   * **人肉决定什么时候折、折哪一段**。第七课换成：量一下，超阈值就
   * 自动选一段折掉。
   *
   * 折哪一段的规则照抄真身
   * [selectCompactableRange](../../../deepseek-harness/packages/compaction/compaction-basic/src/region.ts)，
   * 四条红线一条不少：
   *
   * 1. **从尾部往前累加，够 `retainTokens` 就停**——最近的对话原样留着，
   *    因为它们和当前这轮最相关。
   * 2. **从 `#1` 起折**（`keepFromIdx > 1` 才动手）——系统提示在真身
   *    里是 surface 节点 0，永不进区间；教学版没有系统提示，但这条
   *    边界留着：真要加，它必须是第一条。
   * 3. **只折进过请求的行**（`surfaceOp !== undefined`）——`tool/call`
   *    和 `notice/message` 从没进过模型请求，折它们只会让 endSeq 落空。
   * 4. **保不住就整个收手**——连最近的几句都保不住，折掉一切等于清空
   *    历史，比不折更糟。
   *
   * 本课改的是折完之后那一步：摘要不再写死，而是
   * **再问一次模型，让它自己写**（见 summarize）。
   */
  async function compactIfNeeded(options: GenerateOptions) {
    // 口径和 measureRequest 完全一致：**含工具清单和系统提示。**
    // 真身 token-meter 的 `totalTokens = estimateToolsTokens(header) + surfaceTokens`
    // ——工具清单是请求的一部分，压不掉也得算钱。
    const budget = ctx.tokenMeter.measure(options.messages, toolsTokens(), systemTokens())
    if (budget.totalTokens < thresholdTokens()) return

    const lines = ctx.session.list()
    // 只考虑"进过请求"的行——notice 旁白和 tool/call 从没进过，
    // 折它们没有意义，而且 endSeq 会落空。
    const surface = lines.filter((line) => line.surfaceOp !== undefined)

    // 从尾部往前累加，保留最近 retainTokens 个 token。
    // 累加用的是日志行的估价，而阈值判的是请求的估价——
    // 两边同源（都是 tokenMeter），但别忘了 surface 里含 tool/result，
    // 请求里也一样含，口径一致。
    let accumulated = 0
    let keepFromIdx = surface.length
    for (let index = surface.length - 1; index >= 0; index -= 1) {
      const line = surface[index]
      if (line === undefined) break
      accumulated += ctx.tokenMeter.estimateMessage(toMessage(line))
      keepFromIdx = index
      if (accumulated >= RETAIN_TOKENS) break
    }

    // 红线四：保留的部分已经顶到开头，没什么可折的
    if (keepFromIdx <= 1) return

    const from = surface[0]
    const to = surface[keepFromIdx - 1]
    if (from === undefined || to === undefined) return

    console.log(
      `\n[预算告急] 历史 ≈ ${budget.totalTokens} token 超过阈值 ${thresholdTokens()}，`
      + `折掉 #${from.seq}~#${to.seq}，保留最近 ${accumulated} token`,
    )

    // 区间锁（本课接上）：25 课声明了这两条事件却没用，
    // 本课把它们接在"区间定下来"和"摘要落成"两端。
    //
    // 真身叫 `compaction/start` / `compaction/end`，配
    // `assertSelectedSpanStable` + `assertWholeSurfaceUnchanged`：
    // 摘要生成期间（要等一次模型请求，几百毫秒）整个 surface
    // 一条都不许动。教学版的循环是串行 await 的，期间确实
    // 没有别人能插进来——**所以这两条事件现在是纯观测**，
    // 没有断言在背后。但它们的**位置**就是真身的 invariants
    // 所在的位置，看得见。
    ctx.emit('agent/compact-begin', from.seq, to.seq)

    // 摘要由模型写。这一次请求**不过压力阈值**：阈值检查是为了
    // 避免无限压缩，而摘要请求只发一次、发完就完了。
    // 真身 summarizer.ts 里这个请求走的是同一个 `ctx.llm.stream()`，
    // 带 `purpose: 'compaction'` 和独立的 maxTokens。
    const summary = await summarize(from.seq, to.seq)

    const summarySeq = appendSummary(from.seq, to.seq, summary)
    ctx.emit('agent/compact-end', from.seq, to.seq, summarySeq)

    // 折完重新折一遍历史——options 是调用方传进来的引用，
    // 里面装的是旧的 messages，必须原地换掉，否则这一轮
    // 发的还是没折过的请求。
    const before = budget.totalTokens
    options.messages = ctx.session.deriveMessages()
    const after = ctx.tokenMeter.measure(options.messages, toolsTokens(), systemTokens())
    console.log(`[预算] 折完降到 ≈ ${after.totalTokens} token，省了约 ${before - after.totalTokens}`)
  }

  /**
   * 落一条摘要，返回它的 seq。
   *
   * 从 `compact()` 里拆出来，是为了让 `compact-end` 拿到
   * `summarySeq`——25 课的事件签名里就有这个参数，但那时候
   * 没有任何人发这条事件，参数一直是空口许诺。
   */
  function appendSummary(fromSeq: number, toSeq: number, summary: string): number {
    console.log(`\n=== 压缩：#${fromSeq}~#${toSeq} 折成一条摘要 ===`)
    const seq = ctx.session.append(
      { type: 'assistant/message', data: { text: summary } },
      { op: 'replace', startSeq: fromSeq, endSeq: toSeq },
    )
    console.log(`摘要落成 #${seq}，它顶掉了 #${fromSeq}~#${toSeq}`)
    return seq
  }

  /** 工具清单占多少 token。它每一轮都一样，但每一轮都要重新付。 */
  function toolsTokens(): number {
    const schemas = JSON.stringify(ctx.tools.schemas())
    return schemas.length === 0 ? 0 : Math.ceil(schemas.length / 4) + 4
  }

  // ===== 本课新增：让模型自己写摘要 =====

  /**
   * 把 [fromSeq, toSeq] 那段历史交给模型，要回一条摘要。
   *
   * 这是本课的核心。第七课这里是一句写死的话；本课换成一次真实的
   * 模型请求，形状照抄真身
   * [summarizer.ts](../../../deepseek-harness/packages/compaction/compaction-basic/src/summarizer.ts)：
   *
   * 1. **重放要被折掉的那段对话**，末尾追加一条压缩指令。
   *    指令是 user 角色、带 `<summary>` 开闭标签——真身叫
   *    `COMPACTION_INSTRUCTION`，七段式 Markdown 逼出结构化输出。
   * 2. **摘要请求也是一次 `stream()`**。它要过流式协议、要拼装、
   *    要处理 finish——和主循环那次请求用的是同一条管子。
   * 3. **从标签里抽正文**。模型偶尔会在 `<summary>` 前后多说两句
   *    客套话，抽标签比信任整段输出干净。
   *
   * 一次失败（没闭合标签、空摘要）就抛错——**摘要落空比摘要难看
   * 严重得多**：难看只是信息少，落空等于把历史扔了还骗你说折好了。
   */
  async function summarize(fromSeq: number, toSeq: number): Promise<string> {
    // 重放：把要折掉的那段历史原样发给模型，末尾追加压缩指令。
    // 注意这里重放的是**日志行**，不是 deriveMessages() 的产物——
    // 那段历史可能已经被 replace 过，我们要折的是它当前的样子。
    const replayed = ctx.session.list()
      .filter((line) => line.seq >= fromSeq && line.seq <= toSeq && line.surfaceOp !== undefined)
      .map(toMessage)

    const options: GenerateOptions = {
      messages: [
        ...replayed,
        { role: 'user', content: COMPACTION_INSTRUCTION },
      ],
      system: SYSTEM_PROMPT,
      // **摘要请求不带工具清单**：它要的是一段文字，给工具只会
      // 诱导它去调用，而且白付几百 token 的 schema。真身也一样——
      // summarizer 的请求里 tools 是空的。
      maxTokens: SUMMARY_MAX_TOKENS,
      purpose: 'compaction',
    }

    console.log('\n=== 摘要请求：让模型自己写 ===')
    const turn = await stream(ctx, options)
    if (turn.kind !== 'text') {
      throw new Error('摘要请求返回了工具调用——摘要只能是一段文字')
    }

    const summary = extractSummary(turn.text)
    if (summary.length === 0) {
      throw new Error('摘要为空：模型没有在 <summary> 标签里给出内容')
    }
    return summary
  }

  /**
   * 从模型输出里抽出 `<summary>` 标签中的正文。
   *
   * 真身 [summarizer.ts](../../../deepseek-harness/packages/compaction/compaction-basic/src/summarizer.ts)
   * 用 `<compacted-summary>` 开闭标签，外加一层 `CHECKPOINT_PREAMBLE`
   * 把摘要包成"已成事实的背景"。教学版只保留抽标签这一步。
   *
   * 标签没闭合就抛错，**不做宽容兜底**：兜底会把模型的客套话、
   * 复述的指令一起塞进摘要，那正是标签要防的东西。
   */
  function extractSummary(text: string): string {
    const open = text.indexOf(SUMMARY_OPEN_TAG)
    const close = text.indexOf(SUMMARY_CLOSE_TAG)
    if (open === -1 || close === -1 || close < open) {
      throw new Error(`摘要缺少闭合的 ${SUMMARY_OPEN_TAG} 标签：${text}`)
    }
    return text.slice(open + SUMMARY_OPEN_TAG.length, close).trim()
  }

  /** 重放：日志是唯一事实来源，屏幕上的字早没了，日志还在。 */
  function replay() {
    const lines = ctx.session.list()
    console.log(`\n=== 日志全量（${lines.length} 条）===`)
    for (const line of lines) {
      console.log(`#${line.seq} [${line.type}] ${describe(line)}${opNote(line)}`)
    }

    const messages = ctx.session.deriveMessages()
    console.log(`\n=== 模型看到的历史（折叠后 ${messages.length} 条）===`)
    for (const message of messages) {
      console.log(`[${message.role}] ${message.content}`)
    }
  }

  /** 压缩标记只在日志里可见，模型那一侧看不到。 */
  function opNote(line: SessionLine): string {
    const op = line.surfaceOp
    if (op === undefined || op === 'append') return ''
    return `　← replace #${op.startSeq}~#${op.endSeq}`
  }

  function describe(line: SessionLine): string {
    switch (line.type) {
      case 'user/message':
        return line.data.content
      case 'assistant/message':
        return line.data.text
      case 'tool/call':
        return `${line.data.name}(${line.data.arguments})`
      case 'tool/result':
        return line.data.isError ? `失败：${String(line.data.value)}` : String(line.data.value)
      case 'notice/message':
        return line.data.text
    }
  }
}

/** 把一条消息行翻译成计价器认识的形状。 */
function toMessage(line: SessionLine): { role: 'user' | 'assistant' | 'tool'; content: string } {
  switch (line.type) {
    case 'user/message':
      return { role: 'user', content: line.data.content }
    case 'assistant/message':
      return { role: 'assistant', content: line.data.text }
    case 'tool/result':
      return { role: 'tool', content: String(line.data.value) }
    case 'tool/call':
      return { role: 'assistant', content: line.data.name }
    case 'notice/message':
      return { role: 'assistant', content: line.data.text }
  }
}

/**
 * 流式消费：每收到一片就打印，同时把碎片拼回整块。
 *
 * 和第 09 课的 `for await` 打印相比，这里多了一件事：
 * **打印和拼装同时进行。** 用户看到字一个个蹦出来（体验），
 * 日志拿到的是拼好的完整块（正确性）——两者不冲突，
 * 因为 text-delta 的拼接就是字符串相加，来一片加一片。
 *
 * 注意 `process.stdout.write` 而不是 `console.log`：
 * log 每次调用都自带换行，会把一行字拆成很多行。
 * 流式的要点就是**不换行**，直到块结束。
 *
 * `[模型回答]` 这个标签也在本函数里打，而且只在第一片正文到来时
 * 打一次。标签是"事前"的：它得和正文出现在同一行，事后再补
 * 就只能另起一行贴在后面，读起来像是另一个句子。
 */
async function stream(ctx: Context, options: GenerateOptions): Promise<ModelTurn> {
  // index → 已拼接的文本/参数
  const texts = new Map<number, string>()
  const calls = new Map<number, { id: string; name: string; arguments: string }>()
  // 这一轮有没有往屏幕上写过正文？工具调用那一轮一个字都不写，
  // 结尾就不能补换行——否则会多出一个空行。
  // reasoning-delta 不算正文：它没有标签，也不参与换行判断。
  let wroteText = false
  // 这一轮真花了多少 token。**只有真模型会给出非零的数**——
  // mock 的 usage 是写死的 10/len，那是给教学版凑形状用的，
  // 不能当账。这就是"账单要靠 response 的 usage 分"的意思。
  let spent: Usage = { inputTokens: 0, outputTokens: 0 }

  for await (const chunk of ctx.llm.stream(options)) {
    switch (chunk.type) {
      case 'text-delta':
        texts.set(chunk.index, (texts.get(chunk.index) ?? '') + chunk.text)
        // 第一片正文先亮标签，正文跟在它后面一个字一个字蹦出来
        if (!wroteText) {
          process.stdout.write('[模型回答] ')
          wroteText = true
        }
        process.stdout.write(chunk.text)
        break
      case 'reasoning-delta':
        // 思考过程：本课的假模型不产出它，但真模型会。
        // 打印出来让"流式"这件事更明显——它是先于正文出现的。
        process.stdout.write(chunk.text)
        break
      case 'tool-call-delta': {
        const existing = calls.get(chunk.index) ?? { id: chunk.id, name: '', arguments: '' }
        // name 可能只在第一条 delta 上出现
        if (chunk.name !== undefined) existing.name = chunk.name
        existing.arguments += chunk.argumentsDelta
        calls.set(chunk.index, existing)
        break
      }
      case 'block-end':
        if (chunk.block.type === 'tool-call') {
          // 工具参数拼完了，这里就是"模型说完话了"的时刻
          process.stdout.write('\n')
          reportUsage(options.purpose, spent)
          return { kind: 'tool-call', id: chunk.block.id, name: chunk.block.name, args: parseArgs(chunk.block.arguments) }
        }
        break
      case 'usage':
        spent = { inputTokens: chunk.usage.inputTokens, outputTokens: chunk.usage.outputTokens }
        break
      case 'finish':
        break
      default:
        break
    }
  }

  const text = [...texts.entries()].sort(([a], [b]) => a - b).map(([, value]) => value).join('')
  // 正文逐字打完，补一个换行，让后面的 === 用户说 === 从新行开始
  if (wroteText) process.stdout.write('\n')
  // 分账放在 return 之前：不管这一轮是说话还是调工具，账单都要报。
  // 真模型的 usage 在流末尾才来（message_delta），而 block-end
  // 可能先到——所以 text 分支必须在这里报，不能只在 tool-call
  // 那条路径上报。
  reportUsage(options.purpose, spent)
  return { kind: 'text', text }
}

/**
 * 上一课的 `collect(stream)` 长这样：
 *
 * ```ts
 * async function collect(stream: AsyncIterable<StreamChunk>): Promise<ModelTurn> {
 *   for await (const chunk of stream) { texts.set(chunk.index, ...) }
 *   return { kind: 'text', text: ... }
 * }
 * ```
 *
 * 它和上面这个函数的唯一区别：收完所有 chunk 才返回，
 * 所以手里没有任何东西可打——只能等整句话到齐再显示。
 * 流式和非流式的分界线**不在协议，在消费时机**：
 * 协议两边一模一样（都是 StreamChunk），差别只在
 * "我是在 yield 的那一刻用它，还是在流结束之后用它"。
 */

/**
 * 把一次请求真实花掉的 token 报出来，按用途分开。
 *
 * 前 26 课没有这个函数——账本上从来没有"真花了多少"这一栏。
 * 假模型的 usage 是 provider 里写死的 `10 / len`，那是给教学版
 * 凑形状用的，照它记账等于记了个假数。**只有真模型的 response
 * 会给出账单**，而且只在流末尾来一次（见 stream() 的
 * `case 'usage'`）。
 *
 * 为什么要按 `purpose` 分开？因为两种请求付的是同一份钱，
 * 记的却是两本账：
 * - `generate`——用户看得见的那一轮，是交互成本；
 * - `compaction`——用户看不见的那一次，是维护开销。
 *
 * 混在一起，"压缩一次多少钱"这个问题就永远答不出来。
 *
 * 真身在这里走得更远：`purpose` 会变成请求头
 * `x-deepseek-harness-compact: 1`（adapter.ts:130），
 * 服务端据此分账。教学版只在日志里分——但分账这件事本身
 * 从第一课起就是刚需，不是锦上添花。
 *
 * 为什么放在模块作用域而不是 apply() 里面：调用它的是模块级的
 * `stream()`，那是第 09 课就从 apply 里拆出去的纯函数。
 * 它只做一件事——打一行字，不碰 ctx。
 */
function reportUsage(purpose: GenerateOptions['purpose'], spent: Usage): void {
  const label = purpose === 'compaction' ? '压缩' : '对话'
  console.log(
    `[${label}账] 本次真实花费：输入 ${spent.inputTokens} + 输出 ${spent.outputTokens}`
    + ` = ${spent.inputTokens + spent.outputTokens} token`,
  )
}

/** 解析工具参数；解析失败时返回空对象——校验层会给出准确报错。 */
function parseArgs(json: string): Record<string, unknown> {
  try {
    const parsed: unknown = JSON.parse(json)
    return typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)
      ? parsed as Record<string, unknown>
      : {}
  } catch {
    return {}
  }
}

/**
 * 连续重复检测。
 *
 * 记录上一次调用的身份（工具名 + 规范化参数），和这次的比一比：
 * 一样就连贯计数 +1，不一样就重新从 1 开始。
 *
 * 真身 repeat-tool-reminder 比这讲究得多——它深排序 JSON 再序列化，
 * 所以 `{a:1,b:2}` 和 `{b:2,a:3}` 算同一次调用；还支持 include/exclude
 * 通配符和分级阈值。教学版只保留那个核心判断：**同样的动作连续做，
 * 就是没有进展。**
 */
function observeRepeat(name: string, argsJson: string): number {
  const key = `${name}(${argsJson})`
  const count = lastCallKey === key ? lastCallCount + 1 : 1
  lastCallKey = key
  lastCallCount = count
  return count
}

/** 上一次调用的身份，见 observeRepeat。 */
let lastCallKey = ''
/** 它已经连续重复了几次。 */
let lastCallCount = 0

/**
 * 把任意异常描述成一句人能看懂的话。
 *
 * `catch (error)` 收到的是 `unknown`——TypeScript 不允许你直接
 * `.message`。先收窄到 Error，剩下的用 String() 兜底。
 * 注意这里**不重新抛出**：到了这一层，任何异常都是"工具失败"，
 * 都要变成模型能看见的一句话。
 */
function describeError(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

import type { Context } from '@deepseek-ai/cordis'
import { Llm, type GenerateOptions, type StreamChunk } from './llm.ts'

export function textResponse(text: string): StreamChunk[] {
  return [
    { type: 'block-start', index: 0, blockType: 'text' },
    ...Array.from(text, (char): StreamChunk => ({ type: 'text-delta', index: 0, text: char })),
    { type: 'block-end', index: 0, block: { type: 'text', text } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: text.length } },
    { type: 'finish', reason: { kind: 'stop' } },
  ]
}

export function toolCallResponse(id: string, name: string, args: object): StreamChunk[] {
  const argumentsJson = JSON.stringify(args)
  return [
    { type: 'block-start', index: 0, blockType: 'tool-call' },
    { type: 'tool-call-delta', index: 0, id, name, argumentsDelta: argumentsJson.slice(0, 5) },
    { type: 'tool-call-delta', index: 0, id, argumentsDelta: argumentsJson.slice(5) },
    { type: 'block-end', index: 0, block: { type: 'tool-call', id, name, arguments: argumentsJson } },
    { type: 'usage', usage: { inputTokens: 10, outputTokens: 5 } },
    { type: 'finish', reason: { kind: 'tool-calls' } },
  ]
}

/**
 * 每片之间的间隔，毫秒。
 *
 * 不设成 0 的原因：生成器的 `yield` 之间如果没有 await，
 * 整个流会在**同一个 tick 里全部吐完**，消费方的 `for await`
 * 一次都等不到——那就不叫流式，叫批量。
 * 一个 `await sleep(0)` 就足以把控制权交回事件循环，
 * 但那样眼睛看不出来。这里故意放慢，让你在终端里看见字一个个来。
 */
const CHUNK_DELAY_MS = 60

/** 让出事件循环，等 `ms` 毫秒。 */
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => { setTimeout(resolve, ms) })
}

export const name = 'llm-mock'

export class MockAdapter extends Llm {
  private cursor = 0

  constructor(
    ctx: Context,
    private script: (StreamChunk[] | ((options: GenerateOptions) => StreamChunk[]))[],
  ) {
    super(ctx)
  }

  async *stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const entry = this.script[this.cursor]
    if (!entry) throw new Error('MockAdapter: 剧本用完了')

    // 两种条目的寿命不同，这是本课的关键设计：
    // 函数条目是"常驻大脑"——每一轮都重新问它一次，像真模型那样只看当前请求做决策；
    // 静态条目是一次性剧本——读过就翻页，第二次 stream 就取不到了。
    if (typeof entry !== 'function') this.cursor += 1

    const chunks = typeof entry === 'function' ? entry(options) : entry
    for (const chunk of chunks) {
      // 每片之前等一等。真模型的延迟来自网络和推理，
      // 我们没法真等，但**必须等**——否则流式协议是假的。
      await sleep(CHUNK_DELAY_MS)
      yield chunk
    }
  }
}

/**
 * 假模型的"大脑"：看用户输入决定这一轮说什么。
 *
 * 真模型是靠训练数据学会"什么时候该调工具"的；我们没法训练，
 * 就用 if 把同样的决策写死。重点不在这段逻辑，而在于
 * **它输出的形状和真模型一模一样**——消费方完全感知不到差别。
 *
 * 注意签名收的是 GenerateOptions（整个请求），不是一句字符串：
 * 真模型看的是全部 messages，我们只看最后一条——至于是谁说的，
 * 在"请求即历史"之后已经不重要了，压缩摘要也是一条历史。
 */
export function decide(options: GenerateOptions): StreamChunk[] {
  const input = options.messages.at(-1)?.content ?? ''
  // 摘要请求：最后一条是压缩指令。先认它——指令里也可能出现
  // "天气""算"这些词，被下面的分支截走就永远拿不到摘要了。
  if (input.includes('compaction engine')) {
    return textResponse(buildSummary(options.messages))
  }
  // 工具结果又喂回来了：这次该说人话了
  if (input.includes('°C')) {
    return textResponse(`${input}。出门看情况带把伞。`)
  }
  // 恢复路径：模型看见了**失败**的工具结果（isError: true）。
  // 上一课走到这里就只剩 default 分支——模型压根不知道刚才失败了，
  // 只会顺着自己的思路说下一句。本课它能看见失败，于是补上漏掉的参数重试。
  if (input.includes('必填项')) {
    return toolCallResponse('call-3-fix', 'calc', { a: 7, b: 6, op: '*' })
  }
  if (input.includes('刚才')) {
    // 只有模型能看见摘要时才答得上来；原始记录被 replace 顶掉之后就看不到了
    const summary = options.messages.find((message) => message.content.includes('## Primary Request'))
    if (summary) return textResponse('你问了我北京天气、让我算 7*6，还打了个招呼。')
    return textResponse('我没有历史记忆，每次请求只带当前这一句。')
  }
  if (input.includes('北京')) {
    return toolCallResponse('call-1', 'get_weather', { city: '北京' })
  }
  if (input.includes('天气')) {
    return toolCallResponse('call-2', 'get_weather', { city: '北京' })
  }
  // 新增：模型"选"了另一个工具。它不需要认识 calc 的实现，
  // 只要注册表里有这个名字，loop 就能把它调起来。
  if (input.includes('算') || input.includes('+')) {
    // 注意这里**故意漏了 op**：模型不是永远正确的，漏参数是最常见的错。
    // 漏掉的参数会被第 11 课的校验器拦住，错误信息原样喂回给模型。
    return toolCallResponse('call-3', 'calc', { a: 7, b: 6 })
  }
  // 工具结果又喂回来了：算数结果是 "7 * 6 = 42" 这种形状。
  // 注意上面那句不能写成 includes('*')——那会把结果也当成"要算数"。
  if (/^[\d.]+\s*[-+*/]\s*[\d.]+\s*=/.test(input)) {
    return textResponse(`算好了：${input}`)
  }
  return textResponse(`我不知道怎么回答"${input}"，但我可以查天气、也会算数。`)
}

export function apply(ctx: Context) {
  ctx.plugin(MockAdapter, [decide])
}

/**
 * 假模型的"摘要大脑"：读重放的那段历史，产出带 `<summary>` 标签的
 * 结构化摘要。
 *
 * 真模型是靠指令里的七段式模板学会分门别类的；我们没法训练，
 * 就用 if 把同样的结构写死。重点不在这段拼字符串的逻辑，而在
 * **它输出的形状和真模型一模一样**：开标签、Markdown 小节、
 * 闭标签——消费方的 `extractSummary()` 感知不到差别。
 *
 * 注意它读的是整个 messages（含最后那条压缩指令），不是最后一句：
 * 摘要的内容必须来自被折掉的那段对话，这是"压缩"和"瞎编"的分界线。
 */
function buildSummary(messages: readonly { readonly role: string; readonly content: string }[]): string {
  const history = messages.slice(0, -1)
  const asked = history.filter((message) => message.role === 'user').map((message) => message.content)
  const results = history.filter((message) => message.role === 'tool').map((message) => message.content)
  const failed = results.filter((result) => result.includes('必填项'))

  const lines = [
    '<summary>',
    '## Primary Request and Intent',
    ...asked.map((question) => `- 用户问了：${question}`),
    '',
    '## Current Work',
    ...results.map((result) => `- 工具返回：${result}`),
    failed.length > 0 ? '- 一次 calc 调用漏了 op 参数，被校验器拦下，补上后成功' : '',
    '',
    '## Next Step',
    '- 回答用户"刚才我问了什么"，依据上面的摘要',
    '</summary>',
  ]
  return lines.filter((line) => line !== '').join('\n')
}

import type { Context } from '@deepseek-ai/cordis'
import { Service } from '@deepseek-ai/cordis'
import Schema from '@deepseek-ai/schemastery'

declare module '@deepseek-ai/cordis' {
  interface Events {
    /**
     * 目录加载器扫完一个目录，往 cordis 里加了一批插件。
     * @param dir - 被扫描的目录（相对路径）。
     * @param count - 从这个目录里加载了几个插件。
     * @mode emit
     */
    'plugin-directory/loaded'(dir: string, count: number): void
  }
}

/** 一个目录里的插件清单。 */
export interface DirectoryManifest {
  /** 这个目录是干什么的，出现在启动日志里。 */
  readonly purpose: string
  /** 插件文件列表，相对本目录。 */
  readonly plugins: readonly string[]
}

/** 插件配置：加载哪个目录。 */
export interface Config {
  /** 目录路径，相对 cordis.yml 所在位置。 */
  root: string
}

/** 同名 schema 给 Cordis 看：运行前验证，缺的补默认值。 */
export const Config: Schema<Config> = Schema.object({
  root: Schema.string().default('.'),
})

/**
 * 目录加载器：扫一个文件夹，把里面的插件一个个递给 cordis。
 *
 * 本课的主题。`ctx.loader.create()` 一次只认一个文件，
 * 而一个能力（比如"工具"）通常长在一个文件夹里。
 * 这个 Service 把"文件夹"变成加载单位。
 */
export abstract class PluginDirectory extends Service {
  constructor(ctx: Context) { super(ctx, 'pluginDirectory') }

  /**
   * 加载一个目录。
   * @param dir - 目录路径，相对 cordis.yml 所在位置。
   * @returns 从这个目录里加载了几个插件。
   */
  abstract load(dir: string): Promise<number>
}

/**
 * Service Provider：读 manifest.ts，逐个 ctx.loader.create。
 *
 * 为什么不直接 `readdirSync` 扫文件？因为**显式清单比目录扫描安全**：
 * 一个 `_backup.ts`、一个临时 `test.ts` 都会被扫进来，而它们可能
 * 不是插件，或者是不该现在加载的插件。harness 真身的
 * packages/ 也是靠 package.json 的 exports 声明，不是扫文件名。
 */
export class MapPluginDirectory extends PluginDirectory {
  async load(dir: string): Promise<number> {
    const manifestUrl = new URL(`${dir.replace(/\/$/, '')}/manifest.js`, this.ctx.baseUrl)
    const manifest = (await import((globalThis as any).__DSH_MANIFEST__ ?? manifestUrl.href)) as { default: DirectoryManifest }

    let count = 0
    for (const plugin of manifest.default.plugins) {
      const url = new URL(`${dir.replace(/\/$/, '')}/${plugin.replace(/\.ts$/, '.js')}`, this.ctx.baseUrl)
      await this.ctx.loader.create({ name: url.href })
      count += 1
    }

    this.ctx.emit('plugin-directory/loaded', dir, count)
    return count
  }

  /**
   * 插件启动钩子：本 fiber 激活后才跑，此时服务已经能从 ctx 上取到。
   *
   * 为什么不在 `apply()` 里直接 `await ctx.pluginDirectory.load()`？
   * 因为 `ctx.plugin(X)` 只是**登记**了服务，要等这个插件的 fiber
   * 真正激活（ACTIVE）之后，`ctx.pluginDirectory` 才取得出来。
   * 在 apply 里伸手，只会拿到
   * `cannot get property "pluginDirectory" without inject`。
   *
   * 这个钩子的调用时机正好：apply 跑完、fiber 就绪。
   */
  async *[Service.init]() {
    yield () => {}
    await this.load(this.#root)
  }

  /** 要加载的目录，由 apply 从配置里写进来。 */
  #root = '.'

  /** 记录要加载的目录。 */
  setRoot(root: string) {
    this.#root = root
  }
}

/**
 * 应用入口：登记服务，把配置里的目录记下来。
 *
 * 真正的加载发生在 `[Service.init]` 钩子里——那时本插件的 fiber 已激活，
 * `ctx.pluginDirectory` 取得出来，而且能安全地往 loader 里添新条目。
 */
export function apply(ctx: Context, config: Config) {
  ctx.plugin(MapPluginDirectory)
  ctx.reflect.get('pluginDirectory', false)?.setRoot(config.root)
}

import type { Context } from '@deepseek-ai/cordis'
import { Tools, type ToolSchema } from './tools.ts'
import type { ToolArgs, ToolDefinition, ToolResult } from './define-tool.ts'

export const name = 'tools-registry'

/**
 * Service Provider：一个基于 Map 的工具注册表。
 *
 * register() 是第 02 课的"注册即效果"：注册方插件一卸载，
 * 这个工具定义自动从表里消失。
 */
class MapTools extends Tools {
  private readonly definitions = new Map<string, ToolDefinition>()
  private counter = 0

  register(definition: ToolDefinition): () => void {
    // ctx.effect 是"本插件卸载时自动执行"的注册点
    return this.ctx.effect(() => {
      this.definitions.set(definition.name, definition)
      // 注册即广播：谁想知道"现在有哪些工具"，挂这个事件就行
      this.ctx.emit('tools/change')
      return () => {
        this.definitions.delete(definition.name)
        this.ctx.emit('tools/change')
      }
    }, `tools.register(${definition.name})`)
  }

  get(name: string): ToolDefinition | undefined {
    return this.definitions.get(name)
  }

  list(): ToolDefinition[] {
    return [...this.definitions.values()]
  }

  schemas(): ToolSchema[] {
    // 只挑三个字段——execute 留在本地，不随请求出门
    return [...this.definitions.values()].map(({ name, description, parameters }) => ({
      name,
      description,
      parameters,
    }))
  }

  async call(name: string, args: unknown, signal?: AbortSignal): Promise<ToolResult> {
    const definition = this.definitions.get(name)
    const callId = `call-${++this.counter}`
    if (!definition) {
      return { ok: false, callId, name, error: `工具不存在：${name}` }
    }
    try {
      // 先看调用方是不是已经到点了。真身里这一步由 timeout-policy 的
      // 包装器做——它把 exec.signal 换成自己的期限，工具只需要
      // honor 传进来的 signal，不需要知道期限是谁定的。
      if (signal?.aborted) {
        return { ok: false, callId, name, error: '调用已取消' }
      }
      const value = await definition.execute((args ?? {}) as ToolArgs, { callId, signal })
      // execute 回来了，但调用方可能已经等不下去走了。
      // 一个 honor signal 的工具会在 abort 时尽快抛出/返回，
      // 但**不保证**——所以这里再查一次，宁可丢弃结果也不假装成功。
      if (signal?.aborted) {
        return { ok: false, callId, name, error: '调用已取消' }
      }
      return { ok: true, callId, name, value }
    } catch (error) {
      // abort 导致的异常也是失败，不是 bug：换个说法，别把 stack 摔用户脸上
      if (signal?.aborted) {
        return { ok: false, callId, name, error: '调用已取消' }
      }
      return { ok: false, callId, name, error: error instanceof Error ? error.message : String(error) }
    }
  }
}

export function apply(ctx: Context) {
  ctx.plugin(MapTools)
}

/**
 * 真模型 provider：DeepSeek Messages 协议。
 *
 * 本课的主题。前 26 课一直用 mock-provider——一个假模型，
 * 用 if 把"什么时候该调工具"写死。它输出的 chunk 形状
 * 和真模型一模一样，所以 agent loop 一行都不用改。
 *
 * 现在把那个 if 换成一次真正的 HTTP 请求。**换掉的只有
 * 一个文件**：`mock-provider.ts` 和 `real-provider.ts`
 * 实现的是同一个 `Llm` 抽象类，`main.ts` 里的 `stream()`
 * 看不见任何差别。
 *
 * 这就是第 01 课那个 capability seam：Service Definition
 * （llm.ts）/ Service Provider（本文件 + mock）/ Consumer
 * （main.ts）三个角色。Provider 换了，Consumer 不动。
 */

import type { Context } from '@deepseek-ai/cordis'
import { Llm, type GenerateOptions, type StreamChunk, type ContentBlock } from './llm.ts'
import type { ChatMessage } from './session.ts'

export const name = 'llm-deepseek'
export const inject = ['llm']

/**
 * DeepSeek 的公开端点——**只是根**。
 *
 * 真身 [llm-deepseek/src/config.ts](../../../deepseek-harness/packages/llm/llm-deepseek/src/config.ts#L106)
 * 里这个常量叫 `PUBLIC_BASE_URL`，而且优先读 `$DEEPSEEK_BASE_URL`
 * ——**从可信的环境层读，不从进程随便读**。教学版简化：只有
 * 这一个常量，要换端点就改这里（或者自己 export 一个）。
 *
 * 注意它**不含路径**。真身
 * [adapter.ts:120](../../../deepseek-harness/packages/llm/llm-deepseek/src/adapter.ts#L120)
 * 是 `fetch(`${messagesApiRoot(connection.baseURL)}/messages`)`——
 * baseURL 只是根，`/messages` 要自己拼。POST 到根上会拿到 404，
 * 而且是个看起来像"端点不通"的 404。
 */
const BASE_URL = 'https://api.deepseek.com/anthropic'

/** 协议路径。真身拼在 baseURL 后面，教学版拼在同一个常量旁边。 */
const MESSAGES_PATH = '/messages'

/**
 * 模型 id。
 *
 * 真身这里有一整份模型目录（`models.ts`），默认两条：
 * `deepseek-flash`（DeepSeek-V41-Flash）和 `deepseek-v4-pro`。
 * 教学版只写死一个 id——但注意它出现在**两个地方**：请求体的
 * `model` 字段，和日志。真身把模型 id 记进 durable replay state，
 * 就是为了事后能查清"这一轮用的是谁"。
 *
 * 为什么不用 `deepseek-chat`？真身目录里没有这个 id。写一个
 * 服务端不认识的模型名，错误要等请求发出去才暴露——
 * 而这种错误在 mock 上永远看不见。
 */
const MODEL = 'deepseek-flash'

/**
 * 请求超时。
 *
 * 真身叫 `streamIdleTimeoutMs`（默认五分钟），而且量的是
 * **流空闲间隔**，不是整个请求的墙钟时间——一个流式请求可能
 * 挂几分钟，但每两片之间不能静默太久。教学版简化成总超时：
 * 一次请求超过这个数就断开。宁可少一个功能，不要少一个上限。
 */
const REQUEST_TIMEOUT_MS = 60_000

/** 读 API Key 的环境变量名。真身默认值也是这个名字。 */
const API_KEY_ENV = 'DEEPSEEK_API_KEY'

// ===== 请求：把我们的 ChatMessage 翻译成 WireMessage =====

/**
 * Messages 协议里的一个内容块。
 *
 * 真身 [wire-types.ts](../../../deepseek-harness/packages/llm/llm-deepseek/src/wire-types.ts)
 * 里这叫 `WireBlock`，有十几种（text / image / tool_use /
 * tool_result / thinking / tool_addition …）。教学版只支持两种：
 * 文本，和工具结果。
 */
type WireBlock =
  | { type: 'text'; text: string }
  | { type: 'tool_result'; tool_use_id: string; content: WireBlock[]; is_error?: boolean }

/** Messages 协议里的一轮对话。 */
interface WireMessage {
  role: 'user' | 'assistant' | 'system'
  content: WireBlock[]
}

/**
 * 递出去的请求体。
 *
 * 照抄真身 `WireRequest` 的一个子集。**`stream` 恒为 `true`**——
 * 我们的 agent loop 从第 09 课起就是流式消费的，没有非流式路径。
 */
interface WireRequest {
  model: string
  stream: true
  max_tokens: number
  messages: WireMessage[]
  system?: string
  tools?: {
    name: string
    description: string
    input_schema: Record<string, unknown>
  }[]
}

/**
 * 把内部消息翻成协议消息。
 *
 * **关键的一步，也是最容易出错的一步。** 我们的 `ChatMessage`
 * 只有 role + content 两个字段，协议的 tool_result 却要一个
 * `tool_use_id`——工具结果必须能对上当初那次调用。
 *
 * 27 课之前这里写死 `'unknown'`：日志里明明存了 callId
 * （`SessionRecordMap['tool/result'].callId`），却没有任何人
 * 读过它。本课把它读出来——`deriveMessages()` 现在会把这个
 * 字段带进 ChatMessage（见 session.ts）。
 *
 * 这就是"接真 API"最容易踩的坑：**你以为的字段一直都在，
 * 只是从来没有人真的读过它。**
 */
export function toWireMessages(messages: readonly ChatMessage[]): WireMessage[] {
  const wire: WireMessage[] = []
  for (const message of messages) {
    const role = message.role === 'tool' ? 'user' : message.role
    const block: WireBlock = message.role === 'tool'
      ? {
        type: 'tool_result',
        tool_use_id: message.callId ?? '',
        content: [{ type: 'text', text: message.content }],
      }
      : { type: 'text', text: message.content }
    const previous = wire.at(-1)
    // 协议要求同一角色的连续消息合并——两条 user 挨着会被拒。
    // 教学版的对话是 user/assistant/user/assistant 交替的，
    // 但压缩摘要之后可能连着两条 user，所以这一步省不掉。
    if (previous !== undefined && previous.role === role) {
      previous.content.push(block)
      continue
    }
    wire.push({ role, content: [block] })
  }
  return wire
}

// ===== SSE：把协议事件流翻译回 StreamChunk =====

/**
 * 从响应体里逐帧读 SSE。
 *
 * SSE 的帧格式：`data: {...}\n\n`。**注意是空行分帧**——
 * 单个换行不够。中间可能夹着 `: heartbeat` 注释行（真身用它
 * 唤醒空闲看门狗），和 `event: xxx` 行。
 *
 * 真身把这个活儿交给 `eventsource-parser` 库。教学版不引依赖：
 * 帧格式简单到不值得一个包，而且**自己写一遍才知道它长什么样**。
 */
async function* readSse(body: ReadableStream<Uint8Array>): AsyncGenerator<Record<string, unknown>> {
  const decoder = new TextDecoder()
  const reader = body.getReader()
  let buffer = ''
  try {
    for (;;) {
      const { done, value } = await reader.read()
      if (done) break
      buffer += decoder.decode(value, { stream: true })
      // 按空行切帧。最后一段可能不完整，留在 buffer 里等下一块。
      let boundary = buffer.indexOf('\n\n')
      while (boundary !== -1) {
        const frame = buffer.slice(0, boundary)
        buffer = buffer.slice(boundary + 2)
        const data = frame.split('\n')
          .filter((line) => line.startsWith('data:'))
          .map((line) => line.slice(5).trim())
          .join('')
        if (data.length > 0) yield JSON.parse(data) as Record<string, unknown>
        boundary = buffer.indexOf('\n\n')
      }
    }
  } finally {
    reader.releaseLock()
  }
}

/** 协议里 `message_start` 携带的初始 usage。 */
interface WireUsage {
  input_tokens?: number
  output_tokens?: number
}

/**
 * 真模型的流：一次 HTTP 请求，一路 SSE 回来。
 *
 * 翻译逻辑照抄真身
 * [translate.ts](../../../deepseek-harness/packages/llm/llm-deepseek/src/translate.ts)。
 * 那是个 166 行的状态机，逐事件校验；教学版保留**骨架和两条
 * 会真的咬人的红线**，砍掉大部分校验：
 *
 * 1. **`message_stop` 之前流不许结束**（真身 `STREAM_CLOSED`）。
 *    网络断了就是这样：半条回答，看起来像完整的。
 * 2. **tool_use 的参数是 JSON 增量拼出来的**（`input_json_delta`），
 *    不是一次性给全的。教学版必须自己拼——这是流式协议
 *    和 mock 之间最大的一处差别。
 *
 * 另外教学版必须自己攒三样东西，因为 `StreamChunk` 的
 * `block-end` 要的是**完整块**，而协议是分片给的：
 * 正文文本、工具的身份（id + name）、usage 两个数。
 */
async function* translateSse(events: AsyncIterable<Record<string, unknown>>): AsyncGenerator<StreamChunk> {
  /** index → 块的完整内容。block-end 要的"完整块"就存在这儿。 */
  const blocks = new Map<number, ContentBlock>()
  /** index → 工具调用的 id 和 name。分两批来：block-start 给身份，delta 给参数。 */
  const identities = new Map<number, { id: string; name: string }>()
  /** index → 已拼接的参数 JSON。 */
  const toolJson = new Map<number, string>()
  const usage = { inputTokens: 0, outputTokens: 0 }
  let sawStop = false

  for await (const event of events) {
    switch (event.type) {
      case 'message_start': {
        // message_start 里就带 usage——**请求还没吐字，
        // 输入的钱已经定了**。真身 updateUsage() 在这儿收
        // input_tokens；output_tokens 要到 message_delta 才有。
        const message = (event.message ?? {}) as Record<string, unknown>
        const initial = (message.usage ?? {}) as WireUsage
        usage.inputTokens = initial.input_tokens ?? 0
        usage.outputTokens = initial.output_tokens ?? 0
        break
      }

      case 'content_block_start': {
        const index = Number(event.index ?? 0)
        const block = (event.content_block ?? {}) as Record<string, unknown>
        if (block.type === 'text') {
          blocks.set(index, { type: 'text', text: String(block.text ?? '') })
          yield { type: 'block-start', index, blockType: 'text' }
          // 有的实现会在 block-start 里就给一段初始正文，转发出去。
          const initial = String(block.text ?? '')
          if (initial.length > 0) yield { type: 'text-delta', index, text: initial }
        } else if (block.type === 'tool_use') {
          const id = String(block.id ?? '')
          const name = String(block.name ?? '')
          identities.set(index, { id, name })
          toolJson.set(index, '')
          yield { type: 'block-start', index, blockType: 'tool-call' }
          // 真身在 block-start 时就吐出 id 和 name：调用方要靠
          // 这两个字段把日志写下来（callId 要对得上 tool_result），
          // 不能等参数拼完。**这里 id 是真的**——协议直接给了。
          yield { type: 'tool-call-delta', index, id, name, argumentsDelta: '' }
        }
        break
      }

      case 'content_block_delta': {
        const index = Number(event.index ?? 0)
        const delta = (event.delta ?? {}) as Record<string, unknown>
        if (delta.type === 'text_delta') {
          const text = String(delta.text ?? '')
          const block = blocks.get(index)
          if (block?.type === 'text') block.text += text
          yield { type: 'text-delta', index, text }
        } else if (delta.type === 'input_json_delta') {
          const argumentsDelta = String(delta.partial_json ?? '')
          toolJson.set(index, (toolJson.get(index) ?? '') + argumentsDelta)
          // id 从 block-start 记下的身份里取，**不是空串**。真身
          // translate.ts:85 在每片增量里都带上 `id: content.id`——
          // 调用方靠它把日志写对，不能等参数拼完才认得出这次调用。
          const identity = identities.get(index)
          yield { type: 'tool-call-delta', index, id: identity?.id ?? '', argumentsDelta }
        }
        break
      }

      case 'content_block_stop': {
        const index = Number(event.index ?? 0)
        const block = blocks.get(index)
        if (block !== undefined) {
          yield { type: 'block-end', index, block }
        } else {
          const identity = identities.get(index)
          yield {
            type: 'block-end',
            index,
            block: {
              type: 'tool-call',
              id: identity?.id ?? '',
              name: identity?.name ?? '',
              arguments: toolJson.get(index) ?? '',
            },
          }
        }
        break
      }

      case 'message_delta': {
        const delta = (event.delta ?? {}) as Record<string, unknown>
        // stop_reason 映射成我们的 finish kind。
        // 真身 stopReason() 是个判别联合 switch，四种已知值，
        // 其余一律 malformed——**协议加新值时不猜**。
        const reason = String(delta.stop_reason ?? '')
        if (reason === 'end_turn' || reason === 'stop_sequence') {
          yield { type: 'finish', reason: { kind: 'stop' } }
        } else if (reason === 'tool_use') {
          yield { type: 'finish', reason: { kind: 'tool-calls' } }
        } else if (reason === 'max_tokens') {
          yield { type: 'finish', reason: { kind: 'max-tokens' } }
        }
        // output_tokens 到这一刻才定：吐了多少字，是吐完才知道的。
        const deltaUsage = (event.usage ?? {}) as WireUsage
        usage.outputTokens = deltaUsage.output_tokens ?? usage.outputTokens
        sawStop = true
        break
      }

      case 'message_stop':
        sawStop = true
        break

      case 'error': {
        const error = (event.error ?? {}) as Record<string, unknown>
        throw new Error(`DeepSeek 报错：${String(error.message ?? JSON.stringify(event))}`)
      }
    }
  }

  // 红线：流断了，但没有 message_stop。
  // 半条回答比没有回答更危险——它看起来是完整的。
  if (!sawStop) throw new Error('流在 message_stop 之前就断了')

  // usage 最后统一吐一次。真身在 message_stop 前吐，而且含
  // cache 读写四类 token——教学版只有输入输出两个数。
  yield { type: 'usage', usage: { inputTokens: usage.inputTokens, outputTokens: usage.outputTokens } }
}

export class DeepSeekAdapter extends Llm {
  constructor(ctx: Context) { super(ctx) }

  async *stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const apiKey = process.env[API_KEY_ENV]
    if (apiKey === undefined || apiKey.length === 0) {
      throw new Error(`没读到 ${API_KEY_ENV}——export 之后再跑，或者回到 mock-provider`)
    }

    const request: WireRequest = {
      model: MODEL,
      stream: true,
      max_tokens: options.maxTokens ?? 1024,
      messages: toWireMessages(options.messages),
      // 清单为空时**整个字段都不发**。真身
      // serialize.ts:156 就是这个写法：`...options.tools === undefined ? {} : {...}`。
      // 空数组和"没有这个字段"在协议里不是一个意思——后者才是"别调工具"。
      ...options.tools === undefined || options.tools.length === 0 ? {} : {
        tools: options.tools.map((tool) => ({
          name: tool.name,
          description: tool.description,
          input_schema: tool.parameters,
        })),
      },
      // 系统提示同理：没有就不发这个字段。真身把 options.system
      // 和历史里的系统提示用空行拼起来，教学版只有一次请求一个来源。
      ...options.system === undefined || options.system.length === 0 ? {} : { system: options.system },
    }

    const abort = new AbortController()
    // 调用方给的 signal 也要 honor：27 课之前这里只有自己的超时，
    // 外面想取消只能干等。真身把 signal 一路传进 fetch。
    const timer = setTimeout(() => { abort.abort() }, REQUEST_TIMEOUT_MS)
    if (options.signal !== undefined) {
      if (options.signal.aborted) abort.abort()
      else options.signal.addEventListener('abort', () => { abort.abort() }, { once: true })
    }
    try {
      const response = await fetch(`${BASE_URL}${MESSAGES_PATH}`, {
        method: 'POST',
        headers: {
          // Messages 协议的鉴权头。真身叫 x-api-key，不是
          // OpenAI 那套 Authorization: Bearer。
          'content-type': 'application/json',
          'x-api-key': apiKey,
        },
        body: JSON.stringify(request),
        signal: abort.signal,
      })

      // HTTP 层就失败了：4xx 多半是 key 不对或余额不足，
      // 5xx 是对方的事。两种情况都不能当"模型说了句怪话"，
      // 要抛出来，让 loop 的失败路径接手。
      if (!response.ok) {
        const text = await response.text().catch(() => '')
        throw new Error(`DeepSeek HTTP ${response.status}：${text.slice(0, 200)}`)
      }
      if (response.body === null) throw new Error('DeepSeek 响应没有 body')

      yield* translateSse(readSse(response.body))
    } finally {
      clearTimeout(timer)
    }
  }
}

/**
 * Provider：有 Key 就注册真模型，没有就**什么都不做**。
 *
 * 为什么不在没有 Key 时抛错？因为本课的课目要能在没有 Key 的
 * 机器上跑完（教学验收就是这个状态）。真身
 * [llm-deepseek-api-key](../../../deepseek-harness/packages/llm/llm-deepseek-api-key/src/index.ts)
 * 的做法是**缺 Key 抛 `MISSING_CREDENTIAL`**——fail loud，因为它
 * 的用户是想要真模型的人。
 *
 * 教学版的折中：缺 Key 时静默不注册，`main.ts` 那边靠
 * **能力对账**（第 20 课那个 reportCapabilities）发现 `llm`
 * 缺了 provider，并打印说明。**同一个 seam，两种失败策略，
 * 差别只在你面对的是学生还是用户。**
 */
export function apply(ctx: Context) {
  if (process.env[API_KEY_ENV] === undefined || process.env[API_KEY_ENV] === '') {
    console.log(`[provider] 没读到 ${API_KEY_ENV}，跳过真模型——本课剩下的部分照样跑（用 mock）`)
    return
  }
  ctx.plugin(DeepSeekAdapter)
  console.log(`[provider] 真模型已注册：${MODEL} @ ${BASE_URL}`)
}

import { Service, type Context } from '@deepseek-ai/cordis'
import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

/**
 * 一条会话记录。`data` 的形状由 `type` 决定。
 *
 * harness 真身里这是 `SessionEventMap`（packages/core/session/src/types.ts 第 281 行），
 * 同样是"一个 type 对应一种 data"的表。
 */
export interface SessionRecordMap {
  /** 用户说了一句话。 */
  'user/message': { content: string }
  /** 模型回答了一轮。 */
  'assistant/message': { text: string }
  /** 模型请求调用一个工具，arguments 是它吐出的原始 JSON 字符串。 */
  'tool/call': { callId: string; name: string; arguments: string }
  /** 工具执行完了，value 是返回值，isError 标记成功失败。 */
  'tool/result': { callId: string; name: string; value: unknown; isError: boolean }
  /** 一条旁白：循环写给自己的提醒，模型看不见。 */
  'notice/message': { text: string }
}

/** 任意一种会话记录。 */
export type SessionRecord =
  | { [K in keyof SessionRecordMap]: { type: K; data: SessionRecordMap[K] } }[keyof SessionRecordMap]

/**
 * 会产生模型可见消息的记录类型。
 *
 * 日志里还有别的行（turn 边界、失败尝试），它们不进模型请求，
 * 只是排查问题时看的痕迹。harness 真身叫 `SurfaceEventType`
 * （packages/core/session/src/types.ts 第 439 行）。
 */
export type SurfaceRecordType = 'user/message' | 'assistant/message' | 'tool/result'

/** 一条记录在"模型能看到的历史"里的落点。 */
export type SurfaceOp =
  /** 追加到末尾：正常路径。 */
  | 'append'
  /** 替换一段已有节点：压缩上下文时用，被替换的行在日志里还在，只是不再进模型请求。 */
  | { op: 'replace'; startSeq: number; endSeq: number }

/**
 * 落盘的一行。
 *
 * 这是判别联合：`switch (line.type)` 会收窄 `line.data` 的类型，
 * 不用写任何断言。写法照抄 harness 真身的 `SessionEvent`
 * （packages/core/session/src/types.ts 第 493 行）——
 * `{ [K in ...]: {...} }[T]` 这层映射就是为了让联合生效。
 */
export type SessionLine = {
  [K in keyof SessionRecordMap]: {
    /** 会话内单调递增的序号，从 1 开始。 */
    readonly seq: number
    /** 写入时刻，Unix 毫秒。 */
    readonly time: number
    readonly type: K
    readonly data: SessionRecordMap[K]
    /** 它怎么进入模型可见历史。只有会产生消息的行带这个字段。 */
    readonly surfaceOp?: K extends SurfaceRecordType ? SurfaceOp : never
  }
}[keyof SessionRecordMap]

declare module '@deepseek-ai/cordis' {
  interface Context { session: Session }

  interface Events {
    /**
     * 会话问世：新起一个文件，或者从磁盘接上一条。
     *
     * 真身 `session/created`（packages/core/session/src/index.ts 第 54 行）
     * 的 `@mode emit`：同步广播，不等不收。它标记的是"这个 session
     * 现在有人负责了"，不是"第一条记录写完了"——头行先落地，
     * 事件后广播，所以监听器伸手就能读到 header。
     * @param session - 刚问世的会话。
     * @param restored - 从磁盘恢复了多少条记录，0 表示新起的。
     * @mode emit
     */
    'session/created'(session: Session, restored: number): void

    /**
     * 一条记录落定：写完盘、进了内存，才会广播。
     *
     * 真身 `session/event`（同文件第 74 行）是 post-commit 的
     * fire-and-forget：**监听器抛异常不会让 append 失败**。
     * 教学版不实现失败遏制——我们的监听器只打印。但这个顺序
     * 不能反：先广播后写盘，监听器读到的东西可能还没落定。
     * @param session - 日志变长的会话。
     * @param line - 刚落定的那一行，和盘上逐字一致。
     * @mode emit
     */
    'session/event'(session: Session, line: SessionLine): void

    /**
     * 落盘关卡：把缓冲里的记录全部推到磁盘，所有监听器并发跑完才返回。
     *
     * 真身 `session/flush`（同文件第 82 行）的 `@mode parallel`——
     * 它是 **await 型**的：调用方等所有监听器都做完。
     * `session-checkpoint-policy` 在 `llm/stream` 构造前、工具
     * body 执行前、`agent/pre-step` 三处 await 它，所以
     * "模型请求发出前日志一定在盘上"这件事是被强制出来的。
     * @param session - 要被推到磁盘的会话。
     * @mode parallel
     */
    'session/flush'(session: Session): Promise<void> | void

    /**
     * 会话入土：文件关闭，进程退出前最后一个可观测的时刻。
     *
     * 真身 `session/disposed`（同文件第 63 行）在会话离开 store
     * 时广播一次。教学版由 launcher 在 `ctx.dispose()` 时触发，
     * 所以监听器必须在这里把手里的东西吐完——过了这村，
     * 进程都要退了，没人再听你说话。
     * @param session - 结束的会话。
     * @mode emit
     */
    'session/disposed'(session: Session): void
  }
}

/**
 * 一条喂给模型的请求消息。
 *
 * 27 课加了 `callId`：`tool/result` 日志行里一直存着这个字段
 * （见 `SessionRecordMap`），但从来没有被读过——直到要接真 API。
 * 协议的 tool_result 必须带 `tool_use_id` 对回当初那次调用，
 * 教学版第一次真的把这个字段读出来用。
 */
export interface ChatMessage {
  readonly role: 'user' | 'assistant' | 'tool'
  readonly content: string
  /** 工具调用/结果的 id。只有 `tool` 角色带。 */
  readonly callId?: string
}

/**
 * Service Definition：把"发生过的事"写进一条只增不减的日志。
 *
 * 这是 harness 的**唯一事实来源**。第 12 课的 agent loop 只在内存里跑，
 * 进程一退全忘了；有了它，任何时候都能把对话重放出来。
 */
export abstract class Session extends Service {
  constructor(ctx: Context) { super(ctx, 'session') }

  /**
   * 追加一条记录。
   * @param record - 记录内容。
   * @param op - 它怎么进入模型可见历史，默认 `'append'`。
   * @returns 分配到的序号。
   */
  abstract append(record: SessionRecord, op?: SurfaceOp): number

  /** 目前为止的全部记录，按 seq 升序。 */
  abstract list(): readonly SessionLine[]

  /**
   * 把日志折叠成模型能看的历史。
   *
   * 只走会产生消息的行；`replace` 标记的行会顶掉它覆盖的那一段。
   * 这就是 harness 的 `deriveMessages()`——每次请求前都重新折一遍，
   * 所以日志和模型看到的东西永远一致。
   */
  abstract deriveMessages(): ChatMessage[]

  /** 磁盘上已经有多少条记录——恢复来的，还是新起的。 */
  abstract readonly restoredCount: number

  /**
   * 把缓冲里的记录全部推到磁盘，然后广播 `session/flush`。
   *
   * 真身里这是"落盘关卡"：`session-checkpoint-policy` 在模型请求
   * 构造前、工具 body 执行前 await 它。教学版的 append 本身就是
   * 同步落盘的，所以这个方法空转——但**事件照发**，因为关卡
   * 的位置比关卡的实现更值得看。
   */
  abstract flush(): void

  /**
   * 结束这个会话：广播 `session/disposed`，交还单写者名额。
   *
   * **幂等**：第二次调用什么都不做。
   */
  abstract dispose(): void

  /**
   * 从磁盘读回一个 session 的全部记录。
   *
   * 第一行是头行（`type: 'session'`），记录格式版本；剩下的是记录行。
   * 版本对不上直接抛错——**拒绝加载比猜着加载安全**。
   * @param file - session.jsonl 的路径。
   * @returns 按 seq 升序的记录。
   */
  static load(file: string): readonly SessionLine[] {
    const text = readFileSync(file, 'utf8')
    const lines = text.split('\n')
      .filter((line) => line.length > 0)
      .map((line) => JSON.parse(line) as SessionFileLine)
    const [header, ...rest] = lines
    if (header.type !== 'session') {
      throw new Error(`session 文件第一行必须是头行，实际是 ${String(header.type)}`)
    }
    if (header.version !== SESSION_FORMAT_VERSION) {
      throw new Error(
        `session 格式版本不匹配：文件是 v${header.version}，本程序只会 v${SESSION_FORMAT_VERSION}`,
      )
    }
    // 剩下的都是记录行；头行在上面已经核对掉了
    return rest.filter(isSessionLine)
  }
}

/** 头行不是记录。 */
function isSessionLine(line: SessionFileLine): line is SessionLine {
  return line.type !== 'session'
}

/**
 * 落盘文件的一行：要么是头行，要么是一条记录。
 *
 * 头行不是记录——它没有 `seq`，只说明"这个文件是什么格式的"。
 * harness 真身在 packages/session/session-persistence-jsonl/src/format.ts
 * 里也叫 `HeaderLine`，`type` 字段值是 `'session'`。
 */
export type SessionFileLine =
  | { type: 'session'; version: number }
  | SessionLine

/** 当前会话日志的格式版本。harness 真身是 `SESSION_FORMAT_VERSION = 4`。 */
export const SESSION_FORMAT_VERSION = 1

/**
 * Service Provider：JSONL 落地。
 *
 * 每行一条 JSON，追加写文件。harness 真身（packages/session/session-persistence-jsonl）
 * 用 zstd 压缩、分代文件名和原子替换，我们保留最核心的那个决定：
 * **append-only，写出去的行永不改写**。
 *
 * 本课（26 课）加的是另外一组真身也有的事：
 *
 * 1. **四个生命周期事件**（`session/created` / `session/event` /
 *    `session/flush` / `session/disposed`）——会话从问世到入土，
 *    每一步都有事件可听，不必去轮询 `list()`。
 * 2. **`session/flush` 是 await 型关卡**——真身叫 `@mode parallel`：
 *    调用方等所有监听器做完。checkpoint-policy 靠它在
 *    "模型请求发出前"强制日志落盘。
 * 3. **单写者**——真身是进程内 claim + 内核 flock（Windows 命名
 *    信号量）。教学版只有进程内 claim，但那个错误必须现在就抛：
 *    两个 JsonlSession 同时写一个文件，交替追加会把彼此的
 *    行从中间劈开，读回来时整份日志都是坏的。
 */
export class JsonlSession extends Session {
  private seq = 0
  private readonly records: SessionLine[] = []
  private readonly file: string
  /** 磁盘上已有多少条记录——恢复来的，还是新起的。 */
  readonly restoredCount: number
  /**
   * 已经广播过 `session/disposed` 了吗。收尾只能发生一次。
   *
   * 为什么不用 `#disposed`：服务是从 `ctx.session` 读的，那是 cordis
   * 的 Proxy——私有字段穿过 Proxy 就读不到了（`get` 拦截器拿到的
   * receiver 不是原对象）。TypeScript 的 `private` 只是编译期的事，
   * 运行时就一个普通属性，Proxy 照样能转发。
   */
  private disposed = false

  constructor(ctx: Context, config: { file: string }) {
    super(ctx)
    this.file = join(config.file, 'session.jsonl')
    mkdirSync(dirname(this.file), { recursive: true })

    // 单写者：同一个文件在同一个进程里只许一个 session 持有。
    // 真身在这一步还会去抢内核锁，防的是**另一个进程**——
    // 教学版不跨进程，只拦"自己人打自己人"。
    if (ownedFiles.has(this.file)) {
      throw new Error(`session 文件已被占用：${this.file}（单写者，不能两个实例同时开）`)
    }

    // 恢复：接着磁盘上已有的行往下写，seq 继续往上加
    if (existsSync(this.file)) {
      const existing = Session.load(this.file)
      this.records.push(...existing)
      this.seq = existing.at(-1)?.seq ?? 0
      this.restoredCount = existing.length
    } else {
      this.restoredCount = 0
      // 新文件第一行写头行：以后谁来读这个文件，先核对版本
      appendFileSync(this.file, `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`)
    }

    ownedFiles.add(this.file)
    // 头行已在盘上，事件才可以广播——监听器伸手能读到 header
    this.ctx.emit('session/created', this, this.restoredCount)
  }

  append(record: SessionRecord, op: SurfaceOp = 'append'): number {
    this.seq += 1
    const line = this.toLine(this.seq, record, op)
    this.records.push(line)
    // 追加写：只往文件末尾加字节，不动已有内容
    appendFileSync(this.file, `${JSON.stringify(line)}\n`)
    // 先落盘、后广播：监听器看到的每一行都已经是既成事实
    this.ctx.emit('session/event', this, line)
    return line.seq
  }

  /** 拼一行。`tool/call` 不进模型可见历史——它已经被同一轮的 assistant/message 代表了。 */
  private toLine(seq: number, record: SessionRecord, op: SurfaceOp): SessionLine {
    const time = Date.now()
    switch (record.type) {
      case 'user/message':
        return { seq, time, type: 'user/message', data: record.data, surfaceOp: op }
      case 'assistant/message':
        return { seq, time, type: 'assistant/message', data: record.data, surfaceOp: op }
      case 'tool/result':
        return { seq, time, type: 'tool/result', data: record.data, surfaceOp: op }
      case 'tool/call':
        return { seq, time, type: 'tool/call', data: record.data }
      case 'notice/message':
        return { seq, time, type: 'notice/message', data: record.data }
    }
  }

  list(): readonly SessionLine[] { return this.records }

  /**
   * 折叠日志。
   *
   * `surface` 是一个"模型能看到哪些 seq"的有序列表。
   * 追加就 push；替换就把 [startSeq, endSeq] 那段挖掉、换成新行。
   * 被挖掉的行在日志里一行不少，只是不再进模型请求。
   */
  deriveMessages(): ChatMessage[] {
    const surface: SessionLine[] = []
    for (const line of this.records) {
      const op = line.surfaceOp
      if (op === undefined) continue          // 非消息行：跳过
      if (op === 'append') { surface.push(line); continue }
      // replace：挖掉旧段，在原来的位置插入新行
      const start = surface.findIndex((node) => node.seq === op.startSeq)
      const end = surface.findIndex((node) => node.seq === op.endSeq)
      if (start === -1 || end === -1) continue
      surface.splice(start, end - start + 1, line)
    }
    return surface.map(toChatMessage)
  }

  /**
   * 把整个文件重写一遍。
   *
   * 注意头行得带上——它是文件的一部分，不是记录。
   * 这是本文件里唯一一处"整份重写"的路径，正常写入走的是 append。
   *
   * 教学版的 `append()` 是同步落盘的，所以这个方法空转；
   * 真身有写缓冲，`flush()` 是把缓冲推盘的那一下——
   * 也是 `session/flush` 事件存在的全部理由。
   */
  flush(): void {
    const header = `${JSON.stringify({ type: 'session', version: SESSION_FORMAT_VERSION })}\n`
    const body = this.records.map((line) => `${JSON.stringify(line)}\n`).join('')
    writeFileSync(this.file, header + body)
    void this.ctx.parallel('session/flush', this)
  }

  /**
   * 收尾：广播 `session/disposed`，交还单写者名额。
   *
   * 由剧本末尾显式调用（也由插件的清理钩子兜底）。**幂等**——
   * 第二次调用什么都不做：重复广播会让监听器把一个会话埋两遍。
   * 真身在会话离开 store 时广播一次，同样只此一次。
   */
  dispose(): void {
    if (this.disposed) return
    this.disposed = true
    ownedFiles.delete(this.file)
    this.ctx.emit('session/disposed', this)
  }
}

/** 进程内已被占用的 session 文件。真身在这之上还有一层内核 flock。 */
const ownedFiles = new Set<string>()

/** 把一条消息行翻译成模型请求里的消息。 */
function toChatMessage(line: SessionLine): ChatMessage {
  switch (line.type) {
    case 'user/message':
      return { role: 'user', content: line.data.content }
    case 'assistant/message':
      return { role: 'assistant', content: line.data.text }
    case 'tool/result':
      // callId 从日志里读出来，原样带进请求。真身在这里读的是
      // 同一个字段——tool_result 要靠它和当初的 tool_use 对上。
      return { role: 'tool', content: String(line.data.value), callId: line.data.callId }
    case 'tool/call':
      // 走不到这里：tool/call 没有 surfaceOp，deriveMessages 已经把它过滤掉了
      return { role: 'assistant', content: `${line.data.name}(${line.data.arguments})` }
    case 'notice/message':
      // 走不到这里：旁白没有 surfaceOp，deriveMessages 已经把它过滤掉了
      return { role: 'assistant', content: line.data.text }
  }
}

export function apply(ctx: Context) {
  ctx.plugin(JsonlSession, { file: '.sessions/demo' })
}

import { Service, type Context } from '@deepseek-ai/cordis'
import type { ToolDefinition, ToolParameters, ToolResult } from './define-tool.ts'

declare module '@deepseek-ai/cordis' {
  interface Context {
    tools: Tools
  }
  interface Events {
    /**
     * 有工具注册进来或摘出去。
     *
     * harness 真身（packages/core/tools/src/index.ts 第 208 行）也叫
     * `tools/change`。为什么需要它？因为插件的加载顺序由依赖拓扑决定，
     * **不写插件的人控制不了谁先谁后**。想知道"现在有哪些工具"，
     * 只能等注册表通知，不能在启动时假设它已经满了。
     * @mode emit
     */
    'tools/change'(): void
  }
}

/**
 * Service Definition：工具注册表。
 *
 * 它只知道"工具长什么样、怎么被调用"，不知道任何一个工具的具体实现。
 */
export abstract class Tools extends Service {
  constructor(ctx: Context) {
    super(ctx, 'tools')
  }

  /** 注册一个工具定义，返回的摘除函数随注册方插件的卸载自动执行。 */
  abstract register(definition: ToolDefinition): () => void

  /** 按名字取定义，没有则 undefined。 */
  abstract get(name: string): ToolDefinition | undefined

  /** 当前全部定义，按注册顺序排列。 */
  abstract list(): ToolDefinition[]

  /**
   * 递给模型看的工具清单。
   *
   * 只保留 name / description / parameters 三个字段——
   * `execute` 是本地代码，发给模型没有意义，还可能泄露实现细节。
   * harness 真身 [packages/core/tools/src/index.ts 第 1260 行](../../../deepseek-harness/packages/core/tools/src/index.ts#L1260)
   * 的 `schemas()` 干的就是这件事，注释里那词叫 allowlist（白名单）。
   */
  abstract schemas(): ToolSchema[]

  /**
   * 执行一个工具；任何失败都收进 ToolResult，不往外抛。
   *
   * `signal` 是调用方给的上限：工具应该尽快收手并返回失败。
   * harness 真身（packages/core/tools）在这里是一条 waterfall
   * `tools/execute`，guard/timeout-policy 挂上去的包装器就是
   * 在 `next()` 前后把 signal 换成自己的期限——**注册表本身不认识超时，
   * 超时是别人挂上来的一层。** 教学版把 signal 直接传到底。
   */
  abstract call(name: string, args: unknown, signal?: AbortSignal): Promise<ToolResult>
}

/** 递给模型看的工具描述：三个字段，缺一不可。 */
export interface ToolSchema {
  readonly name: string
  readonly description: string
  readonly parameters: ToolParameters
}

import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from './define-tool.ts'

export const name = 'weather-tool'

// 忘了这行，ctx.tools 会抛 "cannot get property "tools" without inject"
// （第 03 课的规矩：要拿 ctx 上的服务，必须先声明 inject）
export const inject = ['tools']

/**
 * Service Provider 的角色之一：往 ctx.tools 里放一个工具。
 *
 * 真身（packages/web/tool-web/src/search.ts）长这样：
 *   ctx.tools.register(defineTool({ name: 'web_search', ... }))
 * 我们连形状都照抄，只是把网络请求换成了假数据。
 */
export function apply(ctx: Context) {
  ctx.tools.register(defineTool({
    name: 'get_weather',
    description: '查询一个城市的天气。需要城市名。',
    parameters: {
      city: {
        type: 'string',
        required: true,
        description: '城市名，例如 "北京"',
      },
      unit: {
        type: 'string',
        enum: ['celsius', 'fahrenheit'],
        description: '温度单位，默认摄氏度。',
      },
    },
    async execute(args) {
      const city = String(args.city ?? '')
      // Keyless：假数据，不联网
      const table: Record<string, string> = {
        北京: '晴，12°C',
        上海: '小雨，18°C',
      }
      const forecast = table[city] ?? '晴，20°C（默认值）'
      const unit = args.unit === 'fahrenheit' ? '（已换算为华氏）' : ''
      return `${city}：${forecast}${unit}`
    },
  }))
}
